import { createSlice, createAsyncThunk } from "@reduxjs/toolkit";
import {
  api, apiUrl, asList, driveDirectUrl, isMockApi
, atyabLog, ENDPOINTS} from "../api.js";
import { refreshPhrases } from "../../i18n.js";

/* ============================================================
   أطياب الجاسم — مصنع شرائح المنتجات

   الشرائح الثلاث (عطور · عود · بخور) نسخة واحدة بنفس النمط:
   كل شريحة = { list, status, error } + thunk قراءة واحد بشرط
   (لا يُنفَّذ والقائمة ممتلئة) + reducers فارغة + extraReducers.
   لا add ولا update في أي شريحة — القراءة فقط.

   ★ الشريحة تخزّن الخام فقط: gender مفتاح خام، والحجم كما أرسله
     الخادم (فارغ إن غاب — بلا افتراضات سحرية)، والتسميات العربية
     تُبنى عند العرض (الكارت / i18n) لا هنا.
   ★ شارة الخصم تُحسب هنا كنص جاهز: «خصم 19%» بدل «هنا عرض».
   ★ لا فلترة هنا: حتى غير المتوفر يُحفظ ويُعرض زر «احجز الآن».
   ============================================================ */

/* أول قيمة غير فارغة من عدة أسماء محتملة لنفس الحقل */
function pick(r) {
  for (let i = 1; i < arguments.length; i++) {
    const v = r[arguments[i]];
    if (v != null && v !== "") return v;
  }
  return "";
}

function resolveGender(raw) {
  const g = String(raw || "").trim().toLowerCase();
  return g === "men" || g === "women" || g === "unisex" ? g : "unisex";
}

/* نسبة الخصم: من discountType مباشرة، أو محسوبة من السعرين */
function discountPct(r, price, before) {
  const t = String(r.discountType || "").toLowerCase();
  if (t.indexOf("percent") === 0 || t === "%" || t === "نسبة") {
    return Math.round(Number(r.productDiscount) || 0);
  }
  if (before > price && before > 0) {
    return Math.round(((before - price) / before) * 100);
  }
  return 0;
}

function numField(r, keys) {
  for (let i = 0; i < keys.length; i++) {
    const v = r[keys[i]];
    if (v != null && v !== "" && !isNaN(Number(v))) return Number(v);
  }
  return null;
}

/* ★ عقد الباك-اند (مؤكد): المخزون Products.ProductAmount والنشاط IsActive
   هما كل شيء — أي inStock يُحسب (amount > 0 && active) ولا يُخزَّن.
   نلتقط كل التسميات (PascalCase من السيرفر + القديمة للتوافق مع المحاكي).
   ★ عقد الإخفاء/الحذف (2026-10-08): أي عمود إخفاء صريح (IsHidden/Hidden)
   أو عكس الظهور (IsVisible=false) أو حذف (IsDeleted/Deleted) يُسقط المنتج
   من قوائم المتجر نهائياً — المخفي لا يُعرض ولا زر حجز له. تنبيه للباك-اند:
   إن كان الـView لا يورّد أي عمود إخفاء/حذف فزر الإخفاء في برنامج WPF
   لا يمكن أن يعمل على الموقع أبداً — أضيفوا العمود أولاً. */
function amountOf(r) {
  const n = numField(r, ["ProductAmount", "productAmount", "stockQuantity", "StockQuantity", "stock", "Stock", "quantity", "Quantity"]);
  return n == null ? 0 : n;
}

/* أول علامة true من عدة أسماء محتملة (أعمدة الإخفاء/الحذف) */
function flagTrue(r, keys) {
  for (let i = 0; i < keys.length; i++) {
    const v = r[keys[i]];
    if (v === true || v === 1) return true;
    if (v != null && v !== "" && v !== false && v !== 0) {
      const s = String(v).trim().toLowerCase();
      if (s === "true" || s === "1" || s === "yes" || s === "y") return true;
    }
  }
  return false;
}

function isHiddenFlag(r) {
  return flagTrue(r, ["IsHidden", "isHidden", "Hidden", "hidden"]);
}

function isDeletedFlag(r) {
  return flagTrue(r, ["IsDeleted", "isDeleted", "Deleted", "deleted", "is_deleted"]);
}

function isInvisibleFlag(r) {
  const keys = ["IsVisible", "isVisible", "Visible", "visible"];
  for (let i = 0; i < keys.length; i++) {
    const v = r[keys[i]];
    if (v == null || v === "") continue;
    if (v === false || v === 0) return true;
    const s = String(v).trim().toLowerCase();
    if (s === "false" || s === "0" || s === "no" || s === "off") return true;
    return false;
  }
  return false;
}

function activeOf(r) {
  /* ★ الإخفاء/الحذف الصريح يُسقط المنتج قبل النظر إلى IsActive */
  if (isHiddenFlag(r) || isDeletedFlag(r) || isInvisibleFlag(r)) return false;
  const v = r.IsActive != null ? r.IsActive : r.isActive;
  if (v == null) return true;
  if (v === false || v === 0) return false;
  const s = String(v).trim().toLowerCase();
  return !(s === "false" || s === "0" || s === "no" || s === "off");
}

function normalize(raw, opts) {
  const r = raw || {};
  const amount = amountOf(r);
  const active = activeOf(r);
  const hidden = isHiddenFlag(r) || isInvisibleFlag(r);
  const deleted = isDeletedFlag(r);
  /* ★ تعارض بيانات الخادم؟ سطر تشخيصي فقط — الحكم للمخزون والنشاط */
  if (amount > 0 && !active && r.inStock === true) {
    atyabLog("products FLAG-CONFLICT", Number(r.productId) || 0, "amount=" + amount, "inStock=true", "IsActive=false");
  }
  if (amount > 0 && active && r.inStock === false) {
    atyabLog("products FLAG-CONFLICT", Number(r.productId) || 0, "amount=" + amount, "inStock=false(ignored)", "IsActive=true");
  }
  const id = Number(r.productId) || 0;
  const price = Number(r.productFinalPrice) > 0 ? Number(r.productFinalPrice) : Number(r.productPrice) || 0;
  const before = Number(r.productPrice) || 0;
  const hasDiscount = Number(r.productDiscount) > 0 && before > price;
  const pct = hasDiscount ? discountPct(r, price, before) : 0;

  return {
    id: id,
    productId: id,
    productTypeId: Number(r.productTypeId) || 0,
    productTypeName: String(r.productTypeName || "").trim(),
    kind: opts.kind,
    kindGroup: opts.kindGroup,
    kindLabel: opts.kindLabelAr,
    kindLabelEn: String(r.productTypeName || opts.kindLabelEn || "").trim(),
    name: pick(r, "productNameArabic", "productNameAr"),
    nameEn: pick(r, "productNameEnglish", "productNameEn"),
    desc: pick(r, "productTitleArabic", "productTitleAr"),
    descEn: pick(r, "productTitleEnglish", "productTitleEn"),
    story: pick(r, "productTitleArabic", "productTitleAr"),
    storyEn: pick(r, "productTitleEnglish", "productTitleEn"),
    price: price,
    oldPrice: hasDiscount ? before : null,
    saveAmount: hasDiscount ? before - price : 0,
    discountPct: pct,
    discountType: r.discountType || null,
    /* ★ شارة الخصم الجذابة: «خصم 19%» — بدل نص «هنا عرض» الثابت */
    offer: hasDiscount && pct > 0 ? "خصم " + pct + "%" : hasDiscount ? "عرض خاص" : null,
    offerEn: hasDiscount && pct > 0 ? pct + "% OFF" : hasDiscount ? "Special offer" : null,
    sales: Number(r.salesCount) || 0,
    rating: Number(r.ratingAverage) || 0,
    reviews: Number(r.ratingCount) || 0,
    stock: amount,
    inStock: amount > 0 && active,
    isActive: active,
    isHidden: hidden,
    isDeleted: deleted,
    size: r.productSize || "",
    sizeEn: r.productSize || "",
    gender: resolveGender(r.gender),
    searchType: opts.searchType,
    image: driveDirectUrl(r.ImageUrl || r.imageUrl || r.image_url || null),
    placeholder: null
  };
}

/* هل المنتج متاح للشراء الفوري؟ وإلا يُعرض «احجز الآن» */
/* ★ مصدر واحد حسب الباك-اند: التوفر = المخزون (ProductAmount) > 0 مع النشاط (IsActive).
   inStock المحسوبة في normalize هي نفس القاعدة — هنا نعيد التحقق دفاعياً. */
export function isAvailable(p) {
  if (!p) return false;
  if (p.isActive === false) return false;
  const n = Number(p.stock);
  if (!isNaN(n)) return n > 0;
  return p.inStock === true;
}

/* دمج الكمية/النشاط الطازجة في قائمة موجودة (نقية — تُختبر معزولة):
   مصفوفة جديدة، والغائب من الخريطة يُترك كما هو — إلا أن تُعلن
   الخريطة اكتمالها (complete: لقطة كاملة لا جزئية — البند 12)،
   فالغائب يُوسم غير نشط (يختفي من القوائم ويُحجز واتساب). */
export function mergeStock(list, payload) {
  const m = (payload && payload.map) || payload || {};
  const complete = !!(payload && payload.complete);
  if (!Object.keys(m).length && !complete) return list;
  return (list || []).map(function (p) {
    const fresh = m[p.id];
    if (!fresh) {
      if (complete) {
        return Object.assign({}, p, { stock: 0, inStock: false, isActive: false });
      }
      return p;
    }
    const stock = fresh.stock;
    const active = fresh.active;
    return Object.assign({}, p, {
      stock: stock,
      inStock: stock > 0 && active,
      isActive: active
    });
  });
}

/* opts: { sliceName, kind, kindGroup, kindLabelAr, kindLabelEn,
           searchType, endpoint, mockFn } */

/* ★ رحلة المخزون الخفيف مشتركة بين كل الشرائح (البند 12): مهما
   تزامنت التحديثات (عطور/عود/بخور) فطلب شبكة واحد فقط. */
let stockFlight = null;
function fetchLightStock() {
  if (!stockFlight) {
    stockFlight = api.get(apiUrl(ENDPOINTS.productStock)).then(
      function (sres) {
        stockFlight = null;
        return sres;
      },
      function (e) {
        stockFlight = null;
        throw e;
      }
    );
  }
  return stockFlight;
}

export function createProductsSlice(opts) {
  const initialState = { list: [], status: "idle", error: null, lastStockRefresh: 0, stockFailed: false, stockLoading: false };

  const getAll = createAsyncThunk(
    opts.sliceName + "/getAll",
    async function (arg, { rejectWithValue }) {
      try {
        atyabLog("products FETCH", opts.sliceName);
        const raws = isMockApi()
          ? await opts.mockFn()
          : asList((await api.get(apiUrl(opts.endpoint))).data);
        const list = raws
          .map(function (r) {
            return normalize(r, opts);
          })
          .filter(function (p) {
            return p.id > 0;
          })
          .filter(function (p) {
            /* ★ المخفي/المحذوف/غير النشط لا يدخل المتجر أصلاً —
               (النافد النشط يبقى مع زر «احجز الآن») */
            if (p.isActive === false) {
              atyabLog("products HIDDEN-DROPPED", opts.sliceName, p.id);
              return false;
            }
            return true;
          });
        try {
          refreshPhrases(list);
        } catch (e) {}
        return list;
      } catch (err) {
        atyabLog("products FAIL", opts.sliceName);
        const msg = err && err.response && err.response.data && err.response.data.message
          ? err.response.data.message
          : err && err.code === "ECONNABORTED"
            ? "انتهت مهلة الاتصال بالخادم"
            : "تعذّر الوصول إلى الخادم — تحقق من تشغيل الـ API";
        return rejectWithValue(msg);
      }
    },
    {
      condition: function (arg, { getState }) {
        const s = getState()[opts.sliceName];
        if (!s) return true;
        if (s.status === "loading") { atyabLog("products IN-FLIGHT", opts.sliceName); return false; }
        /* ★ #7: force فعلي لإعادة التحميل الكامل — يسمح بالقائمة غير الفارغة */
        if (arg && (arg.force === true || (typeof arg === "object" && arg.force))) return true;
        if (s.list && s.list.length > 0) { atyabLog("products CACHE-HIT", opts.sliceName, s.list.length); return false; }
        atyabLog("products MISS", opts.sliceName);
        return true;
      }
    }
  );

  /* ★ v17-S1: تحديث المخزون الخفيف عند كل دخول (بلا خنق زمني) مع منع
     الطلبات المتزامنة المكررة فقط: رحلة شبكة مشتركة (fetchLightStock)
     + علم stockLoading لكل شريحة. البيانات الثابتة (أسعار/منتجات) لها
     TTL القوائم الكاملة (30د في catalogStock) — لا تبقى للأبد.
     force=true تُستعمل بعد إتمام طلب (نفس المسار). */
  const refreshStock = createAsyncThunk(
    opts.sliceName + "/refreshStock",
    async function (_, { rejectWithValue }) {
      /* ★ البند 15: endpoint المخزون الخفيف أولاً — [{productId, amount,
         isActive}]؛ أي فشل يسقط للمسار القديم (القوائم الكاملة).
         ★ البند 12: رحلة مشتركة بين الشرائح — طلب واحد مهما تزامنت.
         ★ #7: عقد stock — الخفيف قد يعيد مصفوفة بلا حقل complete:
         المصفوفة المجردة = لقطة كاملة (complete=true) لأنها كل المخزون،
         والكائن {items, complete} يحترم complete الصريح. الغائب من لقطة
         كاملة = محذوف/غير نشط (يُوسم stock 0). */
      try {
        const sres = await fetchLightStock();
        const rawData = sres.data;
        const arr = asList(rawData);
        let complete = false;
        if (Array.isArray(rawData)) complete = true;
        else if (rawData && rawData.complete === true) complete = true;
        else if (rawData && Array.isArray(rawData.items)) complete = !!(rawData.complete);
        if (arr.length) {
          const map = {};
          arr.forEach(function (r) {
            const id = Number(r.productId != null ? r.productId : r.ProductId) || 0;
            if (!id || map[id]) return;
            map[id] = {
              stock: r.amount != null ? Number(r.amount) : (r.Amount != null ? Number(r.Amount) : null),
              active: (r.isActive != null ? r.isActive : r.IsActive) !== false
            };
          });
          if (Object.keys(map).length) return { map: map, complete: complete };
        }
      } catch (e) {}
      try {
        const raws = isMockApi()
          ? await opts.mockFn()
          : asList((await api.get(apiUrl(opts.endpoint))).data);
        const map = {};
        raws.forEach(function (r) {
          const id = Number(r.productId) || 0;
          if (!id || map[id]) return;
          map[id] = { stock: amountOf(r), active: activeOf(r) };
        });
        /* ★ القوائم الكاملة لقطة كاملة لشريحتها — الغائب منها منتهٍ */
        return { map: map, complete: true };
      } catch (err) {
        return rejectWithValue("stock-refresh-failed");
      }
    },
    {
      condition: function (force, { getState }) {
        const s = getState()[opts.sliceName];
        if (!s) return true;
        if (s.status === "loading") return false;
        /* ★ v17-S1: المنع للمتزامن فقط (dedupe) — لا خنق زمني للخفيف */
        if (s.stockLoading) { atyabLog("products STOCK-IN-FLIGHT", opts.sliceName); return false; }
        return true;
      }
    }
  );

  const slice = createSlice({
    name: opts.sliceName,
    initialState: initialState,
    reducers: {},
    extraReducers: function (builder) {
      builder
        .addCase(getAll.pending, function (state) {
          state.status = "loading";
          state.error = null;
        })
        .addCase(getAll.fulfilled, function (state, action) {
          state.status = "succeeded";
          /* ★ #7: القوائم الكاملة تحدّث الأسعار والمنتجات الجديدة والنشاط —
             ليست الكمية فقط (mergeStock للخفيف، واستبدال للكامل). */
          state.list = action.payload;
          state.lastStockRefresh = Date.now();
          state.stockFailed = false;
        })
        .addCase(getAll.rejected, function (state, action) {
          state.status = "failed";
          state.error = action.payload || action.error.message;
        })
        /* ★ تحديث المخزون الصامت: يدمج الكمية/النشاط فقط في القائمة
           القائمة (بلا صور ولا نصوص — فلا وميض ولا إعادة تحميل صور).
           صامت تماماً: لا يمسّ status/error، والفشل يُعلَّم (stockFailed)
           بدل التجاهل — فلا شراء على بيانات قديمة بصمت. */
        .addCase(refreshStock.pending, function (state) {
          state.stockLoading = true;
        })
        .addCase(refreshStock.fulfilled, function (state, action) {
          state.list = mergeStock(state.list, action.payload);
          state.lastStockRefresh = Date.now();
          state.stockLoading = false;
          state.stockFailed = false;
        })
        .addCase(refreshStock.rejected, function (state) {
          /* ★ v17-S1: الفشل يُعلَّم ولا يصبح كاشاً — الدخول القادم يعيد المحاولة */
          state.stockLoading = false;
          state.stockFailed = true;
        });
    }
  });

  const EMPTY = [];
  function selectList(state) {
    const s = state[opts.sliceName];
    return (s && s.list) || EMPTY;
  }
  function selectStatus(state) {
    const s = state[opts.sliceName];
    return (s && s.status) || "idle";
  }
  function selectError(state) {
    const s = state[opts.sliceName];
    return (s && s.error) || null;
  }
  function selectById(state, id) {
    const list = selectList(state);
    const num = Number(id);
    for (let i = 0; i < list.length; i++) {
      if (Number(list[i].id) === num) return list[i];
    }
    return null;
  }

  return {
    reducer: slice.reducer,
    getAll: getAll,
    refreshStock: refreshStock,
    selectList: selectList,
    selectStatus: selectStatus,
    selectError: selectError,
    selectById: selectById
  };
}
