/* ============================================================
   أطياب الجاسم (React) — عميل الطلبات (server orders)

   العقد (من Swagger الخلفي):
     POST /api/orders/{customerId} ← { locationId, deliveryMethodId,
       paymentMethodId, couponCode?, customerNote?, termsAccepted:true,
       affiliateCode? + affiliateVisitId? (زيارة الإحالة الصالحة — تُرفق
       فقط إن وُجدت؛ الاستهلاك لطلب واحد والصلاحية للباك) }
       → 200 فاتورة الخادم { orderId, invoiceNumber, statusName,
           currencyCode, items:[{productId,productName,quantity,unitPrice,
           lineTotal}], subtotal, couponCode, discountTotal,
           deliveryFeeTotal, vatRate, vatAmount, grandTotal,
           paymentMethod, paymentStatus, deliveryMethod, deliveryStatus,
           createdAt }
       → 400 بكوبون ساقط لحظة الطلب { valid:false, reason, message }
           (نعرض message ونُسقط الكوبون — لا مفاجأة بالسعر).
      POST /api/orders/{customerId}/quote ← نفس حقول الإنشاء بلا
        termsAccepted (+ offerId? — لا نرسله أبداً: خصم العروض داخل
        FinalPrice) → OrderQuote الملزم { subtotal, itemsCount,
        discount, deliveryFee, vatRate, vatAmount, grandTotal,
        paymentFee, lines[]... } — grandTotal يشمل التوصيل + الضريبة
        + الرسوم وهو نفسه cart_amount في PayTabs. ممنوع offerId +
        couponCode معاً → 400. المعاينة تُربط به؛ فشله لا يمنع الدفع.
      ★ FE20-1 (عقد Backend v20): رد الـquote يحمل أيضاً { quoteId,
      currencyCode, basketVersion, basketFingerprint } — تُحتفظ كما وردت
      وتُرسل expectedBasketFingerprint مع الإنشاء (إلزامي خلفياً).
     GET /api/orders/{customerId}?page=&pageSize= ← { items:[{orderId,
       invoiceNumber,statusName,itemsCount,grandTotal,createdAt}],
       page, pageSize, totalItems, totalPages }
     GET /api/orders/{customerId}/{orderId} ← فاتورة الخادم كاملة.

   ★ كلها بالتوكن + الملكية (403 لغير المالك) عبر authFetch.
   ★ فاتورة الخادم تُطبَّع إلى شكل الطلب المحلي (ordersSlice) حتى
     تعرضها الفاتورة والسجلّ بلا أي فرع جديد في العرض.
   ============================================================ */

import { ENDPOINTS, apiError, atyabLog } from "../redux/api.js";
import { authFetch } from "./auth.js";
import { readValidVisit, REF_FIELD, REF_VISIT_FIELD, REF_CODE_RE } from "./affiliate.js";
import { ATYAB_TERMS } from "../data/appConfig.js";
import { ETA_DAYS } from "../constants/payment.js";

async function readJson(res) {
  const text = await res.text().catch(function () { return ""; });
  if (!text) return null;
  try { return JSON.parse(text); } catch (e) { return null; }
}

function serverMessage(payload, fallback) {
  if (!payload) return fallback;
  if (typeof payload === "string") return payload;
  /* ★ مغلّف الخطأ الموحّد (§0): detail العربية أولاً */
  return payload.detail || payload.message || payload.title || payload.error || fallback;
}

function throwOrder(res, payload) {
  const err = apiError(serverMessage(payload, "استجابة الخادم: " + res.status), res.status);
  err.response = { status: res.status, data: payload };
  throw err;
}

/* ---------- إنشاء طلب في الخادم (معاملة واحدة) ---------- */

export async function createServerOrder(customerId, body, opts) {
  /* ★ إحالة المؤثرين (FE23-F1 — لقطة العملية الملزمة، والتوافق القديم
     عند غياب opts.referral): affiliateVisitId حقل PROPOSED حتى يؤكده
     الباك — تجاهله من عقد قديم آمن. القبول/التجاهل للباك عند الإنشاء —
     لا منطق هنا. */
  const reqBody = {
    locationId: Number(body.locationId),
    deliveryMethodId: Number(body.deliveryMethodId),
    paymentMethodId: Number(body.paymentMethodId),
    couponCode: body.couponCode ? String(body.couponCode) : null,
    customerNote: body.customerNote ? String(body.customerNote) : null,
    termsAccepted: true
  };
  const refDecision = resolveCreateReferral(opts);
  applyReferralToBody(reqBody, refDecision.snapshot);
  /* ★ v17-Q1: ربط الموافقة باللقطة — إصدار السلة وهوية quote المتفق عليهما.
     يرسلهما الفرونت دائماً (إن توفرا)؛ الخادم يرفض الإنشاء من لقطة قديمة. */
  const bv = (opts && opts.basketVersion != null) ? Number(opts.basketVersion)
    : (body && body.basketVersion != null ? Number(body.basketVersion) : null);
  if (bv != null && Number.isFinite(bv)) reqBody.basketVersion = Math.round(bv);
  const qid = (opts && opts.quoteId != null) ? opts.quoteId
    : (body && (body.quoteId != null ? body.quoteId : body.QuoteId));
  if (qid != null && String(qid) !== "") reqBody.quoteId = qid;
  /* ★ FE19-3: المبلغ المتفق عليه من الـquote نفسها — يرسل دائماً (إن توفر).
     الخادم يرفض الإنشاء عند تغيّر المبلغ (grand-total-mismatch) بدل طلب
     صامت بشروط جديدة. حقل إضافي يتجاهله العقد القديم بأمان. */
  const egt = (opts && opts.expectedGrandTotal != null) ? Number(opts.expectedGrandTotal)
    : (body && body.expectedGrandTotal != null ? Number(body.expectedGrandTotal) : null);
  if (egt != null && Number.isFinite(egt) && egt >= 0) reqBody.expectedGrandTotal = egt;
  /* ★ FE20-1 (عقد Backend v20): بصمة السلة المتفق عليها — يشترطها الخادم
     في الإنشاء (expectedBasketFingerprint). من لقطة الموافقة حصراً (لا توليد
     محلي ولا تجاوز). غيابها = رفض صريح هنا قبل أي طلب محكوم بالفشل. */
  const fp = (opts && opts.expectedBasketFingerprint != null) ? String(opts.expectedBasketFingerprint)
    : (body && body.expectedBasketFingerprint != null ? String(body.expectedBasketFingerprint) : "");
  if (!fp) {
    const msg = "تعذّر الإنشاء: بصمة السلة المتفق عليها غائبة — جدّد العرض ووافق مجدداً ثم أكّد.";
    const e = apiError(msg, 400, "missing_fingerprint");
    e.missingFingerprint = true;
    e.response = { status: 400, data: { detail: msg, code: "missing_fingerprint" } };
    throw e;
  }
  reqBody.expectedBasketFingerprint = fp;
  /* ★ #2: عقد العرض المفرد — الخادم يتوقع OfferId واحداً (PascalCase).
     المصدر: body.OfferId ثم opts.offerId ثم التوافق القديم (أول عنصر).
     لا إسقاط تلقائي ولا سعر أساسي صامت — الرفض يُعرض ويطلب موافقة. */
  let singleOffer = 0;
  if (body && body.OfferId != null && Number(body.OfferId)) singleOffer = Number(body.OfferId);
  else if (body && body.offerId != null && Number(body.offerId)) singleOffer = Number(body.offerId);
  else if (opts && opts.offerId != null && Number(opts.offerId)) singleOffer = Number(opts.offerId);
  else if (opts && Array.isArray(opts.offerIds) && opts.offerIds.length) singleOffer = Number(opts.offerIds[0]) || 0;
  else if (body && Array.isArray(body.offerIds) && body.offerIds.length) singleOffer = Number(body.offerIds[0]) || 0;
  if (singleOffer) reqBody.OfferId = Number(singleOffer);
  /* ★ منع التكرار (§11): مفتاح العملية ترويسة Idempotency-Key — يُعاد
     استعماله عند timeout/إعادة الإرسال/التحديث/التبويب الثاني فيرد
     الخادم بالطلب نفسه. بلا مفتاح = بلا ضمان (يُسجَّل تحذير تشخيصي). */
  const headers = {};
  const key = opts && opts.idempotencyKey ? String(opts.idempotencyKey) : "";
  if (key) headers["Idempotency-Key"] = key;
  else {
    try {
      atyabLog("order create WITHOUT idempotency key — duplicate possible");
    } catch (e) {}
  }
  const res = await authFetch(ENDPOINTS.orderCreate(customerId), {
    method: "POST",
    body: reqBody,
    headers: headers
  });
  const payload = await readJson(res);
  if (!res.ok) throwOrder(res, payload);
  return payload;
}

/* ---------- لقطة الإحالة الصريحة لكل عملية إنشاء (FE23-F1) ----------
   القاعدة: الصفحة تلتقط {code, visitId} مرة واحدة للعملية وتمررها هنا
   عبر opts.referral، فتُرسل اللقطة نفسها دون إعادة قراءة خفية من
   localStorage وقت الإرسال. التمييز صريح بين:
     · opts فيه خاصية referral (ولو null) = لقطة العملية الملزمة —
       null تعني «بلا إحالة لهذه العملية» ولا يُقرأ التخزين أبداً.
     · بلا الخاصية = مسار توافقي قديم (إعدادات محفوظة قبل FE23) —
       تُقرأ الزيارة المخزنة كما كان.
   normalizeReferralSnapshot خالصة: كود فاسد/غائب = null (لا يُرسل
   كود فاسد أبداً). applyReferralToBody تطبق اللقطة على الجسم. */

export function normalizeReferralSnapshot(v) {
  const o = v && typeof v === "object" ? v : null;
  if (!o) return null;
  const code = o.code != null ? String(o.code).trim() : "";
  if (!code || !REF_CODE_RE.test(code)) return null;
  const vid = o.visitId != null && String(o.visitId) !== "" ? String(o.visitId) : null;
  return { code: code, visitId: vid };
}

export function resolveCreateReferral(opts) {
  if (opts && Object.prototype.hasOwnProperty.call(opts, "referral")) {
    return { snapshot: normalizeReferralSnapshot(opts.referral), explicit: true };
  }
  let stored = null;
  try {
    stored = readValidVisit();
  } catch (e) {
    stored = null;
  }
  return { snapshot: normalizeReferralSnapshot(stored), explicit: false };
}

export function applyReferralToBody(reqBody, snapshot) {
  const b = reqBody && typeof reqBody === "object" ? reqBody : {};
  const s = normalizeReferralSnapshot(snapshot);
  if (s) {
    b[REF_FIELD] = s.code;
    if (s.visitId) b[REF_VISIT_FIELD] = s.visitId;
    else {
      try {
        delete b[REF_VISIT_FIELD];
      } catch (e) {}
    }
  } else {
    try {
      delete b[REF_FIELD];
    } catch (e) {}
    try {
      delete b[REF_VISIT_FIELD];
    } catch (e) {}
  }
  return s;
}

/* ★ قراءة متسامحة لصدى الإحالة المطبقة في رد الإنشاء (عقد v31 المتوقع):
   الخادم قد يعيد الكود/الزيارة المطبقة فعلاً — تُثبَّت حينها بدل اللقطة
   المرسلة. غيابها = null (لا تخمين). */
export function pickAppliedReferral(payload) {
  const d = payload && typeof payload === "object" ? payload : null;
  if (!d) return null;
  const code = d.affiliateCode != null ? String(d.affiliateCode)
    : (d.affiliate_code != null ? String(d.affiliate_code) : "");
  const vid = d.affiliateVisitId != null ? String(d.affiliateVisitId)
    : (d.affiliate_visit_id != null ? String(d.affiliate_visit_id) : "");
  const applied = d.affiliateApplied != null ? d.affiliateApplied
    : (d.referralApplied != null ? d.referralApplied : null);
  if (!code && !vid && applied == null) return null;
  return { code: code || "", visitId: vid || "", applied: applied };
}

/* ---------- تصنيف رفض الإحالة (FE23-F2) ----------
   رموز منظمة فقط (code/reason/errorCode/error_code) — بلا مسح نصوص.
   العقد المتوقع من v31 (PROPOSED حتى يؤكده الباك — انظر API-CONTRACT-NEXT):
   visit-consumed (استهلكها طلب آخر) · visit-invalid · visit-expired ·
   code-invalid. المخرج null = ليس رفض إحالة. */
const REFERRAL_CONFLICT_TOKENS = {
  affiliate_visit_consumed: "visit-consumed",
  visit_consumed: "visit-consumed",
  referral_consumed: "visit-consumed",
  visit_already_used: "visit-consumed",
  affiliate_visit_already_consumed: "visit-consumed",
  referral_already_used: "visit-consumed",
  affiliate_visit_invalid: "visit-invalid",
  visit_invalid: "visit-invalid",
  referral_invalid: "visit-invalid",
  invalid_visit: "visit-invalid",
  invalid_referral: "visit-invalid",
  affiliate_invalid: "visit-invalid",
  affiliate_visit_expired: "visit-expired",
  visit_expired: "visit-expired",
  referral_expired: "visit-expired",
  affiliate_code_invalid: "code-invalid",
  affiliate_code_not_found: "code-invalid",
  referral_code_invalid: "code-invalid",
  invalid_affiliate_code: "code-invalid",
  affiliate_code_rejected: "code-invalid"
};
export function classifyReferralConflict(data, status) {
  void status;
  const d = data || {};
  const fields = [d.code, d.reason, d.errorCode, d.error_code];
  for (let i = 0; i < fields.length; i++) {
    const v = String(fields[i] || "").trim().toLowerCase();
    if (v && REFERRAL_CONFLICT_TOKENS[v]) return REFERRAL_CONFLICT_TOKENS[v];
  }
  return null;
}

/* ---------- النتيجة الفعلية للإسناد لا الكود المرسل (FE24-F3) ----------
   resolveAttribution(serverPayload, sentSnapshot) خالصة:
   المدخل: رد الإنشاء/التفاصيل + اللقطة المرسلة فعلاً (قد تكون null).
   المخرج: { applied, requested, confirmed, mismatch } —
     · applied: {code, visitId} المطبق فعلاً، أو null.
     · requested: اللقطة المرسلة (للتشخيص/الاستئناف فقط — ليست نتيجة).
     · confirmed: هل حمل الرد حكماً صريحاً (affiliateApplied boolean).
     · mismatch: تناقض يستلزم معالجة صريحة لا حذفاً أعمى.
   القواعد:
     1. affiliateApplied=false → applied=null مؤكداً (إزالة الإسناد) ولو
        وصل code غير فارغ — وجود الكود ليس دليل تطبيق مستقلاً.
     2. affiliateApplied=true + كود مفهوم ومتسق → تثبيت الفعليين.
        true بلا كود = ناقص (unconfirmed + mismatch — لا ادعاء).
     3. غياب الحقول (باك قديم) = «غير مؤكد» لا «مطبق» (applied=null).
     4. صدى كود يخالف المرسل = mismatch (يُسجَّل الاثنان بلا حذف أعمى). */
export function resolveAttribution(serverPayload, sentSnapshot) {
  const requested = normalizeReferralSnapshot(sentSnapshot);
  const echo = pickAppliedReferral(serverPayload);
  if (echo && echo.applied === true) {
    const code = String(echo.code || "").trim();
    if (code) {
      const vid = String(echo.visitId || "").trim() || null;
      const mismatch = !!(requested && requested.code && requested.code !== code);
      return { applied: { code: code, visitId: vid }, requested: requested, confirmed: true, mismatch: mismatch };
    }
    return { applied: null, requested: requested, confirmed: false, mismatch: true };
  }
  if (echo && echo.applied === false) {
    return { applied: null, requested: requested, confirmed: true, mismatch: false };
  }
  return { applied: null, requested: requested, confirmed: false, mismatch: false };
}

/* ★ فصل تنظيف اللقطة المرسلة عن تسجيل الإسناد الفعلي (FE24-F3):
   التنظيف بهوية العملية المرسلة فقط — لا بمعرف مختلف من رد الخادم.
   true = نظّف الهوية المرسلة؛ false = أبقِها (تناقض/لا شيء مرسل) مع
   معالجة صريحة عند المستدعي. الرفض (لا رد ناجح أصلاً) لا ينظف أبداً
   — هذه الدالة لمسار الاكتمال فقط. */
export function shouldCleanupSent(sentSnapshot, serverPayload) {
  const sent = normalizeReferralSnapshot(sentSnapshot);
  if (!sent || !sent.visitId) return false;
  const echo = pickAppliedReferral(serverPayload);
  if (!echo || !echo.code) return true;
  if (String(echo.code) !== String(sent.code)) return false;
  const evid = String(echo.visitId || "").trim();
  if (evid && sent.visitId && evid !== String(sent.visitId)) return false;
  return true;
}

/* ★ بوابة «المتابعة بلا إحالة» (FE24-F4) — خالصة:
   مسموحة فقط بعد رفض قطعي (رموز classifyReferralConflict الأربع) يضمن
   عدم إنشاء طلب، وبلا orderId قائم (ذاك يُستأنف)، وبلا عملية مجهولة
   معلقة (تلك تُستعلَم وتُصالَح أولاً). المخرج {allowed, reason}:
   "definitive-rejection" · "resume-order" · "unknown-pending" ·
   "not-definitive". العملية البديلة نفسها: مفتاح جديد + referral:null
   + إعادة موافقة — يبنيها المستدعي، لا هذه الدالة. */
export function planNoReferralRetry(state) {
  const s = state || {};
  if (s.hasOrderId) return { allowed: false, reason: "resume-order" };
  if (s.unknownPending) return { allowed: false, reason: "unknown-pending" };
  const r = String(s.rejection || "");
  if (r === "visit-consumed" || r === "visit-invalid" || r === "visit-expired" || r === "code-invalid") {
    return { allowed: true, reason: "definitive-rejection" };
  }
  return { allowed: false, reason: "not-definitive" };
}

/* ---------- ربط الرفض بالعملية + حسم المجهول (FE25-R32-02/R32-03) ----------
   المشكلة: referralExit بلا ربط، والبوابات بfalse حرفية — فيسمح رفض K1
   القديم بفرع K3 بينما K2 مجهولة، وخيار بلا-إحالة يضيع في الفرع الإلكتروني.
   الحل هنا خالصٌ وقابل للاختبار؛ الصفحتان طبقة رقيقة (قراءة تخزين طازجة
   داخل onClick + bent identity guards عند حسم الهوية). */

/* ★ الرموز القطعية الأربعة وحسب — لا يُعتبر أي 400/409 آخر رفضاً قطعياً. */
export function isDefinitiveReferralRejection(kind) {
  const r = String(kind || "");
  return r === "visit-consumed" || r === "visit-invalid" || r === "visit-expired" || r === "code-invalid";
}

/* ★ نتيجة مجهولة الأثر (خالصة — شكل الخطأ فقط): timeout بلا رد، انقطاع
   الشبكة (بلا status)، 408/503/504 محتملة التطبيق. المستثنى: أخطاء محلية
   قبل الإرسال (مزامنة/موافقة/بصمة — لم يُرسل شيء فلا مجهول). */
export function isUnknownOutcome(err) {
  if (!err || typeof err !== "object") return false;
  if (err.basketSync || err.approvalStale || err.missingFingerprint) return false;
  if (err.message === "timeout") return true;
  const code = String(err.code || "");
  if (/^(ECONNABORTED|ENETUNREACH|EABORTED|ETIMEDOUT|ENETDOWN|ENETRESET|EPIPE|EAI_AGAIN)$/i.test(code)) return true;
  const st = Number(err.status);
  if (!st) return true;
  if (st === 408 || st === 503 || st === 504) return true;
  return false;
}

/* ★ اشتقاق حالة العملية الحقيقية من التخزين مع عزل العميل (خالصة):
   { present, sameOwner, purchaseId, idempotencyKey, sentCount, orderId,
     unknown, rejected, done, lastRejection } —
   · foreign (مالك آخر) = sameOwner:false وتُتجاهل كلياً (لا تُقرأ هويته).
   · unknown = بهوية + بلا orderId + غير done + (state=unknown أو أُرسل
     بلا رد مسجّل: sentCount>respondedCount — تحطم/تحديث أثناء الطيران).
     in-flight بلا إرسال مسجّل (عدادات صفرية قديمة) ليست مجهولة.
   · rejected = رفض إحالة محلول مسجّل (markSetupRejected) بلا orderId. */
export function currentOpFromSetup(setup, ownerId) {
  const out = { present: false, sameOwner: false, purchaseId: "", idempotencyKey: "", sentCount: 0, orderId: 0, unknown: false, rejected: false, done: false, lastRejection: "" };
  const s = setup && typeof setup === "object" ? setup : null;
  if (!s) return out;
  out.present = true;
  if (ownerId != null && s.customerId != null && Number(s.customerId) !== Number(ownerId)) return out;
  out.sameOwner = true;
  out.purchaseId = s.purchaseId ? String(s.purchaseId) : "";
  out.idempotencyKey = s.idempotencyKey ? String(s.idempotencyKey) : "";
  out.sentCount = (Number(s.sentCount || 0) || 0);
  out.orderId = Number(s.orderId) || 0;
  out.done = !!(s.done === true || s.state === "done");
  out.lastRejection = s.lastRejection ? String(s.lastRejection) : "";
  if (!out.done && !out.orderId && out.purchaseId) {
    if (s.state === "unknown") out.unknown = true;
    else if (s.state === "rejected") out.rejected = true;
    else if (s.state === "in-flight") {
      const resp = (Number(s.respondedCount || 0) || 0);
      if (out.sentCount > resp) out.unknown = true;
    }
  }
  return out;
}

/* ★ بوابة «المتابعة بلا إحالة» المربوطة بالعملية (خالصة) —
   rejection: { kind, purchaseId?, idempotencyKey?, sentCount? } (أو نص kind
   قديم بلا ربط = يرجع لسلوك planNoReferralRetry عبر current البديلة).
   current: مخرج currentOpFromSetup (أو { hasOrderId, unknownPending } قديم).
   الترتيب: قطعي؟ ← طلب يُستأنف؟ ← مجهول لاحق؟ ← الرفض لعملية أخرى/أقدم؟
   ← مسموح. العملية المكتملة (done) تاريخ — رفضها لا يفتح بوابة. */
export function gateNoReferralOp(rejection, current) {
  const r = rejection && typeof rejection === "object" ? rejection : null;
  const kind = r ? r.kind : rejection;
  if (!isDefinitiveReferralRejection(kind)) return { allowed: false, reason: "not-definitive" };
  const c = current && typeof current === "object" ? current : {};
  if (!!c.done) return { allowed: false, reason: "stale-rejection" };
  if (!!(c.orderId || c.hasOrderId)) return { allowed: false, reason: "resume-order" };
  if (!!(c.unknown || c.unknownPending)) return { allowed: false, reason: "unknown-pending" };
  if (r && r.purchaseId) {
    if (!c.sameOwner || !c.purchaseId || String(c.purchaseId) !== String(r.purchaseId)) {
      return { allowed: false, reason: "stale-rejection" };
    }
    if (r.sentCount != null && c.sentCount != null && Number(c.sentCount) !== Number(r.sentCount)) {
      return { allowed: false, reason: "stale-rejection" };
    }
  }
  return { allowed: true, reason: "definitive-rejection" };
}

/* ★ بناء إعداد العملية البديلة بلا إحالة (خالص — يستعمله Redirect):
   هوية جديدة تُمرَّر + referral:null الصريحة + تصفير العدّادات والحالة
   (إرسالها اللاحق يبدأ العدّ من 1) + حذف orderId/invoice/serverId —
   مع إبقاء المالك والحقول والطريقة. لا يمسّ تخزين الزيارات أبداً. */
export function nextNoReferralSetup(curSetup, newIds) {
  const cur = curSetup && typeof curSetup === "object" ? curSetup : {};
  const ni = newIds || {};
  const next = Object.assign({}, cur, {
    purchaseId: String(ni.purchaseId || ""),
    idempotencyKey: String(ni.idempotencyKey || ""),
    referral: null,
    sentCount: 0,
    respondedCount: 0,
    sentKey: "",
    lastSentAt: 0,
    lastResponseKind: "",
    lastRejection: "",
    rejectedAt: 0,
    state: "in-flight",
    done: false,
    startedAt: Date.now()
  });
  try { delete next.orderId; } catch (e) {}
  try { delete next.invoiceNo; } catch (e) {}
  try { delete next.serverId; } catch (e) {}
  return next;
}

/* ★ حسم إحالة المسار الإلكتروني قبل التفريع (خالص — R32-03):
   المدخل: forceNoReferral (خيار صريح بعد رفض قطعي)، اللقطة الواردة من
   المراجعة، الإعداد السابق، المالك، ونتيجة sameOp المحسوبة في الصفحة.
   المخرج: { referral, reusePrevIdentity } —
   · force + سابق مفروض-null (نفس العملية) = استئنافه (null + نفس الهوية).
   · force + غيره = null + هوية جديدة (لا يحق لاستعادة قديمة إرجاع المرفوضة).
   · بلا force + sameOp بلقطة محفوظة = استعادتها (نفس المفتاح = نفس اللقطة). */
export function resolveOnlineReferral(input) {
  const inp = input || {};
  const force = !!inp.forceNoReferral;
  const prev = inp.prevSetup && typeof inp.prevSetup === "object" ? inp.prevSetup : null;
  if (force) {
    let prevForcedNull = false;
    try {
      prevForcedNull = !!(prev && inp.sameOp && prev.customerId != null && inp.customerId != null &&
        Number(prev.customerId) === Number(inp.customerId) && !prev.done && prev.state !== "done" &&
        Object.prototype.hasOwnProperty.call(prev, "referral") && normalizeReferralSnapshot(prev.referral) === null);
    } catch (e) { prevForcedNull = false; }
    return { referral: null, reusePrevIdentity: prevForcedNull };
  }
  let ref = null;
  let restored = false;
  try { ref = normalizeReferralSnapshot(inp.incomingRef); } catch (e) { ref = null; }
  try {
    if (inp.sameOp && prev && Object.prototype.hasOwnProperty.call(prev, "referral")) {
      ref = normalizeReferralSnapshot(prev.referral);
      restored = true;
    }
  } catch (e) {}
  return { referral: ref, reusePrevIdentity: false, restored: restored };
}

/* ---------- حارس الإرسال المكرر داخل الصفحة ----------
   useRef وحده لا يكفي (إعادة التركيب/الـeffect المزدوج يصنعان refs
   جديدة) — هذا الحارس على مستوى الوحدة: أول مُطالِب بالـpurchaseId
   يفوز، والبقية تُرفض فوراً. إعادة التحميل/التبويب الثاني يحميهما
   مفتاح منع التكرار في الخادم — لا هذا الحارس. */
const inflightPurchases = {};
export function claimPurchaseAttempt(purchaseId) {
  const k = String(purchaseId || "");
  if (!k) return true;
  if (inflightPurchases[k]) return false;
  inflightPurchases[k] = true;
  return true;
}
export function releasePurchaseAttempt(purchaseId) {
  const k = String(purchaseId || "");
  if (k) delete inflightPurchases[k];
}

/* ---------- ربط الموافقة بعرض السعر (FE19-3) ----------
   القاعدة: الموافقة = {quoteId, grandTotal, basketVersion, key} مأخوذة من
   استجابة /quote نفسها لحظة ضغط التأكيد. تُرسل expectedGrandTotal مع الإنشاء،
   ولا تُستبدل بإصدار أحدث وقت الضغط. الشراء محظور بينما quote قيد التحديث
   أو لا يطابق الاختيارات (key mismatch). أكواد منظمة فقط (بلا regex عربي). */

/* لقطة الموافقة من رد quote — وحدة واحدة ذرية من الاستجابة نفسها.
   ★ FE20-1 (عقد Backend v20): تحمل grandTotal + currencyCode + basketVersion
   + basketFingerprint + quoteId — كلها من الرد نفسه، بلا توليد محلي وبلا خلط
   (مبلغ عرض قديم مع إصدار أحدث مرفوض). الناقصة تُرفض صراحة (null) —
   غياب الإصدار لا يتحول إلى صفر عبر Number(null). */
export function quoteApprovalOf(normTotals, quoteKey) {
  const t = normTotals || {};
  const total = Number(t.total);
  if (!Number.isFinite(total) || total < 0) return null;
  const qid = t.quoteId != null ? String(t.quoteId) : "";
  if (!qid) return null;
  const bvRaw = t.basketVersion;
  if (bvRaw == null || bvRaw === "") return null;
  const bv = Number(bvRaw);
  if (!Number.isFinite(bv) || bv < 0) return null;
  const fp = t.basketFingerprint != null ? String(t.basketFingerprint) : "";
  if (!fp) return null;
  const cur = t.currencyCode != null ? String(t.currencyCode) : "";
  if (!cur) return null;
  return {
    quoteId: qid,
    grandTotal: total,
    basketVersion: Math.round(bv),
    basketFingerprint: fp,
    currencyCode: cur,
    key: String(quoteKey || "")
  };
}

/* الموافقة صالحة فقط إن: موجودة + ليست قيد تحديث + تطابق مفتاح الاختيارات الحالية.
   ★ FE20-1: اللقطة الناقصة (بلا بصمة/إصدار/عملة) ليست موافقة أصلاً. */
export function isApprovalFresh(approval, currentKey, quoteBusy, quoteOk) {
  if (!approval || quoteBusy) return false;
  if (quoteOk === false) return false;
  if (!approval.key || String(approval.key) !== String(currentKey || "")) return false;
  if (approval.grandTotal == null || !Number.isFinite(Number(approval.grandTotal))) return false;
  if (!approval.basketFingerprint || approval.basketVersion == null || !approval.currencyCode) return false;
  return true;
}

/* ★ FE20-2: مطابقة اللقطة كاملةً مع عرض طازج — المفتاح + المبلغ (±0.005)
   + البصمة + الإصدار + العملة. أي اختلاف (ولو بنفس الإجمالي مع تغيّر
   المحتويات) = إبطال وانتظار موافقة جديدة. quoteId لا يُقارَن (الخادم قد
   يسكّ هوية جديدة لنفس المحتوى) — المحتوى هو المرجع. */
export function approvalMatchesQuote(approval, normTotals) {
  if (!approval || !normTotals) return false;
  if (!approval.basketFingerprint || approval.basketVersion == null || !approval.currencyCode) return false;
  if (Math.abs(Number(normTotals.total) - Number(approval.grandTotal)) > 0.005) return false;
  if (String(normTotals.basketFingerprint || "") !== String(approval.basketFingerprint)) return false;
  if (!normTotals.basketFingerprint) return false;
  if (Number(normTotals.basketVersion) !== Number(approval.basketVersion)) return false;
  if (String(normTotals.currencyCode || "") !== String(approval.currencyCode)) return false;
  return true;
}

/* تصنيف رفض الإنشاء المرتبط بالعرض/السلة — حقول منظمة فقط
   (code/reason/errorCode/error_code)، بلا مسح للنصوص العربية. */
const QUOTE_CONFLICT_TOKENS = {
  basket_changed: "basket_changed",
  quote_changed: "quote_changed",
  quote_expired: "quote_expired",
  grand_total_mismatch: "grand-total-mismatch",
  total_mismatch: "grand-total-mismatch",
  expected_version_mismatch: "version-mismatch",
  version_mismatch: "version-mismatch"
};
export function classifyQuoteConflict(data, status) {
  const d = data || {};
  const fields = [d.code, d.reason, d.errorCode, d.error_code];
  for (let i = 0; i < fields.length; i++) {
    const v = String(fields[i] || "").trim().toLowerCase();
    if (v && QUOTE_CONFLICT_TOKENS[v]) return QUOTE_CONFLICT_TOKENS[v];
  }
  if (Number(status) === 409) {
    const c = String(d.code || d.reason || "").trim().toLowerCase();
    if (c && QUOTE_CONFLICT_TOKENS[c]) return QUOTE_CONFLICT_TOKENS[c];
  }
  return null;
}

/* بصمة الموافقة تُلحق ببصمة الحقول: تغيّر المبلغ المتفق عليه = عملية جديدة
   (مفتاح idempotency جديد)، بينما المجهول (timeout بلا رد) يعيد المفتاح نفسه.
   ★ FE20-2: بصمة السلة جزء من الهوية — تغيّر المحتويات مع بقاء الإجمالي
   نفسه = عملية جديدة أيضاً. */
export function canonWithApproval(fieldsCanon, agreedTotal, basketFingerprint) {
  const base = String(fieldsCanon || "");
  let out = base;
  if (agreedTotal != null && Number.isFinite(Number(agreedTotal))) out += "|total=" + Number(agreedTotal);
  if (basketFingerprint != null && String(basketFingerprint) !== "") out += "|fp=" + String(basketFingerprint);
  return out;
}

/* ---------- تصنيف 409 منع التكرار (§11 — متسامح، والعقد في
   backend-msg-round51): قيد التنفيذ / مفتاح لمدخلات مختلفة /
   مدفوع سابقاً / مجهول. */
export function classifyOrderConflict(data) {
  const d = data || {};
  const reason = String(d.reason || d.code || "").toUpperCase();
  const text = [d.detail, d.message, d.title, d.error].filter(Boolean).map(function (v) { return String(v); }).join(" | ");
  /* ★ #3: مطابقة حرفية لرمز الخلفية idempotency_key_reuse (بكل حالاته) */
  if (/IDEMPOTENCY_KEY_REUSE/i.test(reason + " " + text)) return "key-reuse";
  if (/IDEMPOTENCY_IN_PROGRESS|قيد التنفيذ|already in progress|in progress/i.test(reason + " " + text)) return "in-progress";
  if (/IDEMPOTENCY_KEY_CONFLICT|مدخلات مختلفة|different.*input|key.*mismatch|conflict.*key/i.test(reason + " " + text)) return "key-mismatch";
  if (/مدفوع|غير قابل للدفع|already paid|not payable/i.test(text)) return "paid";
  return "unknown";
}

/* ---------- الأصناف المستبعدة من الطلب (SkippedIssues — البند 5) ----------
   متسامح: skippedIssues/skipped/excludedItems — [{productId, quantity?,
   reason?/detail?/message?}] + أسماء محلية للعرض. غياب الحقل = لا
   مستبعدة (يتعامل settleBasketAfterOrder مع الباقي بأمان). */
export function parseSkippedIssues(payload, names) {
  const d = payload || {};
  const raw = Array.isArray(d.skippedIssues)
    ? d.skippedIssues
    : Array.isArray(d.skipped)
      ? d.skipped
      : Array.isArray(d.excludedItems)
        ? d.excludedItems
        : [];
  const nm = names || {};
  return raw
    .map(function (it) {
      const o = it || {};
      const pid =
        Number(o.productId != null ? o.productId : o.ProductId != null ? o.ProductId : o.id != null ? o.id : 0) || 0;
      return {
        productId: pid,
        qty: o.quantity != null ? Number(o.quantity) : o.qty != null ? Number(o.qty) : null,
        reason: String(o.reason || o.detail || o.message || "غير متاح حالياً بالكمية المطلوبة"),
        name: o.productName != null ? String(o.productName) : o.name != null ? String(o.name) : String(nm[pid] || "")
      };
    })
    .filter(function (s) {
      return s.productId > 0;
    });
}

/* ★ رفض الباقة صريح؟ (سبب OFFER أو باقة أو bundle — لا كلمة عرض العامة) */
export function isOfferRejection(err) {
  const data = err && err.response && err.response.data;
  if (!data) return false;
  const blob = String(data.reason || "") + " " + String(data.code || "") + " " + String(data.detail || data.message || data.error || "");
  return /OFFER|باقة|الباقة|bundle/i.test(blob);
}

/* ---------- قائمة طلباتي + تفاصيل طلب ---------- */

export async function fetchServerOrders(customerId, page, pageSize) {
  const p = Math.max(1, Number(page) || 1);
  const s = Math.max(1, Math.min(100, Number(pageSize) || 20));
  const res = await authFetch(ENDPOINTS.orderList(customerId) + "?page=" + p + "&pageSize=" + s, { method: "GET" });
  const payload = await readJson(res);
  if (!res.ok) throwOrder(res, payload);
  const items = (payload && Array.isArray(payload.items)) ? payload.items : [];
  return {
    items: items,
    page: (payload && Number(payload.page)) || p,
    pageSize: (payload && Number(payload.pageSize)) || s,
    /* ★ العقد يسمّيها total (ونقبل totalItems القديمة للتوافق) */
    totalItems: (payload && (Number(payload.total) || Number(payload.totalItems))) || items.length,
    totalPages: (payload && Number(payload.totalPages)) || 1
  };
}

export async function fetchServerOrderDetail(customerId, orderId) {
  const res = await authFetch(ENDPOINTS.orderDetail(customerId, orderId), { method: "GET" });
  const payload = await readJson(res);
  if (!res.ok) throwOrder(res, payload);
  return payload;
}

/* ---------- الفاتورة الملزمة قبل الإنشاء (OrderQuote) ----------
   ★ #2: نفس حقول الإنشاء بلا termsAccepted — مع OfferId المفرد
   (عقد واحد في quote والإنشاء). ممنوع OfferId + couponCode معاً → 400. */

export async function fetchServerQuote(customerId, fields) {
  const f = fields || {};
  const reqBody = {
    locationId: Number(f.locationId),
    deliveryMethodId: Number(f.deliveryMethodId),
    paymentMethodId: Number(f.paymentMethodId),
    couponCode: f.couponCode ? String(f.couponCode) : null
  };
  /* ★ #2: العرض المفرد في الـquote أيضاً — ليتطابق المعروض مع الطلب */
  let qOffer = 0;
  if (f.OfferId != null && Number(f.OfferId)) qOffer = Number(f.OfferId);
  else if (f.offerId != null && Number(f.offerId)) qOffer = Number(f.offerId);
  else if (Array.isArray(f.offerIds) && f.offerIds.length) qOffer = Number(f.offerIds[0]) || 0;
  if (qOffer) reqBody.OfferId = Number(qOffer);
  const res = await authFetch(ENDPOINTS.orderQuote(customerId), {
    method: "POST",
    body: reqBody
  });
  const payload = await readJson(res);
  if (!res.ok) throwOrder(res, payload);
  return payload;
}

/* تطبيع OrderQuote إلى أرقام عرض (نفس شكل totals الفرعي): الشحن من
   deliveryFee (وبديل deliveryFeeTotal)، والرسوم من paymentFee
   (وبديل paymentFeeAmount).
   ★ FE20-1 (عقد Backend v20): يُحتفظ بحقول اللقطة الملزمة كما وردت —
   currencyCode + basketVersion + basketFingerprint + quoteId (camel/Pascal
   كما في العقد). الإجمالي verbatim ملزم (سياسة FE20-6: بلا تصحيح صامت). */
export function normalizeQuoteTotals(q) {
  const s = q || {};
  const fee = s.paymentFee != null ? s.paymentFee : (s.paymentFeeAmount != null ? s.paymentFeeAmount : 0);
  const ship = s.deliveryFee != null ? s.deliveryFee : (s.deliveryFeeTotal != null ? s.deliveryFeeTotal : 0);
  const qid = s.quoteId != null ? s.quoteId : (s.QuoteId != null ? s.QuoteId : (s.id != null ? s.id : null));
  const cur = s.currencyCode != null ? s.currencyCode : (s.CurrencyCode != null ? s.CurrencyCode : (s.currency != null ? s.currency : null));
  const bv = s.basketVersion != null ? s.basketVersion : (s.BasketVersion != null ? s.BasketVersion : null);
  const fp = s.basketFingerprint != null ? s.basketFingerprint : (s.BasketFingerprint != null ? s.BasketFingerprint : null);
  return {
    before: num(s.subtotal, 0),
    discount: num(s.discount, 0),
    shipping: num(ship, 0),
    vat: num(s.vatAmount, 0),
    vatRate: s.vatRate != null ? num(s.vatRate, 0.05) : 0.05,
    /* ★ FE20-6: رسوم البوابة تُقرأ للعرض الشفاف فقط — إجمالي الخادم ملزم
       كما هو، ومنع تحميلها على العميل (إن وُجد) سياسة تسعير خلفية متفق
       عليها لا تصحيح واجهة. */
    payFee: num(fee, 0),
    total: num(s.grandTotal != null ? s.grandTotal : s.GrandTotal, 0),
    quoteId: qid != null ? qid : null,
    currencyCode: cur != null ? String(cur) : null,
    basketVersion: bv,
    basketFingerprint: fp != null ? String(fp) : null
  };
}

/* ---------- تطبيع فاتورة الخادم إلى شكل الطلب المحلي ---------- */

/* ★ v17-D1: تاريخ الخادم (ISO/epoch) إلى ms — 0 للغائب/الفاسد (لا تخمين) */
function parseDateMs(v) {
  if (v == null || v === "") return 0;
  if (typeof v === "number" && Number.isFinite(v)) return v > 1e12 ? Math.round(v) : Math.round(v * 1000);
  const ms = Date.parse(String(v));
  return Number.isFinite(ms) ? ms : 0;
}

function num(v, fallback) {
  const n = Number(v);
  return Number.isFinite(n) ? n : (fallback || 0);
}

export function normalizeServerOrder(srv, extra) {
  const x = extra || {};
  const s = srv || {};
  const items = Array.isArray(s.items) ? s.items : [];
  const createdAt = s.createdAt ? Date.parse(s.createdAt) || Date.now() : Date.now();
  const day = 86400e3;
  const count = items.reduce(function (n, it) { return n + num(it.quantity, 1); }, 0);
  const discount = num(s.discountTotal, 0);
  /* ★ طريقة الضريبة تُستنتج من أرقام الفاتورة نفسها (بلا اعتماد على
     إعدادات لحظية قد تتغيّر): إن طابق الإجمالي (الفرعي − الخصم + الشحن
     + الضريبة) فالضريبة مضافة فوق المجموع، وإن طابق (الفرعي − الخصم
     + الشحن) فهي مضمّنة فيه. الغامض ← مضافة (افتراضي الإعدادات). */
  const sub = num(s.subtotal, 0);
  const ship = num(s.deliveryFeeTotal, 0);
  const vat = num(s.vatAmount, 0);
  const grand = num(s.grandTotal, 0);
  /* ★ رسوم طريقة الدفع من سطر الخادم paymentFeeAmount (داخلة في المجموع) —
     تُعرض في الفاتورة ليجمع (منتجات − خصم + شحن + ضريبة + رسوم) = المجموع. */
  const payFee = num(s.paymentFeeAmount != null ? s.paymentFeeAmount : (s.paymentFee != null ? s.paymentFee : (s.feeAmount != null ? s.feeAmount : 0)), 0);
  const vatRate = s.vatRate != null ? num(s.vatRate, 0.05) : 0.05;
  /* ★ F6: حالات العقد المباشرة — paymentStatus/orderStatus/needsRefundReview
     تُقرأ كما هي (بكلتي الحالتين Pascal/camel) ولا تُستنتج من النصوص. */
  const orderStatusRaw = s.orderStatus != null ? String(s.orderStatus) : s.OrderStatus != null ? String(s.OrderStatus) : s.statusName != null ? String(s.statusName) : s.StatusName != null ? String(s.StatusName) : "";
  const paymentStatusRaw = s.paymentStatus != null ? String(s.paymentStatus) : s.PaymentStatus != null ? String(s.PaymentStatus) : "";
  const needsReviewRaw = s.needsRefundReview != null ? s.needsRefundReview : s.NeedsRefundReview != null ? s.NeedsRefundReview : s.needsReview != null ? s.needsReview : s.NeedsReview;
  const needsRefundReview = needsReviewRaw === true || needsReviewRaw === 1 || String(needsReviewRaw || "").toLowerCase() === "true";
  const reviewStatusRaw = s.reviewStatus != null ? String(s.reviewStatus) : s.ReviewStatus != null ? String(s.ReviewStatus) : s.refundStatus != null ? String(s.refundStatus) : s.RefundStatus != null ? String(s.RefundStatus) : s.refund_status != null ? String(s.refund_status) : "";
  /* ★ البند 7: حقل صريح من الخادم (vatIncluded:boolean) يغلِب الاستنتاج
     الحسابي — والاستنتاج يبقى احتياطاً فقط. */
  const incl = s.vatIncluded != null ? !!s.vatIncluded
    : x.vatIncluded != null ? !!x.vatIncluded
    : Math.abs(grand - (sub - discount + ship)) < 0.005 && Math.abs(grand - (sub - discount + ship + vat)) >= 0.005;
  return {
    invoiceNo: String(s.invoiceNumber || ("SRV-" + num(s.orderId, 0))),
    createdAt: createdAt,
    status: { ar: String(s.statusName || "مُسجَّل"), en: String(s.statusName || "Placed") },
    method: x.method || "",
    methodLabel: x.methodLabel || String(s.paymentMethod || ""),
    kind: x.kind || "",
    cardLast4: "",
    walletPhone: "",
    customer: x.customer || {},
    items: items.map(function (it) {
      return {
        id: num(it.productId, 0),
        name: String(it.productName || ""),
        nameEn: String(it.productName || ""),
        image: "",
        qty: num(it.quantity, 1),
        unitPrice: num(it.unitPrice, 0),
        lineTotal: num(it.lineTotal, num(it.unitPrice, 0) * num(it.quantity, 1))
      };
    }),
    totals: {
      count: count,
      before: sub,
      offerSave: 0,
      code: s.couponCode ? String(s.couponCode) : "",
      percent: 0,
      discount: discount,
      shipping: ship,
      vat: vat,
      vatRate: vatRate,
      vatIncluded: incl,
      payFee: payFee,
      total: grand,
      saved: discount
    },
    currency: x.currency || { key: String(s.currencyCode || "AED"), rate: 1, decimals: 2, symbol: "د.إ", symbolEn: "AED", position: "after" },
    eta: { min: ETA_DAYS.min, max: ETA_DAYS.max, from: createdAt + ETA_DAYS.min * day, to: createdAt + ETA_DAYS.max * day },
    terms: {
      accepted: true,
      version: (ATYAB_TERMS && ATYAB_TERMS.version) || "",
      acceptedAt: createdAt
    },
    /* ★ أثر الخادم — للسجلّ والتشخيص (لا يُعرض للعميل) */
    server: true,
    serverId: num(s.orderId, 0),
    paymentStatus: paymentStatusRaw,
    orderStatus: orderStatusRaw,
    needsRefundReview: needsRefundReview,
    reviewStatus: reviewStatusRaw,
    deliveryStatus: String(s.deliveryStatus != null ? s.deliveryStatus : (s.DeliveryStatus != null ? s.DeliveryStatus : "")),
    deliveryMethod: String(s.deliveryMethod || ""),
    /* ★ v17-D1: حقول التسليم/التحصيل من الخادم حصراً — لا اشتقاق محلي
       بالوقت: estimatedDeliveryAt موعد متوقع، deliveredAt حدث فعلي،
       paidAt تحصيل فعلي. سياسة المتجر: 24h بعد نجاح الدفع الإلكتروني،
       و48h بعد تأكيد COD — تُحسب خلفياً وتُعرض هنا كما وصلت.
       ★ FE18-X03: سبب الانتقال التلقائي يُمرَّر كما وصل (autoNote/
       transitionReason — أي حالة/نوع) ويُعرض في السجلّ؛ غيابه = "" (لا
       تخمين). أسماء الحقول النهائية بانتظار الباك — انظر API-CONTRACT-NEXT. */
    delivery: {
      status: String(s.deliveryStatus != null ? s.deliveryStatus : (s.DeliveryStatus != null ? s.DeliveryStatus : "")),
      estimatedAt: parseDateMs(s.estimatedDeliveryAt != null ? s.estimatedDeliveryAt : s.EstimatedDeliveryAt),
      deliveredAt: parseDateMs(s.deliveredAt != null ? s.deliveredAt : s.DeliveredAt),
      dueAt: parseDateMs(s.deliveryDueAt != null ? s.deliveryDueAt : s.DeliveryDueAt),
      reason: String(s.transitionReason != null ? s.transitionReason : (s.TransitionReason != null ? s.TransitionReason : (s.transition_reason != null ? s.transition_reason : (s.autoTransitionReason != null ? s.autoTransitionReason : (s.deliveryReason != null ? s.deliveryReason : ""))))),
      autoNote: String(s.autoNote != null ? s.autoNote : (s.AutoNote != null ? s.AutoNote : (s.deliveryAutoNote != null ? s.deliveryAutoNote : (s.DeliveryAutoNote != null ? s.DeliveryAutoNote : ""))))
    },
    autoNote: String(s.autoNote != null ? s.autoNote : (s.AutoNote != null ? s.AutoNote : "")),
    transitionReason: String(s.transitionReason != null ? s.transitionReason : (s.TransitionReason != null ? s.TransitionReason : (s.transition_reason != null ? s.transition_reason : ""))),
    paidAt: parseDateMs(s.paidAt != null ? s.paidAt : s.PaidAt),
    /* ★ المستبعدة من الطلب (البند 5): أسبابها تُعرض في الفاتورة وتبقى
       في العربة عبر settleBasketAfterOrder — لا مسح شامل لطلب جزئي */
    skipped: parseSkippedIssues(s, (x.skipNames || {}))
  };
}

/* تطبيع صفّ القائمة (بلا أصناف) إلى بطاقة سجلّ */
export function normalizeServerRow(row) {
  const r = row || {};
  return {
    invoiceNo: String(r.invoiceNumber || ("SRV-" + num(r.orderId, 0))),
    createdAt: r.createdAt ? Date.parse(r.createdAt) || 0 : 0,
    status: { ar: String(r.statusName || "مُسجَّل"), en: String(r.statusName || "Placed") },
    method: "",
    methodLabel: "",
    kind: "",
    cardLast4: "",
    walletPhone: "",
    customer: {},
    items: [],
    itemsCount: num(r.itemsCount, 0),
    totals: {
      count: num(r.itemsCount, 0),
      before: num(r.grandTotal, 0),
      offerSave: 0,
      code: "",
      percent: 0,
      discount: 0,
      shipping: 0,
      vat: 0,
      total: num(r.grandTotal, 0),
      saved: 0
    },
    currency: { key: "AED", rate: 1, decimals: 2, symbol: "د.إ", symbolEn: "AED", position: "after" },
    eta: null,
    terms: { accepted: true, version: "", acceptedAt: 0 },
    server: true,
    serverId: num(r.orderId, 0),
    rowOnly: true
  };
}
