/* ★ v17-P1: Unknown صريح (نتيجة غير معلومة) ≠ فشل — شاشة تحقق لا فشل نهائي */
/* ★ v17-T17: مصدّرة للاختبار (Unknown ≠ فشل) */
export function normStatus(v) {
  const s = String(v == null ? "" : v).trim().toLowerCase();
  if (!s) return "pending";
  if (s === "unknown" || s === "unverified" || s === "verifying" || s === "ambiguous" || s === "غير معلوم" || s === "مجهول" || s === "غير مؤكد" || s === "غير مؤكدة" || s === "جار التحقق" || s === "جارٍ التحقق") return "unknown";
  if (s === "a" || s === "success" || s === "succeeded" || s === "succeed" || s === "authorised" || s === "authorized" || s === "captured" || s === "paid" || s === "settled" || s === "settle" || s === "approved" || s === "complete" || s === "completed" || s === "مدفوع" || s === "مدفوعة" || s === "ناجح" || s === "ناجحة" || s === "مقبول" || s === "مقبولة" || s === "تم الدفع") return "success";
  if (s === "fail" || s === "failed" || s === "failure" || s === "declined" || s === "cancelled" || s === "canceled" || s === "cancel" || s === "void" || s === "refunded" || s === "rejected" || s === "error" || s === "d" || s === "c") return "fail";
  return "pending";
}

function attemptOrderId(st, pending) {
  const c = [st && st.orderId, st && st.order_id, st && st.orderID, st && st.data && st.data.orderId, pending && pending.orderId].filter(Boolean)[0];
  return Number(c) || 0;
}

/* ★ F6: قرار النتيجة الخالص — قابل للاختبار بلا React.
   العقد الفعلي: حقول الحالة (paymentStatus/orderStatus/needsRefundReview)
   تأتي في رد status (الاستعلام)، بينما detail (تفاصيل الطلب) قد لا تحمل
   needsRefundReview إطلاقاً — فتُقرأ الحالة أولاً ثم التفاصيل احتياطاً.
   لا اشتقاق من paymentMethod ولا بحث عن كلمات refund داخل نصوص أخرى.
   المدخل: detail (تفاصيل الطلب) + status (نتيجة الاستعلام).
   المخرج: { payRaw, ordRaw, revRaw, needsRefundReview, isCancelled, reviewOpen, phase, ... }
   ★ FE19-6: لا paid إلا بدليل نجاح صريح (normStatus(payRaw)==="success").
   الحالات مستقلة: "paid" | "paid-attention" | "failed" | "unknown" | "pending".
   paymentStatus منفصل عن orderStatus وعن needsRefundReview. */
export function resolvePaymentOutcome(detail, status) {
  const dd = detail || {};
  const st = status || {};
  function pickStrFirst(objA, objB, keys, fb) {
    let i = 0;
    for (i = 0; i < keys.length; i++) {
      const v = objA && objA[keys[i]];
      if (v != null && String(v).trim() !== "") return String(v);
    }
    for (i = 0; i < keys.length; i++) {
      const v = objB && objB[keys[i]];
      if (v != null && String(v).trim() !== "") return String(v);
    }
    return fb || "";
  }
  function pickBoolEither(objA, objB, keys) {
    let i = 0;
    for (i = 0; i < keys.length; i++) {
      const v = objA && objA[keys[i]];
      if (v === true || v === 1) return true;
      if (typeof v === "string" && v.trim().toLowerCase() === "true") return true;
    }
    for (i = 0; i < keys.length; i++) {
      const v = objB && objB[keys[i]];
      if (v === true || v === 1) return true;
      if (typeof v === "string" && v.trim().toLowerCase() === "true") return true;
    }
    return false;
  }
  /* ★ FE17-F03: فصل مصادر الحالتين — status العام للمحاولة لا يجوز
     أن يحجب orderStatus الصريح للتفاصيل. حالة الطلب من حقول الطلب
     الصريحة فقط (orderStatus/statusName بكلا الحالتين)؛ وملاذ أخير
     status العام في التفاصيل وحدها (تفاصيل قديمة بشكل {status}).
     لا paid مستنتجة عند غياب دليل الدفع (الافتراضي "" لا "paid"). */
  const payRaw = pickStrFirst(st, dd, ["paymentStatus", "PaymentStatus", "payment_status"], "")
    || pickStrFirst(st, dd, ["status", "Status", "result", "Result", "state", "State"], "");
  const ordRaw = pickStrFirst(st, dd, ["orderStatus", "OrderStatus", "order_status", "statusName", "StatusName"], "")
    || pickStrFirst(dd, {}, ["status", "Status"], "");
  const revRaw = pickStrFirst(st, dd, ["reviewStatus", "ReviewStatus", "refundStatus", "RefundStatus", "refund_status", "review_status"], "");
  const needsRefundReview = pickBoolEither(st, dd, ["needsRefundReview", "NeedsRefundReview", "needsReview", "NeedsReview"]);
  const ordNorm = String(ordRaw || "").trim().toLowerCase();
  const isCancelled = (function () {
    const cands = ["cancelled", "canceled", "cancel", "void", "voided", "refunded", "refund", "ملغي", "ملغى", "ملغاة", "مسترد", "استرداد"];
    for (let i = 0; i < cands.length; i++) {
      if (ordNorm === cands[i]) return true;
    }
    if (ordNorm.indexOf("cancel") !== -1 || ordNorm.indexOf("void") !== -1) return true;
    return false;
  })();
  const reviewOpen = !!(needsRefundReview || (function () {
    const r = String(revRaw || "").trim().toLowerCase();
    return r === "open" || r === "pending" || r === "under review" || r === "needs review" || r === "مفتوحة" || r === "قيد المراجعة" || r === "يحتاج مراجعة";
  })());
  /* ★ v17-P1: حقول المحاولات الصريحة من الخادم (الحالة أولاً ثم التفاصيل):
     failedAttemptCount/canRetry/retryAfterSeconds/attemptId — تحكم شاشات
     الرفض: أول رفض نهائي = إعادة (نفس OrderId)، ثانٍ = ملغي + انتظار. */
  function pickNum(objA, objB, keys) {
    const lists = [objA, objB];
    for (let i = 0; i < lists.length; i++) {
      const o = lists[i] || {};
      for (let j = 0; j < keys.length; j++) {
        const v = o[keys[j]];
        if (v != null && v !== "" && !isNaN(Number(v))) return Number(v);
      }
    }
    return null;
  }
  const failedAttempts = pickNum(st, dd, ["failedAttemptCount", "FailedAttemptCount", "failedAttempts", "FailedAttempts", "attemptCount", "AttemptCount"]);
  const canRetryRaw = [st, dd].some(function (o) {
    if (!o) return false;
    const v = o.canRetry != null ? o.canRetry : o.CanRetry;
    return v === true || v === 1 || String(v || "").toLowerCase() === "true";
  });
  const retryAfter = pickNum(st, dd, ["retryAfterSeconds", "RetryAfterSeconds", "retryAfter", "RetryAfter"]);
  const attemptId = pickStrFirst(st, dd, ["attemptId", "AttemptId", "attempt_id"], "");
  /* ★ FE19-6: دليل النجاح الصريح شرط أي paid — بدونه الحالات مستقلة
     (unknown/pending/failed) ولا يظهر نجاح ولا يُطلق Start تلقائي. */
  const payState = normStatus(payRaw);
  const phase = payState !== "success"
    ? (payState === "fail" ? "failed" : (payState === "unknown" ? "unknown" : "pending"))
    : ((isCancelled || reviewOpen) ? "paid-attention" : "paid");
  return { payRaw: payRaw, ordRaw: ordRaw, revRaw: revRaw, needsRefundReview: needsRefundReview, isCancelled: isCancelled, reviewOpen: reviewOpen, phase: phase, failedAttempts: failedAttempts, canRetry: canRetryRaw, retryAfterSeconds: retryAfter, attemptId: attemptId };
}

/* ★ FE17-F04: بوابة إعادة الدفع الصريحة — خالصة وقابلة للاختبار بلا React.
   المدخل: fresh (رد الاستعلام الحديث قبل أي Start) + nowMs للحقن +
   waitUntilMs (نهاية انتظار retryAfter المحفوظة عند عرض الرفض، أو null).
   المخرج: { allowed, reason, waitUntilMs? } — reason:
     "cancelled" (ملغى — لا Start) · "already-paid" (مدفوع — فاتورة لا Start) ·
     "verify" (معلق/مجهول — شاشة تحقق لا محاولة) · "forbidden"
     (canRetry=false صريح) · "missing-permission" (بلا إذن صريح — لا افتراض) ·
     "waiting" (انتظار نشط) · "ok".
   القواعد: لا Start إلا بإذن صريح وانتهاء الانتظار؛ العد التنازلي للعرض
   فقط والخادم يفرض القرار. الحقول المطلوبة من الخلفية (مصفوفة العقد):
   canRetry وretryAfterSeconds وfailedAttemptCount وattemptId.
   ★ FE23-F3: الدفع الأول له مساره الصحيح ولا يُعامل كإعادة رفض؛ Unknown
   أو نتيجة غير متاحة = انتظار تحقق (لا طلب/صفحة دفع جديدة)؛ بعد انتهاء
   العد يُعاد الاستعلام (المؤقت لا يمنح إذناً وحده — retrySameOrder
   يستعلم أولاً)؛ 503/خطأ الاستعلام يُبقي الطلب وإسناده مع إتاحة إعادة
   الاستعلام (بلا إعلان نجاح/فشل نهائي). */
/* ★ FE17-T18: مصدّرة للاختبار */
export function retryGate(fresh, nowMs, waitUntilMs) {
  const now = nowMs != null ? Number(nowMs) : Date.now();
  const st = fresh || {};
  let oc = null;
  try { oc = resolvePaymentOutcome({}, st); } catch (e) { oc = null; }
  if (oc && oc.isCancelled) return { allowed: false, reason: "cancelled" };
  /* ★ FE23-F3: دليل صريح من حقول الدفع يغلِب الحالة العامة — نجاح صريح
     (paid/paid-attention) يمنع الإعادة (فاتورة لا Start)، وUnknown صريح
     يمنع التحصيل الجديد (تحقق لا خصم)، ولو ادّعت الحالة العامة الرفض
     (محاولة ثانية غير محسومة بعد رفض أول). الغائب/الفارغ ليس دليلاً. */
  if (oc && (oc.phase === "paid" || oc.phase === "paid-attention")) return { allowed: false, reason: "already-paid" };
  if (oc && oc.phase === "unknown") return { allowed: false, reason: "verify" };
  const raw = st.status != null && String(st.status) !== "" ? st.status
    : st.Status != null && String(st.Status) !== "" ? st.Status
    : st.state != null && String(st.state) !== "" ? st.state
    : st.result != null && String(st.result) !== "" ? st.result
    : st.paymentStatus != null && String(st.paymentStatus) !== "" ? st.paymentStatus
    : st.PaymentStatus != null ? st.PaymentStatus : "";
  const s = normStatus(raw);
  if (s === "success") return { allowed: false, reason: "already-paid" };
  if (s !== "fail") return { allowed: false, reason: "verify" };
  /* رفض نهائي — الإذن الصريح شرط (لا افتراض عند الغياب) */
  const hasCanRetry = (st.canRetry !== undefined && st.canRetry !== null)
    || (st.CanRetry !== undefined && st.CanRetry !== null);
  const canRetry = !!(oc && oc.canRetry);
  if (hasCanRetry && !canRetry) return { allowed: false, reason: "forbidden" };
  if (!hasCanRetry) return { allowed: false, reason: "missing-permission" };
  const freshWait = oc && oc.retryAfterSeconds != null ? Number(oc.retryAfterSeconds) : null;
  if (freshWait != null && freshWait > 0) return { allowed: false, reason: "waiting", waitUntilMs: now + Math.round(freshWait) * 1000 };
  if (waitUntilMs != null && Number(waitUntilMs) > now) return { allowed: false, reason: "waiting", waitUntilMs: Number(waitUntilMs) };
  return { allowed: true, reason: "ok" };
}

export default function PaymentReturnPage() {
  usePageMeta({ route: "paymentReturn", titleAr: "نتيجة الدفع", titleEn: "Payment result" });

  const dispatch = useAppDispatch();
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const customerId = useAppSelector(function (s) {
    return (s.user && s.user.auth && s.user.auth.customerId) || null;
  });
  /* ★ البند 10: الاستعلام بهوية محسومة فقط — المعلّقة تُبقي الفحص */
  const authResolved = useAppSelector(function (s) {
    return !!((s.user && s.user.auth && s.user.auth.resolved) || false);
  });
  const profileCurrency = useAppSelector(function (s) {
    return (s.user && s.user.profile && s.user.profile.currency) || "AED";
  });

  const [params] = useSearchParams();
  const [phase, setPhase] = useState("checking");
  const [order, setOrder] = useState(null);
  const [note, setNote] = useState("");
  const [basketWarn, setBasketWarn] = useState("");
  /* ★ FE22-R02: عدّاد تحديث الحالة اليدوي — يعيد تشغيل استعلام الحالة
     (قراءة فقط، بلا بدء خصم جديد) من زر «تحديث الحالة». */
  const [refreshTick, setRefreshTick] = useState(0);
  /* ★ #10: حالات منفصلة — الدفع ≠ تأكيد الطلب ≠ المراجعة/الاسترداد */
  const [payState, setPayState] = useState("");
  const [orderState, setOrderState] = useState("");
  const [reviewState, setReviewState] = useState("");
  /* ★ v17-P1: حالة المحاولة الصريحة + إعادة نفس الطلب (لا طلب جديد أعمى) */
  const [attempt, setAttempt] = useState(null);
  const [retryBusy, setRetryBusy] = useState(false);
  /* ★ البند 14: انقطاع الشبكة أثناء الاستطلاع يُعرض كـ«جارٍ التحقق»
     مع إعادة تلقائية — لا يُعلَن فشل نهائي من انقطاع. */
  const [netFail, setNetFail] = useState(false);
  const tries = useRef(0);
  /* ★ v17-P1: جسر زر «إعادة المحاولة — نفس الطلب» (الدالة تعيش داخل الـeffect) */
  const retryRef = useRef(null);
  /* ★ FE17-F04: قفل تزامني فوري ضد النقر المزدوج (قبل setState غير المتزامنة) */
  const retryLockRef = useRef(false);
  /* ★ FE17-F04: نبضة العد التنازلي للانتظار (عرض فقط — القرار للخادم) */
  const [tick, setTick] = useState(0);

  const pending = readPendingPayment();
  /* ★ cartId هو المرجع الوحيد (§10) — من رابط العودة أو الدفعة المعلّقة */
  const cartId =
    params.get("cartId") ||
    params.get("cart_id") ||
    (pending && (pending.cartId || pending.cart_id)) ||
    "";
  /* ★ مرجع قديم (merchantReference) من دفعات ما قبل العقد — لا استعلام له
     (attempts مُتقاعَدة) — يُوجَّه صاحبه لصفحة «راجع طلباتي» */
  const legacyRef =
    params.get("merchantReference") ||
    params.get("merchant_reference") ||
    params.get("merchantRef") ||
    params.get("reference") ||
    params.get("ref") ||
    (pending && (pending.merchantReference || pending.merchant_reference || pending.reference)) ||
    "";
  const hasRef = !!cartId;
  const legacyOnly = !cartId && !!legacyRef;

  useEffect(
    function () {
      if (!customerId || !hasRef) return;
      if (!authResolved) return;
      let alive = true;
      let timer = 0;
      /* ★ #10: إلغاء الطلبات عند المغادرة/تبديل الحساب — لا استجابة قديمة بعد التبديل */
      let aborter = null;
      try { aborter = new AbortController(); } catch (e) { aborter = null; }
      const myCustomer = Number(customerId);

      function fail(msg) {
        if (!alive) return;
        setPhase("failed");
        setNote(msg || "");
      }

      /* ★ v17-P1: رفض نهائي — أول رفض يسمح بالإعادة (نفس OrderId)، والثاني
         يعرض الإلغاء والانتظار (retryAfter من الخادم). الحكم من حقول صريحة
         لا من رابط العودة وحده. العدد الغائب = إعادة مسموحة (الخادم يفرض
         الإلغاء عند الثاني) — لا نمنع محاولة قد تكون الأولى. */
      function failAttempt(st) {
        if (!alive) return;
        let info = null;
        try { info = resolvePaymentOutcome({}, st || {}); } catch (e) { info = null; }
        const oid = attemptOrderId(st, pending) || Number((readPendingPayment() || {}).orderId) || 0;
        const cancelled = !!(info && info.isCancelled);
        const fails = info && info.failedAttempts != null ? Number(info.failedAttempts) : null;
        const retryAfter = info ? info.retryAfterSeconds : null;
        const aid = info ? info.attemptId : "";
        function decide(failCount) {
          if (!alive) return;
          const second = cancelled || (failCount != null && Number(failCount) >= 2);
          /* ★ FE17-F04: نهاية الانتظار المحفوظة للعد التنازلي (عرض فقط) */
          const waitSecs = retryAfter != null ? Number(retryAfter) : null;
          try {
            setAttempt({ failedAttempts: failCount, canRetry: !!(info && info.canRetry), retryAfterSeconds: retryAfter, attemptId: aid || "", orderId: oid || 0, waitUntilMs: waitSecs != null && waitSecs > 0 ? Date.now() + Math.round(waitSecs) * 1000 : null });
          } catch (e) {}
          if (second) {
            setPhase("failed-final");
            setNote("");
          } else {
            setPhase("failed-retry");
            setNote("");
          }
        }
        /* العدد غائب وغير ملغي؟ نجلب تفاصيل الطلب مرة واحدة للتدقيق —
           فإن تعذّر، الافتراض الآمن = إعادة مسموحة (الخادم يفرض الحد). */
        if (!cancelled && fails == null && oid) {
          fetchServerOrderDetail(Number(customerId), Number(oid)).then(
            function (detail) {
              if (!alive) return;
              let refined = null;
              try { refined = resolvePaymentOutcome(detail, st || {}); } catch (e) { refined = null; }
              info = refined || info;
              decide(info && info.failedAttempts != null ? Number(info.failedAttempts) : (info && info.isCancelled ? 2 : null));
            },
            function () { decide(null); }
          );
          return;
        }
        decide(fails);
      }

      /* ★ v17-P1: إعادة المحاولة على الطلب نفسه — بفحص مسبق (لا Start أعمى):
         نستعلم أولاً؛ فإن بقي قابلاً للإعادة نبدأ attempt جديداً لنفس OrderId
         ونغادر لصفحة البوابة. 409 مدفوع = الـcallback سوّاها → نعرض الفاتورة.
         ★ FE17-F04: بوابة صريحة على الحالة الحديثة (retryGate) — canRetry=false
         أو انتظار نشط أو غياب إذن صريح أو ملغى/مجهول = لا Start. قفل تزامني
         فوري ضد النقر المزدوج، وحراسة الحساب قبل Start وقبل المغادرة. */
      function releaseRetry() {
        retryLockRef.current = false;
        if (alive) setRetryBusy(false);
      }
      function gateMessage(reason) {
        if (reason === "cancelled") return "أُلغي الطلب — لا يمكن إعادة الدفع. راجع «طلباتي».";
        if (reason === "already-paid") return "تم الدفع — نجلب الفاتورة.";
        if (reason === "verify") return "نتيجة الدفع غير محسومة — نتحقق أولاً ولا نبدأ محاولة جديدة.";
        if (reason === "forbidden") return "الخادم رفض إعادة الدفع لهذا الطلب — راجع «طلباتي» أو كلم الدعم.";
        if (reason === "missing-permission") return "لم يصل إذن إعادة صريح من الخادم — راجع «طلباتي» ولا تعِد الضغط.";
        if (reason === "waiting") return "ما زالت مدة الانتظار مستمرة — انتظر انتهاء العد التنازلي.";
        return "تعذّرت إعادة الدفع الآن — راجع «طلباتي».";
      }
      function retrySameOrder() {
        if (!alive || retryBusy || retryLockRef.current) return;
        const oid = (attempt && attempt.orderId) || attemptOrderId(null, pending) || Number((readPendingPayment() || {}).orderId) || 0;
        if (!oid) {
          fail("تعذّر تحديد الطلب لإعادة الدفع — أكمل من «طلباتي».");
          return;
        }
        retryLockRef.current = true;
        setRetryBusy(true);
        queryStatus().then(
          function (st) {
            if (!alive) { retryLockRef.current = false; return; }
            const raw = (st && (st.status || st.state || st.paymentStatus || st.result)) || "";
            const s = normStatus(raw);
            if (s === "success") {
              retryLockRef.current = false;
              setRetryBusy(false);
              const id2 = attemptOrderId(st, pending) || oid;
              fetchServerOrderDetail(Number(customerId), Number(id2)).then(
                function (detail) { setRetryBusy(false); succeed(st, detail); },
                function () { setRetryBusy(false); fail("تم الدفع — وتعذّر جلب الفاتورة. ستجد طلبك في «طلباتي»."); }
              );
              return;
            }
            if (s !== "fail") {
              /* ما زال معلقاً/مجهولاً — لا Start جديد، شاشة تحقق */
              retryLockRef.current = false;
              setRetryBusy(false);
              setPhase("waiting");
              return;
            }
            /* ★ FE17-F04: البوابة على الحالة الحديثة قبل أي Start */
            let gate = null;
            try { gate = retryGate(st, Date.now(), (attempt && attempt.waitUntilMs) || null); } catch (e) { gate = null; }
            if (!gate || !gate.allowed) {
              const reason = (gate && gate.reason) || "verify";
              if (reason === "waiting" && gate && gate.waitUntilMs) {
                try { setAttempt(Object.assign({}, attempt, { waitUntilMs: Number(gate.waitUntilMs) })); } catch (e) {}
                retryLockRef.current = false;
                setRetryBusy(false);
                return;
              }
              if (reason === "cancelled") {
                try { setAttempt(Object.assign({}, attempt, { orderId: oid })); } catch (e) {}
                retryLockRef.current = false;
                setRetryBusy(false);
                setPhase("failed-final");
                setNote("");
                return;
              }
              if (reason === "already-paid") {
                retryLockRef.current = false;
                setRetryBusy(false);
                const id3 = attemptOrderId(st, pending) || oid;
                fetchServerOrderDetail(Number(customerId), Number(id3)).then(
                  function (detail) { setRetryBusy(false); succeed(st, detail); },
                  function () { setRetryBusy(false); fail("تم الدفع — وتعذّر جلب الفاتورة. ستجد طلبك في «طلباتي»."); }
                );
                return;
              }
              retryLockRef.current = false;
              setRetryBusy(false);
              if (reason === "verify") setPhase("waiting");
              else fail(gateMessage(reason));
              return;
            }
            /* ★ FE17-F04: حراسة الحساب لحظة Start — تبدّل أثناء الاستعلام = توقف */
            if (Number(customerId) !== myCustomer) {
              retryLockRef.current = false;
              setRetryBusy(false);
              fail("تبدلت الجلسة أثناء إعادة الدفع — سجّل الدخول بالحساب الصحيح وراجع «طلباتي».");
              return;
            }
            startServerPayment(Number(customerId), Number(oid)).then(
              function (r) {
                if (!alive || Number(customerId) !== myCustomer) {
                  retryLockRef.current = false;
                  setRetryBusy(false);
                  return;
                }
                const url = r && (r.paymentUrl || r.payment_url);
                if (!url) {
                  retryLockRef.current = false;
                  setRetryBusy(false);
                  fail("تعذّر فتح صفحة الدفع — حاول مجدداً من «طلباتي».");
                  return;
                }
                try {
                  savePendingPayment(Object.assign({}, readPendingPayment() || {}, {
                    customerId: Number(customerId),
                    orderId: Number(oid),
                    cartId: String((r && (r.cartId || r.cart_id)) || cartId || ""),
                    tranRef: String((r && (r.tranRef || r.tran_ref)) || "")
                  }));
                } catch (e) {}
                retryLockRef.current = false;
                setRetryBusy(false);
                window.location.href = String(url);
              },
              function (err) {
                if (!alive) return;
                retryLockRef.current = false;
                setRetryBusy(false);
                /* ★ FE19-7: رفض إعادة البدء الصريح (رموز منظمة) — لا Start
                   جديد ولا إنشاء طلب بديل تلقائياً؛ توجيه لـ«طلباتي» فقط. */
                let rejCode = null;
                try { rejCode = classifyRetryReject(err && err.response && err.response.data, err && err.status); } catch (eR) { rejCode = null; }
                if (rejCode) {
                  fail("رفض الخادم إعادة الدفع لهذا الطلب (" + rejCode + ") — لا يمكن فتح محاولة جديدة. راجع «طلباتي» أو كلم الدعم.");
                  return;
                }
                if (err && err.status === 409) {
                  if (!settleFromOrderFallback()) fail("طُلب الدفع لطلب محسوم — راجع «طلباتي».");
                  return;
                }
                /* ★ FE17-F04: حد المعدل 429 يُعرض بمعناه مع الانتظار المعروف */
                if (err && err.status === 429) {
                  const w = attempt && attempt.waitUntilMs ? Math.max(0, Math.ceil((Number(attempt.waitUntilMs) - Date.now()) / 1000)) : 0;
                  fail("الخادم مشغول (تجاوزت حد الطلبات)" + (w > 0 ? " — انتظر " + w + " ثانية ثم أعد من «طلباتي»." : " — انتظر قليلاً ثم أعد من «طلباتي»."));
                  return;
                }
                fail("تعذّر بدء محاولة الدفع — تحقق من الاتصال ثم أعد المحاولة.");
              }
            );
          },
          function () {
            if (!alive) { retryLockRef.current = false; return; }
            retryLockRef.current = false;
            setRetryBusy(false);
            fail("تعذّر التحقق قبل إعادة الدفع — تحقق من الاتصال ثم أعد المحاولة.");
          }
        );
      }

      /* ★ البند 19: دفعة معلقة لحساب آخر لا تُقرأ بهوية مختلفة */
      const pend0 = readPendingPayment() || {};
      if (pend0.customerId && Number(pend0.customerId) !== Number(customerId)) {
        try {
          clearPendingPayment();
        } catch (e) {}
        fail("تبدلت الجلسة أثناء الدفع — سجّل الدخول بالحساب الصحيح وراجع «طلباتي».");
        return;
      }

      function succeed(status, detail) {
        if (!alive) return;
        const meta = currencyMeta(profileCurrency);
        const pend = readPendingPayment() || {};
        /* ★ F6: مسار النجاح يستخدم resolvePaymentOutcome نفسها (لا منطق مكرر) —
           وإلا اختبرت الدالة المصدّرة شيئاً لا يستدعيه التطبيق. */
        const outcome = resolvePaymentOutcome(detail, status);
        /* ★ FE19-6: حارس الدليل الصريح — لا فاتورة نجاح بلا دليل (phase غير
           paid/paid-attention تعني أن المستدعي أخطأ المسار؛ نسقط لشاشة تحقق). */
        if (outcome.phase !== "paid" && outcome.phase !== "paid-attention") {
          setPhase("waiting");
          return;
        }
        const payRaw = outcome.payRaw;
        const ordRaw = outcome.ordRaw;
        const revRaw = outcome.revRaw;
        const isCancelled = outcome.isCancelled;
        /* ★ المراجعة المفتوحة تُعرض بوضوح — ولا ندّعي أن الاسترداد تم لمجردها */
        const reviewOpen = outcome.reviewOpen;
        const needsRefund = reviewOpen;
        try { setPayState(payRaw || "paid"); } catch (e) {}
        try { setOrderState(ordRaw || ""); } catch (e) {}
        try { setReviewState(revRaw || ""); } catch (e) {}
        const built = normalizeServerOrder(detail, {
          method: pend.method || "",
          methodLabel: methodLabelOf(pend.method, language) || String(status.paymentMethod || status.payment_method || ""),
          kind: kindOf(pend.method),
          customer: pend.customer || {},
          currency: { key: meta.key, rate: meta.rate, decimals: meta.decimals, symbol: meta.symbol, symbolEn: meta.symbolEn, position: meta.position }
        });
        /* ★ FE24-F3: الإسناد الفعلي للمسار الإلكتروني (ونفسه في replay عبر
           settleFromOrderFallback → succeed): صدى التفاصيل (applied صريح)
           مقابل اللقطة المرسلة المحفوظة في المعلق (requested). applied=false
           يزيل الإسناد ولو وصل code؛ غياب الحقول (باك قديم) = غير مؤكد لا
           مطبق — بلا ادعاء عمولة/نجاح إسناد من localStorage وحده. */
        try {
          const attrRes = resolveAttribution(detail, (pend && pend.referral) || null);
          built.affiliateRequested = attrRes ? attrRes.requested : null;
          built.affiliateApplied = attrRes && attrRes.applied ? attrRes.applied : null;
          built.affiliateAttributionConfirmed = !!(attrRes && attrRes.confirmed);
          if (attrRes && attrRes.mismatch) built.attributionMismatch = true;
          if (attrRes && attrRes.applied && attrRes.applied.code) {
            built.affiliateCode = String(attrRes.applied.code);
            if (attrRes.applied.visitId) built.affiliateVisitId = String(attrRes.applied.visitId);
          }
        } catch (eA) {}
        dispatch(ordersActions.orderPlaced(built));
        /* ★ البند 5: تسوية لا مسح شامل — المستبعدة والمضافة أثناء
           البوابة تبقى؛ وفشل التفريغ تحذير قابل للاستعادة. */
        try {
          Promise.resolve(dispatch(settleBasketAfterOrder(Number(customerId), built.items, built.skipped, built.invoiceNo, built.serverId || built.invoiceNo))).then(function (ok) {
            if (!alive) return;
            if (!ok) setBasketWarn("طلبك مدفوع ومحفوظ — وتعذّر تفريغ بعض سطور الخادم. ستُزامَن تلقائياً عند فتح العربة.");
          });
        } catch (e) {}
        built.payState = payRaw;
        built.orderState = ordRaw;
        built.reviewState = revRaw;
        built.orderCancelled = isCancelled;
        /* ★ F6: needsRefundReview علَم مباشر — لا ادعاء استرداد تم لمجرد فتحها.
           التحصيل المؤكد + طلب ملغى/مراجعة = شاشة انتباه لا «مؤكد». */
        built.needsRefund = reviewOpen;
        built.needsRefundReview = needsRefund;
        /* ★ #10: المرجع غير المحسوم يُحفظ للمتابعة من «طلباتي» */
        if (!isCancelled && !reviewOpen) {
          try { clearPendingPayment(); } catch (e) {}
        }
        setOrder(built);
        if (isCancelled || reviewOpen) setPhase("paid-attention");
        else setPhase("paid");
        try {
          window.scrollTo(0, 0);
        } catch (e) {}
      }

      /* ★ #10: صفحة النتيجة استعلام فقط — ممنوع إنشاء الطلب أو Start تلقائياً منها */
      function queryStatus() {
        if (Number(customerId) !== myCustomer) return Promise.reject({ status: 0, code: "EABORTED", message: "account-switched" });
        return getPaymentStatus(Number(customerId), String(cartId));
      }

      /* ★ 409 بعد الدفع = الـcallback سوّاها غالباً (§10) —
         نعيد قراءة تفاصيل الطلب بدل الفشل */
      function settleFromOrderFallback() {
        const pend = readPendingPayment() || {};
        const oid = Number(pend.orderId) || 0;
        if (!oid) return false;
        fetchServerOrderDetail(Number(customerId), oid).then(
          function (detail) {
            if (!alive) return;
            /* ★ FE19-6: دليل النجاح الصريح عبر normStatus الموحد (لا سلسلة
               indexOf مبعثرة) — بدونه لا فاتورة نجاح. */
            const paidRaw = detail && (detail.paymentStatus != null ? detail.paymentStatus : detail.payment_status);
            if (normStatus(paidRaw) === "success") {
              succeed({ paymentMethod: detail.paymentMethod }, detail);
            } else {
              fail("سُجّل طلبك بانتظار تأكيد الدفع — ستجده محدّثاً في «طلباتي» تلقائياً.");
            }
          },
          function () {
            if (!alive) return;
            fail("تعذّر التأكد من الدفع الآن — راجع «طلباتي» بعد قليل، وإن خُصم المبلغ سيظهر مدفوعاً.");
          }
        );
        return true;
      }

      function check() {
        tries.current += 1;
        queryStatus().then(
          function (st) {
            if (!alive) return;
            const raw = (st && (st.status || st.state || st.paymentStatus || st.result)) || "";
            const s = normStatus(raw);
            if (s === "success") {
              const oid = attemptOrderId(st, pending);
              if (!oid) {
                fail("تم الدفع — وتعذّر جلب الفاتورة. ستجد طلبك في «طلباتي».");
                return;
              }
              fetchServerOrderDetail(Number(customerId), Number(oid)).then(
                function (detail) {
                  succeed(st, detail);
                },
                function () {
                  fail("تم الدفع — وتعذّر جلب الفاتورة. ستجد طلبك في «طلباتي».");
                }
              );
              return;
            }
            if (s === "unknown") {
              /* ★ v17-P1: نتيجة غير معلومة = شاشة تحقق — لا فشل نهائي ولا Start تلقائي */
              setPhase("waiting");
              return;
            }
            if (s === "fail") {
              failAttempt(st);
              return;
            }
            if (tries.current >= POLL_MAX) {
              setPhase("waiting");
              return;
            }
            timer = window.setTimeout(check, POLL_EVERY_MS);
          },
          function (err) {
            if (!alive) return;
            /* ★ البند 14: انقطاع الشبكة ≠ فشل دفع — علّمه وتابع الاستطلاع */
            if (err && (err.status === 0 || err.code === "ECONNABORTED" || err.message === "timeout")) {
              setNetFail(true);
            }
            if (err && (err.status === 404 || err.status === 501)) {
              setPhase("unready");
              return;
            }
            /* ★ 409 = غالباً تسوية الـcallback — أعد قراءة الطلب */
            if (err && err.status === 409) {
              if (settleFromOrderFallback()) return;
            }
            if (tries.current >= POLL_MAX) {
              setPhase("waiting");
              return;
            }
            timer = window.setTimeout(check, POLL_EVERY_MS);
          }
        );
      }

      try { retryRef.current = retrySameOrder; } catch (e) {}
      check();
      return function () {
        alive = false;
        try { retryRef.current = null; } catch (e) {}
        if (timer) window.clearTimeout(timer);
        try { if (aborter) aborter.abort(); } catch (e) {}
      };
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [customerId, cartId, authResolved, refreshTick]
  );

  /* ★ FE22-R02: تحديث يدوي للحالة — قراءة فقط (يُعيد تشغيل الـeffect
     عبر refreshTick)، بلا بدء خصم جديد إطلاقاً. */
  function onRefreshStatus() {
    try {
      if (phase === "checking" || phase === "waiting") {
        setPhase("checking");
        setRefreshTick(function (x) { return (Number(x) || 0) + 1; });
      }
    } catch (e) {}
  }

  /* ★ v17-P1: معالج زر الإعادة على مستوى المكوّن */
  function onRetrySameOrder() {
    try { if (retryRef.current) retryRef.current(); } catch (e) {}
  }

  /* ★ FE17-F04: نبضة العد التنازلي أثناء شاشة الرفض الأول (عرض فقط) */
  useEffect(
    function () {
      if (phase !== "failed-retry") return undefined;
      let t = 0;
      try {
        t = window.setInterval(function () {
          setTick(function (x) { return x + 1; });
        }, 1000);
      } catch (e) { t = 0; }
      return function () {
        try { if (t) window.clearInterval(t); } catch (e) {}
      };
    },
    [phase]
  );

  /* ---------- بلا جلسة ---------- */
  if (!customerId) {
    return (
      <section className="container view ck ct" id="paymentReturnView">
        <div className="ct-empty">
          <span className="ct-empty-ic">
            <Icon name="user" strokeWidth={1.6} />
          </span>
          <h3>سجّل الدخول لعرض نتيجة الدفع</h3>
          <p>انتهت الجلسة أثناء الدفع — سجّل الدخول وستجد طلبك في «طلباتي».</p>
          <div className="wl-empty-actions">
            <Link className="btn-primary" to={PATHS.login}>
              تسجيل الدخول
            </Link>
            <Link className="btn-ghost" to={PATHS.profile}>
              طلباتي
            </Link>
          </div>
        </div>
      </section>
    );
  }

  /* ---------- بلا مرجع دفع ---------- */
  if (!hasRef) {
    return (
      <section className="container view ck ct" id="paymentReturnView">
        <div className="ct-empty">
          <span className="ct-empty-ic">
            <Icon name="cart" strokeWidth={1.6} />
          </span>
          <h3>{legacyOnly ? "راجع حالة طلبك في «طلباتي»" : "لا توجد عملية دفع هنا"}</h3>
          <p>
            {legacyOnly
              ? "عملية الدفع هذه من نسخة قديمة بلا رقم سلة — لا يمكن الاستعلام عنها مباشرة، لكن طلبك محفوظ وستجد حالته (مدفوع/بانتظار الدفع) في «طلباتي»."
              : "لم نجد رقم سلة للدفع (cartId) — أكمل طلبك من العربة وستُحوَّل لصفحة الدفع الآمنة."}
          </p>
          <div className="wl-empty-actions">
            {legacyOnly ? (
              <Link className="btn-primary" to={PATHS.profile}>
                طلباتي
              </Link>
            ) : (
              <Link className="btn-primary" to={PATHS.cart}>
                العربة
              </Link>
            )}
            <Link className="btn-ghost" to={PATHS.profile}>
              طلباتي
            </Link>
          </div>
        </div>
      </section>
    );
  }

  /* ---------- ناجح: الفاتورة ---------- */
  if (phase === "paid" && order) {
    return (
      <section className="container view ck ct" id="paymentReturnView">
        <header className="ck-done-head">
          <span className="ck-done-ic">
            <Icon name="check" strokeWidth={2.6} />
          </span>
          <span className="eyebrow">تم الدفع</span>
          <h1>
            شكراً لك — <span className="gold-text">دُفع طلبك بنجاح</span>
          </h1>
          <p className="ck-done-sub">
            استلمنا مبلغ فاتورتك برقم <b>#{order.invoiceNo}</b>، وأفرغنا العربة.
          </p>
          {basketWarn ? (
            <p className="ck-auth-warn">{basketWarn}</p>
          ) : null}
        </header>

        <div className="ck-done-actions">
          <Link className="btn-ghost" to={PATHS.profile}>
            <Icon name="doc" strokeWidth={1.8} />
            <span>طلباتي</span>
          </Link>
          <Link className="btn-ghost" to={PATHS.perfumes}>
            <Icon name="cart" strokeWidth={1.8} />
            <span>متابعة التسوق</span>
          </Link>
        </div>

        <Invoice order={order} language={language} />
      </section>
    );
  }

  /* ★ #10: دفع ناجح وطلب يحتاج انتباهاً (ملغى/استرداد/مراجعة) — لا «مؤكد» */
  if (phase === "paid-attention" && order) {
    return (
      <section className="container view ck ct" id="paymentReturnView">
        <header className="ck-done-head">
          <span className="ct-empty-ic">
            <Icon name="alert" strokeWidth={2} />
          </span>
          <span className="eyebrow">الدفع مسجّل — الطلب يحتاج متابعة</span>
          <h1>
            دفعك مسجّل — <span className="gold-text">راجع حالة طلبك</span>
          </h1>
          <p className="ck-done-sub">
            رقم الطلب <b>#{order.invoiceNo}</b> — حالته لا تعني التأكيد النهائي. تابع من «طلباتي».
          </p>
          <div className="ck-skipped" role="status">
            <p>حالة الدفع: <b>{payState || order.payState || "مسجّل"}</b></p>
            <p>حالة الطلب: <b>{orderState || order.orderState || order.statusAr || ""}</b></p>
            {reviewState || order.reviewState ? (
              <p>المراجعة/الاسترداد: <b>{reviewState || order.reviewState}</b></p>
            ) : null}
            <p className="ck-hint">النتيجة المجهولة تبقى «جارٍ التحقق» — لا نعلن نجاحاً أو فشلاً نهائياً من قراءة واحدة.</p>
          </div>
          {basketWarn ? (
            <p className="ck-auth-warn">{basketWarn}</p>
          ) : null}
        </header>
        <div className="ck-done-actions">
          <Link className="btn-primary" to={PATHS.profile}>
            <Icon name="doc" strokeWidth={1.8} />
            <span>طلباتي — متابعة العملية</span>
          </Link>
          <Link className="btn-ghost" to={PATHS.contact}>
            <span>كلم الدعم</span>
          </Link>
        </div>
        <Invoice order={order} language={language} />
      </section>
    );
  }

  /* ★ v17-P1: أول رفض نهائي — إعادة مسموحة على الطلب نفسه (لا طلب جديد) */
  if (phase === "failed-retry") {
    /* ★ FE17-F04: العد التنازلي للعرض فقط — الزر معطل حتى انتهائه،
       وعند الضغط يُجلب status حديث وتُطبَّق البوابة قبل أي Start. */
    const waitLeft = (function () {
      try {
        const until = attempt && attempt.waitUntilMs != null ? Number(attempt.waitUntilMs) : 0;
        if (!(until > 0)) return 0;
        return Math.max(0, Math.ceil((until - Date.now()) / 1000));
      } catch (e) { return 0; }
    })();
    void tick;
    const waitTxt = waitLeft > 0
      ? (waitLeft >= 60 ? "انتظر نحو " + Math.round(waitLeft / 60) + " دقيقة قبل إعادة المحاولة." : "انتظر " + waitLeft + " ثانية قبل إعادة المحاولة.")
      : "";
    return (
      <section className="container view ck ct" id="paymentReturnView">
        <div className="ct-empty">
          <span className="ct-empty-ic">
            <Icon name="alert" strokeWidth={1.6} />
          </span>
          <h3>رُفضت محاولة الدفع</h3>
          <p>هذه المحاولة الأولى المرفوضة نهائياً — يمكنك إعادة المحاولة على نفس الطلب (رقم {(attempt && attempt.orderId) || "—"}) دون إنشاء طلب جديد. عربتك محفوظة كما هي.{waitTxt ? " " + waitTxt : ""}</p>
          <div className="wl-empty-actions">
            <button className="btn-primary" type="button" disabled={retryBusy || waitLeft > 0} onClick={onRetrySameOrder}>
              {retryBusy ? "نتحقق ونفتح البوابة…" : waitLeft > 0 ? "إعادة المحاولة بعد " + waitLeft + " ث" : "إعادة المحاولة — نفس الطلب"}
            </button>
            <Link className="btn-ghost" to={PATHS.profile}>
              طلباتي
            </Link>
            <Link className="btn-ghost" to={PATHS.cart}>
              العربة
            </Link>
            <Link className="btn-ghost" to={PATHS.contact}>
              كلم الدعم
            </Link>
          </div>
        </div>
      </section>
    );
  }

  /* ★ v17-P1: ثاني رفض نهائي — الطلب ملغي + انتظار retryAfter من الخادم.
     لا زر إعادة هنا: أي تحصيل لاحق يذهب للمراجعة المالية. */
  if (phase === "failed-final") {
    const waitSecs = attempt && attempt.retryAfterSeconds != null ? Number(attempt.retryAfterSeconds) : null;
    const waitTxt = waitSecs != null && waitSecs > 0
      ? (waitSecs >= 60 ? "انتظر نحو " + Math.round(waitSecs / 60) + " دقيقة قبل أي إجراء جديد." : "انتظر " + waitSecs + " ثانية قبل أي إجراء جديد.")
      : "انتظر قليلاً قبل أي إجراء جديد.";
    return (
      <section className="container view ck ct" id="paymentReturnView">
        <div className="ct-empty">
          <span className="ct-empty-ic">
            <Icon name="x" strokeWidth={1.6} />
          </span>
          <h3>أُلغي الطلب — رُفض الدفع نهائياً</h3>
          <p>رُفض الدفع للمرة الثانية، فأُلغي الطلب. {waitTxt} إن خُصم أي مبلغ سيظهر في «طلباتي» للمراجعة المالية — لا تنشئ دفعاً جديداً لنفس السلة فوراً.</p>
          <div className="wl-empty-actions">
            <Link className="btn-primary" to={PATHS.profile}>
              طلباتي — متابعة الحالة
            </Link>
            <Link className="btn-ghost" to={PATHS.contact}>
              كلم الدعم
            </Link>
          </div>
        </div>
      </section>
    );
  }

  /* ---------- فاشل/ملغي: صفحة خطأ واضحة — أعد المحاولة أو كلم الدعم ---------- */
  if (phase === "failed") {
    return (
      <section className="container view ck ct" id="paymentReturnView">
        <div className="ct-empty">
          <span className="ct-empty-ic">
            <Icon name="alert" strokeWidth={1.6} />
          </span>
          <h3>حدث خطأ ما</h3>
          <p>{note || tr2(language, "The payment did not complete — please try again later or contact support. Your cart is kept as is.", "لم تتم عملية الدفع — أعد المحاولة لاحقاً أو كلم الدعم. عربتك محفوظة كما هي.")}</p>
          <div className="wl-empty-actions">
            <Link className="btn-primary" to={PATHS.checkout}>
              المحاولة مجدداً
            </Link>
            <Link className="btn-ghost" to={PATHS.cart}>
              العربة
            </Link>
            <Link className="btn-ghost" to={PATHS.perfumes}>
              العودة للمتجر
            </Link>
            <Link className="btn-ghost" to={PATHS.contact}>
              كلم الدعم
            </Link>
          </div>
        </div>
      </section>
    );
  }

  /* ---------- الخدمة غير جاهزة بعد ---------- */
  if (phase === "unready") {
    return (
      <section className="container view ck ct" id="paymentReturnView">
        <div className="ct-empty">
          <span className="ct-empty-ic">
            <Icon name="info" strokeWidth={1.6} />
          </span>
          <h3>الدفع الإلكتروني يُجهَّز الآن</h3>
          <p>طلبك محفوظ بانتظار الدفع — أكمله نقداً عند الاستلام أو عُد قريباً للدفع بالبطاقة.</p>
          <div className="wl-empty-actions">
            <Link className="btn-primary" to={PATHS.profile}>
              طلباتي
            </Link>
            <Link className="btn-ghost" to={PATHS.checkout}>
              إتمام الدفع
            </Link>
          </div>
        </div>
      </section>
    );
  }

  /* ---------- فحص/انتظار ---------- */
  return (
    <section className="container view ck ct" id="paymentReturnView">
      <div className="ct-empty">
        <span className="ct-empty-ic">
          <Icon name="lock" strokeWidth={1.6} />
        </span>
        <h3>{phase === "waiting" ? "الدفع قيد المراجعة" : "نتحقق من الدفع…"}</h3>
        <p>
          {phase === "waiting"
            ? "لم يصل التأكيد بعد — إن خُصم المبلغ سيظهر طلبك مدفوعاً في «طلباتي» تلقائياً."
            : "لحظات ونعرض النتيجة — لا تغلق الصفحة."}
        </p>
        {netFail && phase !== "waiting" ? (
          <p className="ck-hint">انقطع الاتصال أثناء التحقق — نعيد المحاولة تلقائياً، ولا تغلق الصفحة.</p>
        ) : null}
        <div className="wl-empty-actions">
          {/* ★ FE22-R02: تحديث الحالة قراءةً فقط + دعم — بلا بدء خصم جديد */}
          <button className="btn-primary" type="button" onClick={onRefreshStatus}>
            تحديث الحالة
          </button>
          <Link className="btn-ghost" to={PATHS.profile}>
            طلباتي
          </Link>
          <Link className="btn-ghost" to={PATHS.contact}>
            كلم الدعم
          </Link>
        </div>
      </div>
    </section>
  );
}
