import { CATALOG_META, ATYAB_GENDERS } from "./appConfig.js";

/* ============================================================
   أطياب الجاسم — جسر المنتجات (مؤقت)
   ⚠ ملف انتقالي فقط: يُبقي الشاشات القديمة تعمل أثناء نقلها
   حبة حبة إلى Redux. كل دالة تقرأ من الـ store الحي (لا بيانات
   ثابتة هنا إطلاقاً). يُحذف نهائياً عند اكتمال النقل.
   ============================================================ */

function liveState() {
  try {
    return typeof window !== "undefined" && window.__ATYAB_STORE__
      ? window.__ATYAB_STORE__.getState()
      : null;
  } catch (e) {
    return null;
  }
}

function liveList() {
  const s = liveState();
  if (!s) return [];
  const out = [];
  ["perfumes", "ouds", "incenses"].forEach(function (k) {
    const list = s[k] && s[k].list;
    if (list) out.push.apply(out, list);
  });
  return out;
}

function liveGallery(productId) {
  try {
    const s = typeof window !== "undefined" && window.__ATYAB_STORE__
      ? window.__ATYAB_STORE__.getState()
      : null;
    const g = s && s.images && s.images.galleries;
    return (g && g[Number(productId)]) || null;
  } catch (e) {
    return null;
  }
}

function metaFor(key) {
  if (key === "incense" || key === "ouds") return CATALOG_META[key];
  return CATALOG_META.perfumes;
}

export function ATYAB_allProducts() {
  return liveList();
}

/* ★ منتجات العروض: تُبنى ككائنات منتج خفيفة من شريحة العروض الحية،
   حتى تعمل السلة وأزرار الإضافة عليها (السلة تقرأ عبر ATYAB_byId). */
/* ★ الباقة كوحدة واحدة: id من 9000000+ — تُبنى من العرض نفسه
   (الاسم + السعر النهائي + الصورة)، فتُضاف للسلة قطعة واحدة. */
function offerBundleById(num) {
  try {
    const s = liveState();
    const offers = (s && s.offers && s.offers.items) || [];
    for (let i = 0; i < offers.length; i++) {
      if (Number(offers[i].bundleId) !== num) continue;
      const o = offers[i];
      const items = o.items || [];
      const first = items[0] || {};
      const t = Number(first.typeId);
      const kind = t === 2 ? "incense" : t === 3 ? "oud" : "perfume";
      const before = Number(o.priceBefore) || items.reduce(function (x, it) { return x + (Number(it.price) || 0); }, 0);
      const price = Number(o.finalPrice) || items.reduce(function (x, it) { return x + (Number(it.finalPrice) || Number(it.price) || 0); }, 0) || before;
      const left = o.stockLeft == null ? null : Math.max(0, Number(o.stockLeft) || 0);
      return {
        id: num, productId: num, productTypeId: t || 0, kind: kind,
        kindLabel: t === 2 ? "بخور" : t === 3 ? "عود" : "عطر", kindLabelEn: kind === "perfume" ? "Perfume" : kind,
        name: o.nameAr || o.nameEn || o.name || "باقة", nameEn: o.nameEn || o.nameAr || o.name || "Bundle",
        desc: o.taglineAr || "", descEn: o.taglineEn || "",
        price: price, oldPrice: before > price ? before : null,
        saveAmount: before > price ? before - price : 0,
        sales: 0, rating: 0, reviews: 0,
        /* ★ مخزون الباقة: معروف يُحترَم (الصفر صفر → حجز واتساب)،
           ومجهول يبقى مجهولاً (null = بلا سقف، والخادم المرجع) */
        stock: left,
        inStock: left == null ? true : left > 0, isActive: true, size: "", sizeEn: "", gender: "unisex",
        searchType: kind, image: o.mainImageUrl || null, placeholder: null,
        offer: "باقة", offerEn: "Bundle", bundleOf: o.id
      };
    }
  } catch (e) {}
  return null;
}

function offerProductById(num) {
  /* ★ سطر التحويل المفقود: معرّفات 9000000+ باقات لا منتجات */
  if (num >= 9000000) return offerBundleById(num);
  try {
    const s = liveState();
    const offers = (s && s.offers && s.offers.items) || [];
    for (let i = 0; i < offers.length; i++) {
      const items = offers[i].items || [];
      for (let j = 0; j < items.length; j++) {
        if (Number(items[j].id) === num) {
          const it = items[j];
          const t = Number(it.typeId);
          const kind = t === 2 ? "incense" : t === 3 ? "oud" : "perfume";
          const kindLabel = t === 2 ? "بخور" : t === 3 ? "عود" : "عطر";
          const price = Number(it.finalPrice) > 0 ? Number(it.finalPrice) : Number(it.price) || 0;
          const before = Number(it.price) || 0;
          return {
            id: num, productId: num, productTypeId: t, kind: kind,
            kindLabel: kindLabel, kindLabelEn: kind === "perfume" ? "Perfume" : kind,
            name: it.nameAr || it.nameEn || "عرض", nameEn: it.nameEn || it.nameAr || "Offer",
            desc: it.titleAr || "", descEn: it.titleEn || "",
            price: price, oldPrice: before > price ? before : null,
            saveAmount: before > price ? before - price : 0,
            sales: 0, rating: 0, reviews: 0,
            /* ★ مخزون سطر العرض غير معروف (لا حقل مخزون في العرض):
               null = بلا سقف محلي، والخادم هو المرجع (409 عند النفاد) */
            stock: null,
            inStock: true, isActive: true, size: "", sizeEn: "", gender: "unisex",
            searchType: kind, image: it.mainImageUrl || null, placeholder: null,
            offer: "عرض", offerEn: "Offer"
          };
        }
      }
    }
  } catch (e) {}
  return null;
}

export function ATYAB_byId(id) {
  const num = Number(id);
  const list = liveList();
  for (let i = 0; i < list.length; i++) {
    if (Number(list[i].id) === num) {
      const p = list[i];
      /* ★ إرفاق الصورة الأساسية من شريحة الصور حيثما طُلب المنتج */
      const st = liveState();
      const url = st && st.images && st.images.main[num];
      return url && p.image !== url ? { ...p, image: url } : p;
    }
  }
  return offerProductById(num);
}

export function ATYAB_catalog(key) {
  const k = key === "incense" ? "incense" : key === "ouds" ? "ouds" : "perfumes";
  const meta = metaFor(k);
  const items = liveList().filter(function (p) {
    if (k === "incense") return p.kind === "incense";
    if (k === "ouds") return p.kind === "oud";
    return p.kind === "perfume";
  });
  return {
    key: meta.key,
    route: meta.route,
    label: meta.label,
    labelEn: meta.labelEn,
    noun: meta.noun,
    nounEn: meta.nounEn,
    countNoun: meta.countNoun,
    nounForms: meta.nounForms,
    nounFormsEn: meta.nounFormsEn,
    collectionsLabel: meta.collectionsLabel,
    reviewsTitle: meta.reviewsTitle,
    reviewsChannel: meta.reviewsChannel,
    reviewsChannelLabel: meta.reviewsChannelLabel,
    notesTitle: meta.notesTitle,
    collectionFallback: meta.collectionFallback,
    collectionFallbackEn: meta.collectionFallbackEn,
    collections: meta.collections || [],
    items: items
  };
}

export function ATYAB_catalogOf(id) {
  const p = ATYAB_byId(id);
  if (p && p.kind === "oud") return ATYAB_catalog("ouds");
  if (p && p.kind === "incense") return ATYAB_catalog("incense");
  return ATYAB_catalog("perfumes");
}

/* العروض ستأتي من الخادم لاحقاً — لا عروض حالياً */
export const ATYAB_OFFERS = [];

export function ATYAB_offerById() {
  return null;
}

export const ATYAB_PLACEHOLDERS = {};

/* الصورة الإضافية n للمنتج: من معرض شريحة الصور (4 صور) */
export function ATYAB_extraImage(id, n) {
  const gallery = liveGallery(id);
  if (gallery && gallery[n - 1]) return gallery[n - 1];
  return null;
}

export { ATYAB_GENDERS };
