/* ============================================================
   أطياب الجاسم (React) — عميل الدخول بالتوكن (JWT)

   السيناريو (كما طُلب):
     · الزائر يتجوّل حرّاً: العربة/المفضلة/اللغة/العملة في Local Storage.
     · عند «إتمام الدفع» يُوجَّه للدخول/التسجيل، وبعد النجاح يعود
       إلى Checkout (returnTo) ليُكمل بيانات التوصيل بنفسه.
     · الدخول المباشر من «سجل الآن»/أسفل الصفحة: حرّية كاملة بعد
       إنشاء الحساب — لا نطلب أي بيانات شخصية إلا عند الدفع أو
       من أيقونة «حسابي».
     · التوكن: access قصير (~ساعة) + refresh طويل (14 يوماً).
       عند الإقلاع ندخل Guest فوراً ثم نُحدّث بصمت إلى Customer
       إن وُجد refresh صالح — وكل استدعاء مُوثَّق يُجدِّد تلقائياً
       قبل الانتهاء أو عند 401، دون أن يشعر العميل.

   ★ بلا خادم (API غير شغّال): الدوال تقذف ENETUNREACH فيستعمل
     المتصل الحسابات المحلية القديمة كاحتياط — فلا يتعطّل الموقع.
   ★ شكل الاستجابة (signup/login/refresh واحدة):
     { accessToken, tokenType, expiresIn, refreshToken,
       customerId, email, firstName }
   ============================================================ */

import { API_BASE_URL, ENDPOINTS, apiError, atyabLog } from "../redux/api.js";
import { KEYS, readJSON, writeJSON, removeRaw } from "../redux/persist.js";
import { isPlaceholderName } from "../validation.js";
import { userActions } from "../redux/slices/userSlice.js";

const POST_TIMEOUT_MS = 12000;
/* هامش التجديد المبكّر: نُجدِّد قبل انتهاء access بـ 60 ثانية */
const REFRESH_MARGIN_MS = 60000;
/* صلاحية الـ refresh كما حدّدها المالك: 14 يوماً */
export const REFRESH_TTL_MS = 14 * 24 * 3600 * 1000;
/* ★ #8: جيل المصادقة — يرتفع مع كل تبديل حساب/إنهاء/إقلاع.
   أي استجابة تحمل gen أقدم من الحالي تُتجاهل (لا تمسح جلسة جديدة). */
let authGen = 0;
export function nextAuthGen() {
  authGen += 1;
  return authGen;
}
export function currentAuthGen() {
  return authGen;
}
/* ★ #8: عداد فشل التجديد المتتالي — لمنع إعادة المحاولة غير المحدودة */
let refreshFailStreak = 0;
const REFRESH_MAX_STREAK = 3;
let refreshCoolUntil = 0;

function now() {
  return Date.now();
}

/* ---------- تخزين الجلسة ---------- */

export function saveSession(data) {
  const d = data || {};
  const at = now();
  const access = {
    token: String(d.accessToken || ""),
    type: String(d.tokenType || "Bearer"),
    expiresAt: at + Number(d.expiresIn || 3600) * 1000
  };
  const refresh = {
    token: String(d.refreshToken || ""),
    obtainedAt: at
  };
  const customer = {
    id: d.customerId == null ? null : d.customerId,
    email: String(d.email || "").trim().toLowerCase(),
    firstName: String(d.firstName || "")
  };
  if (access.token) writeJSON(KEYS.authAccess, access);
  if (refresh.token) writeJSON(KEYS.authRefresh, refresh);
  if (customer.email) writeJSON(KEYS.authCustomer, customer);
  return { access: access, refresh: refresh, customer: customer };
}

export function loadSession() {
  return {
    access: readJSON(KEYS.authAccess, null),
    refresh: readJSON(KEYS.authRefresh, null),
    customer: readJSON(KEYS.authCustomer, null)
  };
}

export function clearAuthStorage() {
  removeRaw(KEYS.authAccess);
  removeRaw(KEYS.authRefresh);
  removeRaw(KEYS.authCustomer);
}

export function accessValid(access) {
  const token = access && access.token;
  if (!token) return false;
  const exp = Number(access.expiresAt) || 0;
  return exp - REFRESH_MARGIN_MS > now();
}

export function refreshUsable(refresh) {
  const token = refresh && refresh.token;
  if (!token) return false;
  const at = Number(refresh.obtainedAt) || 0;
  return at + REFRESH_TTL_MS > now();
}

/* ---------- POST خام ---------- */

async function authPost(path, body, extraHeaders, opts) {
  /* ★ #9: يدعم signal المستدعي + مهلة داخلية + تمييز الإلغاء عن المهلة */
  const o = opts || {};
  const url = API_BASE_URL + path;
  if (!API_BASE_URL) throw apiError("تعذّر الوصول إلى الخادم — تحقق من تشغيل الـ API", 0, "ENETUNREACH");
  let controller = null;
  let timer = 0;
  let callerAborted = false;
  let onCallerAbort = null;
  const init = {
    method: "POST",
    headers: Object.assign({ Accept: "application/json", "Content-Type": "application/json", "ngrok-skip-browser-warning": "true" }, extraHeaders || {}),
    body: JSON.stringify(body || {})
  };
  if (typeof AbortController === "function") {
    controller = new AbortController();
    init.signal = controller.signal;
    timer = setTimeout(function () {
      controller.abort();
    }, POST_TIMEOUT_MS);
    if (o.signal) {
      if (o.signal.aborted) {
        if (timer) clearTimeout(timer);
        const e = apiError("أُلغي الطلب", 0, "EABORTED");
        throw e;
      }
      onCallerAbort = function () {
        callerAborted = true;
        try { controller.abort(); } catch (e) {}
      };
      try {
        if (typeof o.signal.addEventListener === "function") o.signal.addEventListener("abort", onCallerAbort, { once: true });
      } catch (e) {}
    }
  }
  let res;
  try {
    res = await fetch(url, init);
  } catch (e) {
    if (timer) clearTimeout(timer);
    try {
      if (o.signal && typeof o.signal.removeEventListener === "function" && onCallerAbort) o.signal.removeEventListener("abort", onCallerAbort);
    } catch (ee) {}
    if (callerAborted || (o.signal && o.signal.aborted)) {
      throw apiError("أُلغي الطلب", 0, "EABORTED");
    }
    if (e && e.name === "AbortError") {
      throw apiError("انتهت مهلة الاتصال بالخادم", 0, "ECONNABORTED");
    }
    throw apiError("تعذّر الوصول إلى الخادم — تحقق من تشغيل الـ API", 0, "ENETUNREACH");
  }
  /* ★ المؤقت يغطي قراءة body أيضاً (لا ينتهي عند headers): إلغاء المستدعي
     أثناء res.text() يُجهضها عبر signal نفسه. */
  let payload = null;
  try {
    const text = await res.text();
    payload = text ? JSON.parse(text) : null;
  } catch (e) {
    if (callerAborted || (o.signal && o.signal.aborted)) {
      if (timer) clearTimeout(timer);
      try {
        if (o.signal && typeof o.signal.removeEventListener === "function" && onCallerAbort) o.signal.removeEventListener("abort", onCallerAbort);
      } catch (ee) {}
      throw apiError("أُلغي الطلب", 0, "EABORTED");
    }
    if (e && e.name === "AbortError") {
      if (timer) clearTimeout(timer);
      try {
        if (o.signal && typeof o.signal.removeEventListener === "function" && onCallerAbort) o.signal.removeEventListener("abort", onCallerAbort);
      } catch (ee) {}
      throw apiError("انتهت مهلة الاتصال بالخادم", 0, "ECONNABORTED");
    }
    payload = null;
  }
  if (timer) clearTimeout(timer);
  try {
    if (o.signal && typeof o.signal.removeEventListener === "function" && onCallerAbort) o.signal.removeEventListener("abort", onCallerAbort);
  } catch (e) {}
  if (!res.ok) {
    /* ★ مغلّف الخطأ الموحّد (§0): detail العربية أولاً */
    const msg = (payload && (payload.detail || payload.message || payload.title || payload.error)) || ("استجابة الخادم: " + res.status);
    const err = apiError(msg, res.status);
    err.response = { status: res.status, data: payload };
    throw err;
  }
  return payload;
}

/* ---------- signup / login / refresh ---------- */

export function serverSignup(values) {
  const v = values || {};
  return authPost(ENDPOINTS.authSignup, {
    email: String(v.email || "").trim().toLowerCase(),
    password: String(v.password || ""),
    confirmPassword: String(v.confirm != null ? v.confirm : v.confirmPassword || "")
  });
}

export function serverLogin(values) {
  const v = values || {};
  return authPost(ENDPOINTS.authLogin, {
    email: String(v.email || "").trim().toLowerCase(),
    password: String(v.password || "")
  });
}

/* ---------- الدخول بجوجل ---------- */

/* ★ الـ Client ID علني (ليس سراً) — الافتراضي المضمّن لمتجرك،
   ويمكن تجاوزه عبر window.ATYAB_GOOGLE_CLIENT_ID أو localStorage. */
const DEFAULT_GOOGLE_CLIENT_ID = "836833308164-o6mb815hjpeg0pc735v5b3bfge13l56u.apps.googleusercontent.com";

export function readGoogleClientId() {
  try {
    if (typeof window !== "undefined" && window.ATYAB_GOOGLE_CLIENT_ID) {
      return String(window.ATYAB_GOOGLE_CLIENT_ID).trim();
    }
    const saved = window.localStorage.getItem("atyab:googleClientId");
    if (saved) return String(saved).trim();
  } catch (e) {
    /* بيئة بلا تخزين */
  }
  return DEFAULT_GOOGLE_CLIENT_ID;
}

/* يرسل idToken الخام للخادم — التحقق (aud/iss/exp/sub) هناك حصراً،
   ففكّ الترميز في المتصفح للعرض فقط ولا يُوثق به أبداً. */
export function serverGoogleLogin(idToken) {
  return authPost(ENDPOINTS.authGoogle, { idToken: String(idToken || "") });
}

function serverRefreshOnce(accessToken, refreshToken) {
  return authPost(
    ENDPOINTS.authRefresh,
    { refreshToken: String(refreshToken || "") },
    accessToken ? { Authorization: "Bearer " + accessToken } : {}
  );
}

/* ★ #8: تجديد واحد مشترك لكل المتصلين (فلا تتكرّر الطلبات).
   طلبان 401 متزامنان يشتركان في نفس الوعد — لا عمليتي refresh.
   + منع إعادة غير محدودة: streak متتالية + تهدئة.
   ★ F1/F2: الوعد مرتبط بالجلسة (gen + مالك + refreshToken البدئي).
   استجابة قديمة بعد تبديل الحساب تُتجاهل — لا كتابة ولا مسح.
   التنسيق بين التبويبين عبر حدث storage (يرفع gen) + فحص
   تغيّر refreshToken المخزّن قبل الكتابة — الوعد وحده ذاكرة تبويب واحد. */
let refreshPromise = null;
let refreshPromiseMeta = null;
/* ★ تنسيق التبويبين — أفضل جهد (best-effort) لا قفلاً موزعاً مثالياً:
   localStorage عمليات متزامنة لكن تبويبين قد يقرآن «فارغاً» معاً، فيبدأ
   تجديدان. شبكة الأمان الحقيقية: (1) حدث storage يرفع gen في التبويب
   الآخر فيُسقط رده القديم، (2) فحص تغيّر refreshToken المخزّن قبل الكتابة
   فيعتمد الأحدث، (3) الخادم يدير تدوير refresh فالمكرر يُرفض. هذا القفل
   يقلل التزامن ولا يدّعي منعه تماماً. */
const REFRESH_LOCK_KEY = "atyab:refresh-lock";
const REFRESH_LOCK_MS = 8000;
function readRefreshLock() {
  try {
    const raw = window.localStorage.getItem(REFRESH_LOCK_KEY);
    if (!raw) return null;
    const o = JSON.parse(raw);
    if (!o || !o.tok || !o.at) return null;
    return o;
  } catch (e) { return null; }
}
function writeRefreshLock(tok) {
  try {
    window.localStorage.setItem(REFRESH_LOCK_KEY, JSON.stringify({ tok: tok, at: Date.now() }));
  } catch (e) {}
}
function clearRefreshLock(tok) {
  try {
    const cur = readRefreshLock();
    if (cur && cur.tok === tok) window.localStorage.removeItem(REFRESH_LOCK_KEY);
  } catch (e) {}
}
function randomLockToken() {
  try {
    const b = new Uint32Array(2);
    if (window.crypto && window.crypto.getRandomValues) {
      window.crypto.getRandomValues(b);
      return "l" + b[0].toString(36) + b[1].toString(36);
    }
  } catch (e) {}
  return "l" + Math.floor(Math.random() * 1e9).toString(36);
}

function ownerKeyOf(sess) {
  const s = sess || {};
  const c = s.customer || {};
  const id = c.id == null ? 0 : Number(c.id) || 0;
  const email = String(c.email || "").trim().toLowerCase();
  if (id || email) return "c:" + id + "|" + email;
  return "guest";
}
export function currentOwnerKey() {
  try { return ownerKeyOf(loadSession()); } catch (e) { return "guest"; }
}
function storedRefreshToken() {
  try {
    const s = loadSession();
    return String((s.refresh && s.refresh.token) || "");
  } catch (e) { return ""; }
}

/* ★ F1: تجديد إجباري بعد 401 عبر force:true — يتجاوز صلاحية access
   المحلية. بدون force يعيد التوكن الصالح محلياً (المسار الصامت).
   ★ F2: يلتقط gen والمالك وrefreshToken قبل الطلب، ويتحقق منهما قبل
   أي كتابة/مسح. الوعد المشترك يُعاد استعماله فقط لجلسة مطابقة. */
export function ensureFreshToken(opts) {
  const force = !!(opts && (opts.force === true || opts === true));
  const s = loadSession();
  if (!force && accessValid(s.access)) return Promise.resolve(s.access.token);
  if (!refreshUsable(s.refresh)) return Promise.resolve("");
  if (Date.now() < refreshCoolUntil) return Promise.resolve("");
  if (refreshFailStreak >= REFRESH_MAX_STREAK && Date.now() < refreshCoolUntil) return Promise.resolve("");
  const curGen = currentAuthGen();
  const curOwner = ownerKeyOf(s);
  if (refreshPromise && refreshPromiseMeta && refreshPromiseMeta.gen === curGen && refreshPromiseMeta.ownerKey === curOwner) {
    return refreshPromise;
  }
  const startGen = curGen;
  const startOwner = curOwner;
  const startRefreshToken = String((s.refresh && s.refresh.token) || "");
  const startAccessToken = String((s.access && s.access.token) || "");
  /* ★ قفل تبويبين (أفضل جهد): قفل أجنبي حديث؟ انتظر تدويره القريب بدل
     تجديد موازٍ — up to 2.5s ثم تابع بقرارك. */
  try {
    const lock = readRefreshLock();
    if (lock && lock.at + REFRESH_LOCK_MS > Date.now()) {
      const beforeTok = String((loadSession().access && loadSession().access.token) || "");
      const t0 = Date.now();
      /* انتظار قصير متزامن عبر promises — يُحترم budget المستدعي لاحقاً */
      const waitForeign = (async function () {
        while (Date.now() - t0 < 2500) {
          await new Promise(function (r) { setTimeout(r, 120); });
          try {
            const cur = loadSession();
            const tok = String((cur.access && cur.access.token) || "");
            if (tok && tok !== beforeTok && accessValid(cur.access)) return tok;
            const lk = readRefreshLock();
            if (!lk || lk.at + REFRESH_LOCK_MS <= Date.now()) break;
          } catch (e) { break; }
        }
        return "";
      })();
      return waitForeign.then(function (tok) {
        if (tok) return tok;
        return startOwnedRefresh();
      });
    }
  } catch (e) {}
  return startOwnedRefresh();

  function startOwnedRefresh() {
  const myLock = randomLockToken();
  writeRefreshLock(myLock);
  const p = serverRefreshOnce(s.access && s.access.token, s.refresh.token).then(
    function (data) {
        if (refreshPromise === p) { refreshPromise = null; refreshPromiseMeta = null; }
        try { clearRefreshLock(myLock); } catch (e) {}
        /* ★ F2: تبدلت الجلسة أثناء الانتظار؟ تجاهل الرد القديم تماماً —
           لا كتابة تخزين ولا Redux هنا (المتصل يفحص الجيل ويلغي retry). */
        if (Number(currentAuthGen()) !== Number(startGen)) {
          atyabLog("auth REFRESH stale-gen discarded");
          return "";
        }
        if (currentOwnerKey() !== startOwner) {
          atyabLog("auth REFRESH stale-owner discarded");
          return "";
        }
        /* ★ تنسيق تبويبين: تبويب آخر جدّد/بدّل أثناء انتظارنا (تغيّر
           refreshToken المخزّن)؟ اعتمد المخزّن الأحدث ولا تكتب فوقه. */
        const curStoredRefresh = storedRefreshToken();
        if (curStoredRefresh && startRefreshToken && curStoredRefresh !== startRefreshToken) {
          atyabLog("auth REFRESH cross-tab superseded — keep stored");
          try {
            const cur = loadSession();
            if (cur.access && cur.access.token && accessValid(cur.access)) return cur.access.token;
          } catch (e) {}
          return "";
        }
        refreshFailStreak = 0;
        const saved = saveSession(data || {});
        atyabLog("auth REFRESH ok");
        /* ★ F1: إن جدّد مسار آخر التوكن أثناء انتظارنا فالمخزّن أحدث —
           أعد الأحدث (لا الأقدم). */
        try {
          const curTok = String((loadSession().access && loadSession().access.token) || "");
          if (curTok && curTok !== startAccessToken) return curTok;
        } catch (e) {}
        return saved.access.token;
      },
    function (err) {
        if (refreshPromise === p) { refreshPromise = null; refreshPromiseMeta = null; }
        try { clearRefreshLock(myLock); } catch (e) {}
        /* ★ F2: رفض قديم بعد تبديل الحساب؟ لا تمسح جلسة B بسبب A. */
        const genChanged = Number(currentAuthGen()) !== Number(startGen);
        const ownerChanged = currentOwnerKey() !== startOwner;
        const refreshRotated = (function () {
          const cur = storedRefreshToken();
          return !!(cur && startRefreshToken && cur !== startRefreshToken);
        })();
        refreshFailStreak += 1;
        if (refreshFailStreak >= REFRESH_MAX_STREAK) {
          refreshCoolUntil = Date.now() + 5 * 60 * 1000;
          atyabLog("auth REFRESH cooldown 5m after streak");
        }
        /* refresh مرفوض (400/401) → عودة نظيفة لوضع Guest — فقط إن كانت
           الجلسة ما زالت جلسة الطلب نفسها. عطل الشبكة (status 0) لا يمسح
           شيئاً أبداً (F2: لا خلط بين شبكة ورفض مؤكد). */
        if (err && (err.status === 400 || err.status === 401)) {
          if (!genChanged && !ownerChanged && !refreshRotated) {
            clearAuthStorage();
            atyabLog("auth REFRESH rejected — back to guest");
          } else {
            atyabLog("auth REFRESH rejected stale — keep current session");
          }
        } else {
          atyabLog("auth REFRESH unreachable — will retry later");
        }
        return "";
      }
    );
  refreshPromise = p;
  refreshPromiseMeta = { gen: startGen, ownerKey: startOwner, refreshToken: startRefreshToken };
  return p;
  } /* end startOwnedRefresh */
}

/* ★ F1+F7: نداء مُوثَّق بميزانية زمنية شاملة — يغطي انتظار refresh
   والمحاولتين وقراءة الترويسات، مع إلغاء المستدعي في كل المراحل.
   · 401 → تجديد إجباري واحد (force) عبر الوعد المشترك للجلسة نفسها.
     إن كان المخزّن تدوّر أثناء الانتظار استُعمل الأحدث بلا refresh زائد.
   · إعادة واحدة فقط بعد 401، ثم يُرجَع الرفض كما هو (لا حلقة).
   · تغيّرت الجلسة (gen/مالك) أثناء الانتظار؟ لا retry بحساب مختلف —
     يُرمى ESESSIONCHANGED ويلغي المستدعي انتظاره بأمان.
   · انتظار refresh المشترك قابل للإلغاء من طرف المستدعي دون إلغاء
     الـrefresh نفسه (مستدعون آخرون قد يحتاجونه).
   · لا إعادة POST تلقائياً بعد timeout/NW — النتيجة مجهولة؛ المستدعي
     يستأنف بهوية العملية/رقم الطلب (Idempotency-Key) لا بإعادة إنشاء.
   ★ انتهاء انتظار المتصفح لا يثبت أن الخادم لم ينفذ. */
const AUTHFETCH_DEFAULT_TIMEOUT_MS = 15000;
function sessionChangedError() {
  const e = apiError("تبدلت الجلسة أثناء الطلب — أُبطلت المحاولة القديمة", 0, "ESESSIONCHANGED");
  return e;
}
/* انتظار وعد مشترك مع إلغاء المستدعي ومهلة متبقية — دون إلغاء الأصل */
function waitShared(promise, signal, msLeft) {
  return new Promise(function (resolve, reject) {
    let done = false;
    let timer = 0;
    function cleanup() {
      if (timer) { try { clearTimeout(timer); } catch (e) {} timer = 0; }
      try {
        if (signal && typeof signal.removeEventListener === "function" && onAbort) signal.removeEventListener("abort", onAbort);
      } catch (e) {}
    }
    function onAbort() {
      if (done) return;
      done = true;
      cleanup();
      reject(apiError("أُلغي الطلب", 0, "EABORTED"));
    }
    if (signal && signal.aborted) {
      reject(apiError("أُلغي الطلب", 0, "EABORTED"));
      return;
    }
    if (msLeft != null && !(msLeft > 0)) {
      reject(apiError("انتهت مهلة الاتصال بالخادم", 0, "ECONNABORTED"));
      return;
    }
    if (msLeft != null && msLeft > 0) {
      timer = setTimeout(function () {
        if (done) return;
        done = true;
        cleanup();
        reject(apiError("انتهت مهلة الاتصال بالخادم", 0, "ECONNABORTED"));
      }, msLeft);
    }
    try {
      if (signal && typeof signal.addEventListener === "function") signal.addEventListener("abort", onAbort, { once: true });
    } catch (e) {}
    Promise.resolve(promise).then(function (v) {
      if (done) return;
      done = true;
      cleanup();
      resolve(v);
    }, function (e) {
      if (done) return;
      done = true;
      cleanup();
      resolve("");
    });
  });
}
function doFetch(url, init, signal, msLeft) {
  return new Promise(function (resolve, reject) {
    let controller = null;
    let timer = 0;
    let callerAborted = false;
    function onCallerAbort() {
      callerAborted = true;
      try { if (controller) controller.abort(); } catch (e) {}
    }
    if (signal && signal.aborted) {
      reject(apiError("أُلغي الطلب", 0, "EABORTED"));
      return;
    }
    if (msLeft != null && !(msLeft > 0)) {
      reject(apiError("انتهت مهلة الاتصال بالخادم", 0, "ECONNABORTED"));
      return;
    }
    try {
      if (typeof AbortController === "function") {
        controller = new AbortController();
        init.signal = controller.signal;
        if (msLeft != null && msLeft > 0) {
          timer = setTimeout(function () {
            try { controller.abort(); } catch (e) {}
          }, msLeft);
        }
        if (signal) {
          try {
            if (typeof signal.addEventListener === "function") signal.addEventListener("abort", onCallerAbort, { once: true });
          } catch (e) {}
        }
      }
    } catch (e) {}
    function cleanup() {
      if (timer) { try { clearTimeout(timer); } catch (e) {} timer = 0; }
      try {
        if (signal && typeof signal.removeEventListener === "function") signal.removeEventListener("abort", onCallerAbort);
      } catch (e) {}
    }
    let timedOut = false;
    if (controller && controller.signal) {
      try {
        controller.signal.addEventListener("abort", function () {
          if (!callerAborted) timedOut = true;
        }, { once: true });
      } catch (e) {}
    }
    fetch(url, init).then(function (res) {
      cleanup();
      resolve(res);
    }, function (e) {
      cleanup();
      if (callerAborted || (signal && signal.aborted)) reject(apiError("أُلغي الطلب", 0, "EABORTED"));
      else if ((e && e.name === "AbortError") || timedOut) reject(apiError("انتهت مهلة الاتصال بالخادم", 0, "ECONNABORTED"));
      else reject(apiError("تعذّر الوصول إلى الخادم — تحقق من تشغيل الـ API", 0, "ENETUNREACH"));
    });
  });
}
export async function authFetch(path, options) {
  const o = options || {};
  if (o.signal && o.signal.aborted) {
    throw apiError("أُلغي الطلب", 0, "EABORTED");
  }
  const reqGen = currentAuthGen();
  function assertSameSession() {
    /* ★ F2: التبديل الخارجي يُكتشف عبر الجيل (كل دخول/إنهاء يرفعه).
       مسح جلستنا نفسها بعد رفض refresh مؤكد (gen ثابت → ضيف) ليس تبديلاً
       خارجياً — يُرجَع 401 الأصلي بدل رمي ESESSIONCHANGED. */
    if (Number(currentAuthGen()) !== Number(reqGen)) throw sessionChangedError();
  }
  const budgetMs = Number(o.timeoutMs) > 0 ? Number(o.timeoutMs) : AUTHFETCH_DEFAULT_TIMEOUT_MS;
  const deadline = Date.now() + budgetMs;
  function msLeft() { return Math.max(0, deadline - Date.now()); }
  const url = API_BASE_URL + path;
  if (!API_BASE_URL) throw apiError("تعذّر الوصول إلى الخادم — تحقق من تشغيل الـ API", 0, "ENETUNREACH");
  function buildInit(token) {
    const init = {
      method: o.method || "GET",
      headers: { Accept: "application/json", "Content-Type": "application/json", "ngrok-skip-browser-warning": "true" }
    };
    if (token) init.headers.Authorization = "Bearer " + token;
    if (o.body != null) init.body = JSON.stringify(o.body);
    if (o.headers) {
      Object.keys(o.headers).forEach(function (k) { init.headers[k] = o.headers[k]; });
    }
    return init;
  }
  /* المحاولة الأولى: توكن صالح محلياً أو تجديد صامت (غير إجباري) */
  let token = "";
  try {
    token = await waitShared(ensureFreshToken().catch(function () { return ""; }), o.signal || null, msLeft());
  } catch (e) {
    throw e;
  }
  assertSameSession();
  let res;
  try {
    res = await doFetch(url, buildInit(token), o.signal || null, msLeft());
  } catch (e) {
    /* ★ لا إعادة بعد timeout/شبكة/إلغاء — النتيجة مجهولة (F7) */
    throw e;
  }
  assertSameSession();
  if (res.status !== 401) return res;
  /* ★ 401 واحدة فقط: تجديد إجباري مشترك للجلسة نفسها (F1) */
  const before = token || "";
  let fresh = "";
  try {
    const curStored = (function () {
      try { return String((loadSession().access && loadSession().access.token) || ""); } catch (e) { return ""; }
    })();
    let curValid = false;
    try { curValid = accessValid(loadSession().access); } catch (e) {}
    if (curStored && curStored !== before && curValid) {
      /* ★ جُدد التوكن أثناء انتظارنا (تبويب/نبض) — استعمل الأحدث بلا refresh */
      fresh = curStored;
    } else {
      fresh = await waitShared(ensureFreshToken({ force: true }).catch(function () { return ""; }), o.signal || null, msLeft());
    }
  } catch (e) {
    throw e;
  }
  /* فحص الإلغاء والجيل قبل بدء طلب بعد اكتمال refresh (F7) */
  if (o.signal && o.signal.aborted) throw apiError("أُلغي الطلب", 0, "EABORTED");
  assertSameSession();
  if (!fresh || fresh === before) {
    /* تجديد لم يأتِ بجديد (مرفوض/شبكة) — أعد الـ401 الأصلية بلا حلقة */
    try {
      const cur2 = String((loadSession().access && loadSession().access.token) || "");
      let cur2Valid = false;
      try { cur2Valid = accessValid(loadSession().access); } catch (e) {}
      if (cur2 && cur2 !== before && cur2Valid) fresh = cur2;
      else return res;
    } catch (e) { return res; }
    if (!fresh || fresh === before) return res;
    assertSameSession();
  }
  /* ★ المحاولة الثانية تحمل signal والميزانية المتبقية (F7) — لا ثالثة */
  try {
    res = await doFetch(url, buildInit(fresh), o.signal || null, msLeft());
  } catch (e) {
    throw e;
  }
  /* ★ حراسة نهائية بعد المحاولة الثانية: تبديل أثناء retry لا يُطبَّق —
     المتصل يفحص الجيل قبل استعمال الرد (body يُقرأ عبر readJsonBody). */
  assertSameSession();
  return res;
}

/* ★ قراءة body بميزانية وإلغاء — headers السريعة + body المعلّق يُغطّى.
   تُستعمل بعد authFetch حيث انتهت مهلة doFetch عند headers. */
export function readJsonBody(res, signal, msLeft) {
  const data = { text: null };
  return new Promise(function (resolve, reject) {
    let done = false;
    let timer = 0;
    function onAbort() {
      if (done) return;
      done = true;
      cleanup();
      reject(apiError("أُلغي الطلب", 0, "EABORTED"));
    }
    function cleanup() {
      if (timer) { try { clearTimeout(timer); } catch (e) {} timer = 0; }
      try {
        if (signal && typeof signal.removeEventListener === "function") signal.removeEventListener("abort", onAbort);
      } catch (e) {}
    }
    if (signal && signal.aborted) {
      reject(apiError("أُلغي الطلب", 0, "EABORTED"));
      return;
    }
    if (msLeft != null && !(msLeft > 0)) {
      reject(apiError("انتهت مهلة الاتصال بالخادم", 0, "ECONNABORTED"));
      return;
    }
    if (msLeft != null && msLeft > 0) {
      timer = setTimeout(function () {
        if (done) return;
        done = true;
        cleanup();
        reject(apiError("انتهت مهلة الاتصال بالخادم", 0, "ECONNABORTED"));
      }, msLeft);
    }
    try {
      if (signal && typeof signal.addEventListener === "function") signal.addEventListener("abort", onAbort, { once: true });
    } catch (e) {}
    Promise.resolve().then(function () { return res.text(); }).then(function (t) {
      if (done) return;
      done = true;
      cleanup();
      data.text = t;
      resolve(t);
    }, function () {
      if (done) return;
      done = true;
      cleanup();
      resolve("");
    });
  }).then(function (t) {
    if (!t) return null;
    try { return JSON.parse(t); } catch (e) { return null; }
  });
}
/* ★ مسار كامل: fetch + حراسة نهائية + body — لقطات السلة الحرجة تستعمله
   بدل authFetch+readJsonSafe المنفصلين (تغطية body + رفض تطبيق قديم). */
export async function authFetchJson(path, options) {
  const o = options || {};
  const budgetMs = Number(o.timeoutMs) > 0 ? Number(o.timeoutMs) : AUTHFETCH_DEFAULT_TIMEOUT_MS;
  const deadline = Date.now() + budgetMs;
  function msLeft() { return Math.max(0, deadline - Date.now()); }
  const reqGen = currentAuthGen();
  const res = await authFetch(path, { method: o.method || "GET", body: o.body, headers: o.headers, signal: o.signal || null, timeoutMs: Math.max(1, msLeft() - 1) });
  if (Number(currentAuthGen()) !== Number(reqGen)) throw sessionChangedError();
  const data = o.strictJson
    ? await readJsonBodyStrict(res, o.signal || null, msLeft())
    : await readJsonBody(res, o.signal || null, msLeft());
  if (Number(currentAuthGen()) !== Number(reqGen)) throw sessionChangedError();
  return { res: res, data: data };
}

/* ★ v14-F2: قراءة صارمة للمسارات التي تتوقع JSON (لقطات السلة الحرجة).
   أي فشل في قراءة body أو تحليل JSON خطأ صريح — لا null صامت:
   · تعذر قراءة body → EREADBODY
   · body فارغ → EEMPTYBODY (لقطة السلة يجب أن تكون JSON دائماً)
   · JSON غير صالح (HTML/مقطوع/...) → EINVALIDJSON
   المهلة/الإلغاء كما في النسخة اللينة (ECONNABORTED/EABORTED). */
export function readJsonBodyStrict(res, signal, msLeft) {
  return new Promise(function (resolve, reject) {
    let done = false;
    let timer = 0;
    function onAbort() {
      if (done) return;
      done = true;
      cleanup();
      reject(apiError("أُلغي الطلب", 0, "EABORTED"));
    }
    function cleanup() {
      if (timer) { try { clearTimeout(timer); } catch (e) {} timer = 0; }
      try {
        if (signal && typeof signal.removeEventListener === "function") signal.removeEventListener("abort", onAbort);
      } catch (e) {}
    }
    if (signal && signal.aborted) {
      reject(apiError("أُلغي الطلب", 0, "EABORTED"));
      return;
    }
    if (msLeft != null && !(msLeft > 0)) {
      reject(apiError("انتهت مهلة الاتصال بالخادم", 0, "ECONNABORTED"));
      return;
    }
    if (msLeft != null && msLeft > 0) {
      timer = setTimeout(function () {
        if (done) return;
        done = true;
        cleanup();
        reject(apiError("انتهت مهلة الاتصال بالخادم", 0, "ECONNABORTED"));
      }, msLeft);
    }
    try {
      if (signal && typeof signal.addEventListener === "function") signal.addEventListener("abort", onAbort, { once: true });
    } catch (e) {}
    Promise.resolve().then(function () { return res.text(); }).then(function (t) {
      if (done) return;
      done = true;
      cleanup();
      if (t == null || String(t).trim() === "") {
        reject(apiError("رد فارغ من الخادم — تعذرت قراءة السلة", 0, "EEMPTYBODY"));
        return;
      }
      try {
        resolve(JSON.parse(t));
      } catch (e) {
        reject(apiError("رد غير صالح من الخادم — تعذر تحليل السلة", 0, "EINVALIDJSON"));
      }
    }, function () {
      if (done) return;
      done = true;
      cleanup();
      reject(apiError("تعذرت قراءة رد الخادم", 0, "EREADBODY"));
    });
  });
}

/* ---------- ربط الجلسة بالمتجر ---------- */

/* ★ #8: إجراء مركزي وحيد لإنهاء الجلسة — يمسح التخزين + Redux مع gen جديد.
   للحسابات اليتيمة (404 سلة) أو refresh مرفوض أو تبديل حساب. */
export function terminateSession(dispatch, reason) {
  const gen = nextAuthGen();
  try { clearAuthStorage(); } catch (e) {}
  try {
    if (dispatch) {
      dispatch(userActions.sessionDropped({ gen: gen }));
      dispatch(userActions.setSession(null));
    }
  } catch (e) {}
  try { atyabLog("auth TERMINATED " + String(reason || "")); } catch (e) {}
  return gen;
}
/* ★ خروج كامل: مسح التوكن + حالة المستخدم — للحسابات اليتيمة
   (404 على السلة = الحساب غير موجود عند الخادم بعد تصفير القاعدة). */
export function signOutEverywhere(dispatch) {
  terminateSession(dispatch, "signout");
  try {
    if (dispatch) dispatch(userActions.logout());
  } catch (e) {}
}

/* ★ #8: gen عند بدء المحاولة لا عند حلها — استجابة قديمة بعد تبديل الحساب تُتجاهل */
export function beginAuthAttempt() {
  return nextAuthGen();
}
/* ★ F2: التقط الجيل والمالك قبل الطلب، وتحقق منهما قبل أي كتابة إلى
   storage أو Redux أو profile — وأيضاً قبل مسح الجلسة عند فشل قديم.
   saveSession كانت تُنفذ قبل حراسة reducer فاستبدل refresh-A جلسة B.
   ★ v15-F5: القبول والمسح انتقال محروس واحد — المسح عند تبديل الهوية يعيش
   داخل sessionEstablished (يُرفض مع الرد القديم ذرياً)؛ المتصل يفحص
   القيمة الراجعة (null = مرفوض) ويوقف كل آثار النجاح. */
export function applyServerSession(dispatch, data, profile, preGen) {
  const gen = preGen != null ? Number(preGen) : nextAuthGen();
  /* استجابة أقدم من الجيل الحالي؟ تجاهل كامل — لا تخزين ولا Redux */
  if (Number(gen) < Number(currentAuthGen())) {
    try { atyabLog("auth STALE-RESPONSE discarded gen=" + gen); } catch (e) {}
    return null;
  }
  /* ★ مالك جديد بجيل أحدث/مساوٍ (دخول B بعد A) يُسمح له بالكتابة —
     الجيل وحده يحدد الأقدمية (F2). */
  const saved = saveSession(data || {});
  const email = (saved.customer && saved.customer.email) || "";
  const patch = { email: email };
  const srvName = saved.customer ? String(saved.customer.firstName || "") : "";
  if (srvName && !isPlaceholderName(srvName) && !(profile && profile.firstName)) {
    patch.firstName = saved.customer.firstName;
  }
  dispatch(
    userActions.sessionEstablished({
      customerId: saved.customer ? saved.customer.id : null,
      email: email,
      firstName: saved.customer ? saved.customer.firstName : "",
      expiresAt: saved.access ? saved.access.expiresAt : 0,
      gen: gen
    })
  );
  if (email) {
    dispatch(userActions.setSession(email));
    dispatch(userActions.setProfile(patch));
  }
  return saved;
}

/* ★ #1+#8: إقلاع صامت بدورة resolved كاملة — كل مسار يحسم resolved.
   guest/zائر/فشل كلها تنتهي بـ authCheckFinished أو sessionEstablished/Dropped مع gen.
   انتهاء refresh يصفّر Redux (sessionDropped) ولا يترك أثراً معلقاً. */
export function bootAuth(dispatch) {
  const gen = nextAuthGen();
  try { dispatch(userActions.authCheckStarted()); } catch (e) {}
  const s = loadSession();
  if (!s.refresh || !s.refresh.token) {
    atyabLog("auth BOOT guest (no refresh stored)");
    try { dispatch(userActions.authCheckFinished({ gen: gen })); } catch (e) {}
    return Promise.resolve("guest");
  }
  if (!refreshUsable(s.refresh)) {
    atyabLog("auth BOOT guest (refresh expired)");
    clearAuthStorage();
    /* ★ انتهاء refresh يصفّر Redux صراحة (#8) */
    try { dispatch(userActions.sessionDropped({ gen: gen })); } catch (e) {}
    try { dispatch(userActions.authCheckFinished({ gen: gen })); } catch (e) {}
    return Promise.resolve("guest");
  }
  if (accessValid(s.access)) {
    atyabLog("auth BOOT customer (access still fresh — no refresh needed)");
    if (s.customer && s.customer.email) {
      dispatch(
        userActions.sessionEstablished({
          customerId: s.customer.id,
          email: s.customer.email,
          firstName: s.customer.firstName || "",
          expiresAt: s.access.expiresAt,
          gen: gen
        })
      );
      dispatch(userActions.setSession(s.customer.email));
      return Promise.resolve("customer");
    }
  }
  return ensureFreshToken().then(function (token) {
    if (!token) {
      atyabLog("auth BOOT guest (refresh attempt failed)");
      /* ★ فشل التجديد: صفّر أي أثر قديم ولا تترك resolved معلقاً */
      const cur = loadSession();
      if (!cur.refresh || !cur.refresh.token || !refreshUsable(cur.refresh)) {
        try { clearAuthStorage(); } catch (e) {}
        try { dispatch(userActions.sessionDropped({ gen: gen })); } catch (e) {}
      }
      try { dispatch(userActions.authCheckFinished({ gen: gen })); } catch (e) {}
      return "guest";
    }
    atyabLog("auth BOOT customer (silently refreshed)");
    const fresh = loadSession();
    if (fresh.customer && fresh.customer.email) {
      dispatch(
        userActions.sessionEstablished({
          customerId: fresh.customer.id,
          email: fresh.customer.email,
          firstName: fresh.customer.firstName || "",
          expiresAt: fresh.access ? fresh.access.expiresAt : 0,
          gen: gen
        })
      );
      dispatch(userActions.setSession(fresh.customer.email));
      return "customer";
    }
    try { dispatch(userActions.authCheckFinished({ gen: gen })); } catch (e) {}
    return "guest";
  });
}

/* نبض دوري: الصفحة المفتوحة ساعات تُجدِّد بصمت (كل دقيقة + عند عودة
   التركيز للتبويب) — بلا تنبيهات، مع سطر log عند التدوير فقط. */
let heartbeatToken = "";
let heartbeatBusy = false;

export function authHeartbeat(dispatch) {
  if (heartbeatBusy) return Promise.resolve("");
  const s = loadSession();
  if (!refreshUsable(s.refresh)) return Promise.resolve("");
  heartbeatBusy = true;
  return ensureFreshToken().then(function (token) {
    heartbeatBusy = false;
    if (token && heartbeatToken && token !== heartbeatToken) {
      atyabLog("auth HEARTBEAT rotated");
    }
    if (token) heartbeatToken = token;
    const fresh = loadSession();
    if (token && fresh.customer && fresh.customer.email) {
      /* ★ #8: النبض لا يمحو جلسة أحدث — gen الحالي فقط */
      const gen = currentAuthGen();
      dispatch(
        userActions.sessionEstablished({
          customerId: fresh.customer.id,
          email: fresh.customer.email,
          firstName: fresh.customer.firstName || "",
          expiresAt: fresh.access ? fresh.access.expiresAt : 0,
          gen: gen
        })
      );
      dispatch(userActions.setSession(fresh.customer.email));
    }
    return token;
  });
}

/* ★ #8: تنسيق التبويبات — اشتراك الرموز عبر حدث storage.
   تبويب يبدّل/ينهي الحساب يُحدِث البقية فوراً (لا جلسة قديمة معلقة).
   + إلغاء استجابات الحساب السابق: كل حدث يرفع gen في المستقبِل. */
let authSyncInit = false;
export function initAuthSync(dispatch) {
  if (authSyncInit) return;
  authSyncInit = true;
  try {
    window.addEventListener("storage", function (ev) {
      const k = String((ev && ev.key) || "");
      if (k !== KEYS.authCustomer && k !== KEYS.authAccess && k !== KEYS.authRefresh && k !== KEYS.session) return;
      const gen = nextAuthGen();
      try {
        const s = loadSession();
        if (s.customer && s.customer.email && s.refresh && s.refresh.token && refreshUsable(s.refresh)) {
          dispatch(
            userActions.sessionEstablished({
              customerId: s.customer.id,
              email: s.customer.email,
              firstName: s.customer.firstName || "",
              expiresAt: s.access ? s.access.expiresAt : 0,
              gen: gen
            })
          );
          dispatch(userActions.setSession(s.customer.email));
        } else {
          dispatch(userActions.sessionDropped({ gen: gen }));
          if (!s.customer || !s.customer.email) dispatch(userActions.setSession(null));
        }
        atyabLog("auth SYNC cross-tab gen=" + gen);
      } catch (e) {}
    });
  } catch (e) {}
}
