/* مهلة كل نداء: ngrok المجاني ينام أحياناً — بعدها شاشة خطأ مع إعادة */
const STEP_TIMEOUT_MS = 35000;

/* أسباب الكوبون المعروفة — وحدها تُسقط الكوبون؛ أي سبب آخر = مخزون/تحقق */
const COUPON_REASONS = ["NOT_FOUND", "INACTIVE", "EXPIRED", "NOT_STARTED", "MIN_SUBTOTAL", "MIN_ITEMS", "USAGE_LIMIT", "USAGE_PER_CUSTOMER", "EMPTY_BASKET", "COUPON"];

/* ★ تصنيف بدء الدفع الموجود/المجهول — الأكواد أولاً ثم النص احتياطاً.
   in-progress: عملية قائمة → تابعها. unknown: نتيجة مجهولة → استعلم ثم تابع.
   لا تُنشئ طلباً/مفتاحاً جديداً في أي منهما. */
export function classifyStartFollow(payload) {
  const d = payload || {};
  const code = String(d.reason || d.code || "").toUpperCase();
  const text = [d.detail, d.message, d.title, d.error].filter(Boolean).map(function (v) { return String(v); }).join(" | ");
  if (/START_IN_PROGRESS|IN_PROGRESS|ALREADY_STARTED|قيد التنفيذ|عملية.*جارية|بدء.*جارٍ/i.test(code + " " + text)) return "in-progress";
  if (/START_UNKNOWN|UNKNOWN_RESULT|UNKNOWN|نتيجة.*مجهول|غير مؤكد|مجهولة/i.test(code + " " + text)) return "unknown";
  if (/IDEMPOTENCY_IN_PROGRESS/i.test(code)) return "in-progress";
  return "";
}

function withTimeout(promise, ms) {
  return new Promise(function (resolve, reject) {
    const timer = setTimeout(function () {
      reject(new Error("timeout"));
    }, ms);
    promise.then(
      function (v) {
        clearTimeout(timer);
        resolve(v);
      },
      function (e) {
        clearTimeout(timer);
        reject(e);
      }
    );
  });
}

/* رسالة الخادم الكاملة: detail العربية أولاً (ProblemDetails)، ثم
   message/error، والـtitle العام (conflict/not_found/...) يُتجاهل —
   كان يعرض "conflict" ويخفي "الكمية المطلوبة غير متوفرة". */
const GENERIC_TITLES = ["conflict", "not_found", "not found", "bad_request", "bad request", "error", "internal_error", "internal error", "unauthorized"];

function fullServerMessage(payload, fallback) {
  const d = payload || {};
  const detail = d.detail != null ? String(d.detail).trim() : "";
  const main = (d.message != null && String(d.message).trim()) || (d.error != null && String(d.error).trim()) || "";
  let title = d.title != null ? String(d.title).trim() : "";
  const tl = title.toLowerCase().replace(/_/g, " ");
  if (!title || GENERIC_TITLES.indexOf(title.toLowerCase()) !== -1 || GENERIC_TITLES.indexOf(tl) !== -1) title = "";
  const parts = [];
  if (detail) parts.push(detail);
  if (main && main !== detail) parts.push(main);
  if (title && title !== detail && title !== main) parts.push(title);
  if (d.reason) parts.push("السبب: " + String(d.reason));
  if (d.errors && typeof d.errors === "object") {
    Object.keys(d.errors).forEach(function (k) {
      const v = d.errors[k];
      parts.push(k + ": " + (Array.isArray(v) ? v.join(" ") : String(v)));
    });
  }
  return parts.length ? parts.join(" | ") : String(fallback || "");
}

export default function PaymentRedirectPage() {
  usePageMeta({ route: "paymentStart", titleAr: "التوجيه للدفع الآمن", titleEn: "Redirecting to secure payment" });

  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const location = useLocation();
  const totals = useAppSelector(selectCartTotals);
  const support = useAppSelector(selectSupport);
  const language = useAppSelector(function (s) {
    return (s.ui && s.ui.language) || "ar";
  });

  const [phase, setPhase] = useState("working"); /* working | failed | empty | follow */
  const [follow, setFollow] = useState(null); /* { orderId, code } — عملية قائمة/مجهولة تُتابَع */
  const [error, setError] = useState("");
  const [adjustNote, setAdjustNote] = useState("");
  const [stockFail, setStockFail] = useState(false);
  /* ★ FE24-F4: مخرج رفض الإحالة القطعي — referralExit: { kind, message,
     orderId }؛ noRefArmed: تأكيد صريح بخطوتين للمتابعة بلا إحالة
     (عملية جديدة بمفتاح جديد وreferral:null مع إعادة تحقق الموافقة). */
  const [referralExit, setReferralExit] = useState(null);
  const [noRefArmed, setNoRefArmed] = useState(false);
  /* ★ FE25-R32-02: منع النقر المزدوج على تأكيد بلا-إحالة (الهوية الجديدة
     تُصنع لحظياً — حارس الوحدة لا يغطيها) + اشتقاق حالة العملية طازجة. */
  const noRefBusyRef = useRef(false);
  function currentOpNow() {
    let setup = null;
    try { setup = readPaymentSetup(); } catch (e) { setup = null; }
    /* ★ FE26-§1-req7: فشل التخزين (تصفح خاص)؟ الأحدث في الذاكرة
       (setupRef — محدّثة عند كل بدء/fork/إنشاء) قبل state التنقل الأقدم. */
    if (!setup) {
      try { if (setupRef.current && setupRef.current.purchaseId) setup = setupRef.current; } catch (eR) {}
    }
    if (!setup) {
      try { if (location && location.state && location.state.setup) setup = location.state.setup; } catch (e2) {}
    }
    try { return currentOpFromSetup(setup, customerId); } catch (e3) { return currentOpFromSetup(null, null); }
  }
  /* ★ الحفظ المحلي تعذّر (تصفح خاص)؟ نكمل بالذاكرة مع تحذير صريح:
     إعادة تحميل الصفحة الآن قد تكرّر الطلب — لا تحدّثها. */
  const [volatileSetup, setVolatileSetup] = useState(false);
  const tries = useRef(0);
  const stockRetried = useRef(false);
  const setupRef = useRef(null);
  const customerId = useAppSelector(function (s) {
    return (s.user && s.user.auth && s.user.auth.customerId) || null;
  });
  /* ★ البند 10: لا بدء قبل حسم المصادقة — الهوية المعلّقة تُبقي الانتظار */
  const authResolved = useAppSelector(function (s) {
    return !!((s.user && s.user.auth && s.user.auth.resolved) || false);
  });

  const startFlow = useCallback(function () {
    if (!authResolved) return;
    /* ★ #3: بديل آمن عند فشل الحفظ — state التنقل ثم sessionStorage ثم localStorage.
       لا انتقال لصفحة تعتمد على إعداد فشل حفظه دون بديل. */
    let setup = null;
    try {
      if (location && location.state && location.state.setup) setup = location.state.setup;
    } catch (e) {}
    if (!setup) {
      try {
        const mem = window.sessionStorage.getItem("atyab:paymentSetupMem");
        if (mem) setup = JSON.parse(mem);
      } catch (e) {}
    }
    if (!setup) setup = readPaymentSetup();
    if (location && location.state && location.state.volatile) setVolatileSetup(true);
    if (!setup || !setup.customerId || !setup.orderFields) {
      setPhase("empty");
      return;
    }
    /* ★ البند 19: إعداد دفع محفوظ لحساب آخر لا يُنفَّذ بهوية مختلفة —
       يُمسح ويُطلب البدء من المراجعة بدل إنشاء طلب بهوية أخرى.
       ★ وأي محاولة قديمة تُبطَل فوراً (لا تكمل بهوية منتهية). */
    if (customerId && Number(setup.customerId) !== Number(customerId)) {
      tries.current += 1;
      if (setup.purchaseId) releasePurchaseAttempt(String(setup.purchaseId));
      clearPaymentSetup();
      setPhase("failed");
      setStockFail(false);
      setError("تبدلت الجلسة أثناء تجهيز الدفع — أعد العملية من المراجعة.");
      return;
    }
    setupRef.current = setup;
    tries.current += 1;
    stockRetried.current = false;
    /* ★ FE25-R32-02: محاولة جديدة تبدأ الآن — أبطل رفض المحاولة السابقة
       وخيار تأكيدها فوراً (لا يُستعمل رفض قديم كدليل لعملية أحدث)؛ مجرّد
       إخفاء الرسالة لا يكفي والـhandlers تُعاد تقييمها لحظة التنفيذ. */
    try {
      setReferralExit(null);
      setNoRefArmed(false);
      noRefBusyRef.current = false;
    } catch (eInv) {}
    setPhase("working");
    setFollow(null);
    setError("");
    setAdjustNote("");
    setStockFail(false);
    runOnce();
  }, [customerId, authResolved]);

  /* ★ FE26-§1: كشف الاستجابة المتأخرة لمحاولة أقدم — خانة الإعداد صارت
     لعملية أخرى (fork بلا-إحالة/تبويب أحدث)، أو إرسال أحدث لنفس العملية
     تجاوز هذا الإرسال (تبويبان بنفس الهوية). المتأخرة لا تعدّل التخزين
     ولا اللوحات ولا تغادر المتصفح — ولا تنشئ referralExit صالحاً لعملية
     أحدث. ملاحظة مقصودة: القرار بالهوية والعدّادات لا بالجيل (tries) —
     الـref يتصفّر عند إعادة التركيب فيبقى الجيل مضللاً، والـfork لا يرفعه
     أصلاً؛ الجيل يُمرَّر في السياق للتتبع فقط. */
  function isStaleAttempt(attempt) {
    const a = attempt && typeof attempt === "object" ? attempt : {};
    const pid = a.runPid ? String(a.runPid) : "";
    const mySent = Number(a.sentCount) || 0;
    try {
      const cur = readPaymentSetup();
      if (!cur) return false;
      if (pid && cur.purchaseId && String(cur.purchaseId) !== String(pid)) {
        if (cur.customerId == null || customerId == null || Number(cur.customerId) === Number(customerId)) return true;
      }
      if (mySent > 0 && pid && cur.purchaseId && String(cur.purchaseId) === String(pid)) {
        if ((Number(cur.sentCount) || 0) > mySent) return true;
      }
    } catch (eC) {}
    return false;
  }

  /* محاولة واحدة: طلب ← start ← مغادرة. تُستدعى أول مرة من startFlow
     ومرة ثانية تلقائياً بعد تخفيض الكمية للمتاح (409 قابل للتحليل).
     ★ البند 5: طلب قائم (setup.orderId) لا يُعاد إنشاؤه أبداً — Start فقط،
       فإعادة المحاولة بعد إنشاء ناجح لا تنتج طلباً مكرراً.
     ★ محاولة قديمة لا تُوجّه المتصفح بعد بدء أحدث منها.
     ★ حارس الوحدة (§11): ref وحده لا يكفي — إعادة التركيب/تغيّر الهوية
       يعيدان التشغيل؛ أول مُطالِب بالـpurchaseId يفوز فقط. */
  function runOnce() {
    const setup = setupRef.current;
    if (!setup) {
      setPhase("empty");
      return;
    }
    const myAttempt = tries.current;
    /* ★ FE26-§1: سياق المحاولة الصريح — يُبنى هنا ويُمرَّر param إلى
       onOrderFailed (لا globals ولا مشتركات قابلة للاستبدال، ولا قراءة
       هوية قديمة من أحدث setup). sentCount يُضبط بعد markSetupSent. */
    const attemptCtx = {
      runPid: "",
      runKey: "",
      sentCount: 0,
      generation: myAttempt
    };
    try { attemptCtx.runPid = setup.purchaseId ? String(setup.purchaseId) : ""; } catch (eRP) {}
    try { attemptCtx.runKey = setup.idempotencyKey ? String(setup.idempotencyKey) : ""; } catch (eRK) {}
    const pid = String(setup.purchaseId || "");
    if (pid && !claimPurchaseAttempt(pid)) return;
    function release() {
      if (pid) releasePurchaseAttempt(pid);
    }

    function goPaymentUrl(url, pendingExtra) {
      /* ★ جيل أحدث أو fork أحدث (نفس الجيل بهوية أخرى) = متأخرة: لا مغادرة. */
      try { if (isStaleAttempt(attemptCtx)) { release(); return; } } catch (eSG) {}
      if (myAttempt !== tries.current) return;
      release();
      if (!url) {
        setPhase("failed");
        setStockFail(false);
        setError("أُنشئ طلبك بانتظار الدفع وتعذّر فتح صفحة الدفع — ستجده في «طلباتي» لإكمال الدفع.");
        return;
      }
      savePendingPayment(
        Object.assign(
          {
            customerId: Number(setup.customerId),
            method: setup.method || "",
            customer: setup.customer || {},
            startedAt: Date.now()
          },
          pendingExtra || {}
        )
      );
      clearPaymentSetup();
      window.location.href = url;
    }

    function failMessage(err, fallback) {
      if (err && err.message === "timeout") return "تأخّر الخادم في الرد — تحقق من الاتصال وحاول مجدداً.";
      const data = err && err.response && err.response.data;
      return fullServerMessage(data, err && err.message ? err.message : fallback);
    }

    /* ٢) بدء الدفع لطلب قائم ← { orderId } */
    function startExisting(oid) {
      withTimeout(startServerPayment(Number(setup.customerId), Number(oid)), STEP_TIMEOUT_MS).then(
        function (pay) {
          const url = pay && (pay.paymentUrl || pay.payment_url);
          if (!url) {
            setPhase("failed");
            setStockFail(false);
            setError("أُنشئ طلبك بانتظار الدفع (رقم " + oid + ") وتعذّر فتح صفحة الدفع — ستجده في «طلباتي» لإكمال الدفع.");
            return;
          }
          goPaymentUrl(url, {
            tranRef: String((pay && (pay.tranRef || pay.tran_ref || pay.tranref)) || ""),
            cartId: String((pay && (pay.cartId || pay.cart_id)) || ""),
            orderId: Number(oid),
            /* ★ FE24-F3: اللقطة المرسلة تسافر مع المعلق — صفحة العودة تحسم
               الإسناد الفعلي منها (requested) مقابل صدى التفاصيل. */
            referral: attachedRefOnline
          });
        },
        function (err) {
          release();
          /* ★ FE26: رد start متأخر بعد fork/جيل أحدث — لا يمسح إعداد الأحدث ولا يوجّه. */
          try { if (isStaleAttempt(attemptCtx)) return; } catch (eSt) {}
          /* ★ 409 «مدفوع / غير قابل للدفع» (§10) = أعد قراءة الطلب:
             قائمة «طلباتي» تجلب الحالة المحدّثة من الخادم */
          const data409 = err && err.response && err.response.data;
          const t409 = data409 ? String(data409.detail || data409.message || "") : "";
          if (err && err.status === 409 && /مدفوع|غير قابل للدفع|already paid|not payable/i.test(t409)) {
            clearPaymentSetup();
            dispatch(
              uiActions.toastShown("هذا الطلب مدفوع/مسوّى — ستجد حالته المحدّثة في «طلباتي».")
            );
            navigate(PATHS.profile);
            return;
          }
          /* ★ عملية موجودة أو نتيجتها مجهولة (start_in_progress/start_unknown):
             لا طلب جديد ولا مفتاح جديد أبداً — تابع الطلب نفسه: أعد الاستعلام
             بنفس orderId (resume)، واعرض أن النتيجة مجهولة لا «مدفوع».
             الأكواد أولاً (لا تحليل نص عربي)، والنص احتياط فقط. */
          const followCode = classifyStartFollow(data409);
          if (err && (err.status === 409 || err.status === 202) && followCode) {
            setPhase("follow");
            setStockFail(false);
            setFollow({ orderId: Number(oid), code: followCode });
            setError("");
            return;
          }
          setPhase("failed");
          setStockFail(false);
          setError(failMessage(err, "أُنشئ طلبك بانتظار الدفع (رقم " + oid + ") وتعذّر فتح صفحة الدفع — ستجده في «طلباتي» لإكمال الدفع."));
        }
      );
    }

    /* ١) إنشاء الطلب بالطريقة الإلكترونية — بعد تصريف مزامنة السلة
       حتى لا يتسابق PUT معلّق مع POST الطلب.
       ★ إعادة محاولة لطلب أُنشئ سابقاً (setup.orderId): Start فقط. */
    const existingId = Number(setup.orderId) || 0;
    if (existingId) {
      startExisting(existingId);
      return;
    }
    /* ★ FE23-F1: لقطة الإحالة الملزمة لهذه العملية — من إعداد الدفع
       المحفوظ (Checkout ثبّتها عند بدء العملية) فتُرسل نفسها عند كل
       إنشاء/استئناف؛ إعدادات قديمة بلا لقطة تسلك القراءة التوافقية.
       الفشل يُبقيها لإعادة المحاولة بنفس اللقطة (لا إلحاق لاحق). */
    var attachedRefOnline = null;
    try {
      if (setup && Object.prototype.hasOwnProperty.call(setup, "referral")) attachedRefOnline = normalizeReferralSnapshot(setup.referral);
      else attachedRefOnline = normalizeReferralSnapshot(readValidVisit());
    } catch (eRef) { attachedRefOnline = null; }
    withTimeout(drainSettled(Number((setupRef.current && setupRef.current.customerId) || customerId) || undefined).then(function (sync) {
      /* ★ البند 3: النتيجة بعد الانتظار — فشل صف يوقف الإنشاء */
      if (!sync || !sync.ok) {
        const e = new Error("basket-sync-failed");
        e.basketSync = true;
        throw e;
      }
    /* ★ #2+#3: مفتاح العملية نفسه في كل إعادة (§11) — timeout ثم retry يرد
       بالطلب نفسه بدل التكرار. العرض مفرد OfferId (عقد واحد).
       الرفض الصريح لا يُسقط تلقائياً: عُد للمراجعة للموافقة الصريحة
       (بمفتاح جديد لمدخلات متغيرة) — لا سعر أساسي صامت بنفس المفتاح. */
      let singleOff = 0;
      if (setup.OfferId != null && Number(setup.OfferId)) singleOff = Number(setup.OfferId);
      else if (setup.offerId != null && Number(setup.offerId)) singleOff = Number(setup.offerId);
      else if (Array.isArray(setup.offerIds) && setup.offerIds.length) singleOff = Number(setup.offerIds[0]) || 0;
      else if (setup.orderFields && setup.orderFields.OfferId != null && Number(setup.orderFields.OfferId)) singleOff = Number(setup.orderFields.OfferId);
      const orderBodyForCreate = Object.assign({}, setup.orderFields);
      if (singleOff) orderBodyForCreate.OfferId = Number(singleOff);
      else delete orderBodyForCreate.OfferId;
      /* ★ FE20-2: بوابة الموافقة للمسار الإلكتروني — لا إنشاء بموافقة غائبة
         أو ناقصة (بلا بصمة/إصدار/عملة) أو لا تطابق المدخلات الحالية.
         الإعدادات القديمة (قبل approvalRequired) تسلك المسار السابق. */
      if (setup.approvalRequired) {
        const appr = setup.approval || null;
        let apprOk = false;
        try {
          apprOk = !!(appr && appr.grandTotal != null && appr.basketFingerprint && appr.basketVersion != null && appr.currencyCode && setup.approvalFields &&
            String(canonicalOrderFields(setup.orderFields || {})) === String(setup.approvalFields));
        } catch (eA) { apprOk = false; }
        if (!apprOk) {
          const e = new Error("approval-stale");
          e.approvalStale = true;
          throw e;
        }
      }
      const oidOpt = singleOff ? { idempotencyKey: setup.idempotencyKey || "", offerId: Number(singleOff) } : { idempotencyKey: setup.idempotencyKey || "" };
      if (setup.approval && setup.approval.grandTotal != null) oidOpt.expectedGrandTotal = Number(setup.approval.grandTotal);
      if (setup.approval && setup.approval.basketFingerprint) oidOpt.expectedBasketFingerprint = String(setup.approval.basketFingerprint);
      /* ★ FE20-2: إعادة التحقق من اللقطة الكاملة قبل الإنشاء — أي تغيّر
         (مبلغ/بصمة/إصدار/عملة، ولو بقي الإجمالي نفسه) = إيقاف بلا إنشاء
         صامت، والعودة للمراجعة لموافقة جديدة (لا طلب بديل تلقائي). */
      function quoteFieldsForCreate() {
        const of = setup.orderFields || {};
        return {
          locationId: Number(of.locationId),
          deliveryMethodId: Number(of.deliveryMethodId),
          paymentMethodId: Number(of.paymentMethodId),
          couponCode: of.couponCode ? String(of.couponCode) : null,
          OfferId: singleOff || null
        };
      }
      function doCreate() {
        /* ★ FE23-F1: اللقطة الملزمة خاصية حاضرة دائماً (ولو null) — لا
           قراءة خفية وقت الإرسال.
           ★ FE26-§1: علّم الإرسال الفعلي قبل النداء — sentCount المرتبط
           بهذا الإرسال يُضبط هنا (بعد markSetupSent لا قبلها) ويُمرَّر
           صراحة مع السياق إلى onOrderFailed. */
        try {
          const nx = markSetupSent(attemptCtx.runPid || undefined);
          if (nx) attemptCtx.sentCount = Number(nx.sentCount) || 0;
        } catch (eS) {}
        const createOpts = Object.assign({}, oidOpt, { referral: attachedRefOnline });
        return createServerOrder(Number(setup.customerId), orderBodyForCreate, createOpts);
      }
      if (setup.approval && setup.approval.grandTotal != null) {
        return fetchServerQuote(Number(setup.customerId), quoteFieldsForCreate()).then(function (q) {
          let fresh = null;
          try { fresh = normalizeQuoteTotals(q); } catch (eQ) { fresh = null; }
          if (!fresh || !approvalMatchesQuote(setup.approval, fresh)) {
            const e = new Error("approval-stale");
            e.approvalStale = true;
            e.oldTotal = Number(setup.approval.grandTotal);
            e.newTotal = fresh ? Number(fresh.total) : null;
            throw e;
          }
          return doCreate();
        });
      }
      return doCreate();
    }), STEP_TIMEOUT_MS).then(
      function (srvBill) {
        /* ★ FE26: نجاح متأخر لمحاولة أقدم بعد بدء أحدث — لا حفظ ولا Start ولا مغادرة. */
        try { if (isStaleAttempt(attemptCtx)) { release(); return; } } catch (eStS) {}
        /* ★ إحالة المؤثرين (نجاح): التنظيف باللقطة المُرسلة نفسها فقط —
           إحالة أحدث (ولو بنفس الكود) لا تُمحى. الفشل (onOrderFailed)
           يُبقيها لإعادة المحاولة.
           ★ FE25-R32-03-#5/#9: التنظيف عبر shouldCleanupSent (صدى متناقض
           = إبقاء بلا حذف أعمى — وV2 أثناء V1 لا تُمس). */
        try {
          if (shouldCleanupSent(attachedRefOnline, srvBill)) {
            if (attachedRefOnline.visitId) clearRefIfVisit(attachedRefOnline.visitId);
            else if (attachedRefOnline.code) clearRefIfSame(attachedRefOnline.code);
          }
        } catch (e) {}
        /* ★ المخزون طازج فوراً بعد إنشاء الطلب */
        refreshCatalogStock(dispatch, { force: true });
        const oid = srvBill && (srvBill.orderId != null ? srvBill.orderId : srvBill.order_id);
        if (!oid) {
          release();
          setPhase("failed");
          setStockFail(false);
          setError("أُنشئ طلبك وتعذّر فتح صفحة الدفع — ستجده في «طلباتي».");
          return;
        }
        /* ★ احفظ الطلب فور إنشائه — أي retry بعده Start فقط لا Create.
           الفشل يُبلَّغ (لا ابتلاع): نكمل بالذاكرة مع تحذير «لا تحدّث». */
        const savedSetup = Object.assign({}, setup, { orderId: Number(oid) });
        if (!savePaymentSetup(savedSetup)) setVolatileSetup(true);
        setupRef.current = savedSetup;
        startExisting(oid);
      },
      function (err) {
        release();
        onOrderFailed(err, attemptCtx);
      }
    );
  }

  /* فشل إنشاء الطلب: كوبون ساقط؟ أم 409 مخزون قابل للتحليل؟
     ★ FE26-§1: السياق (attempt) يُمرَّر صراحة من runOnce — الهوية والجيل
     والعدّ من مصدر المحاولة نفسها، لا من التخزين ولا من مشتركات. */
  function onOrderFailed(err, attempt) {
    /* ★ FE25-R32-02: كل خروج بردّ محلول يلحق العدّاد؛ المجهول وحده يتخطى
       (respondKind=null) ليبقى للمصالحة بنفس المفتاح. try/finally يغطي
       كل مسارات العودة المبكرة — ولا يسجّل ردّاً لمحاولة timeout أو متأخرة. */
    var respondKind = "failed";
    var staleResp = false;
    const actx = attempt && typeof attempt === "object" ? attempt : {};
    const aPid = actx.runPid ? String(actx.runPid) : "";
    const aKey = actx.runKey ? String(actx.runKey) : "";
    const aSent = Number(actx.sentCount) || 0;
    try {
    /* ★ FE26-§1-req3: رد متأخر لمحاولة أقدم — لا عدادات ولا رفض ولا رسائل
       فوق الأحدث. يُتجاهل كلياً (مع عدم تسجيل ردّ في finally). */
    try { staleResp = isStaleAttempt(actx); } catch (eSt) { staleResp = false; }
    if (staleResp) { respondKind = null; return; }
    /* ★ البند 3: المزامنة لم تستقر — لا إنشاء؛ عُد للعربة وسوِّها.
       ★ FE26: خطأ محلي قبل الإرسال (لا send في هذه المحاولة) — لا يُسجَّل
       ردّاً في finally حتى لا يمحو مجهولية إرسال سابق. */
    if (err && err.basketSync) {
      respondKind = null;
      setPhase("failed");
      setStockFail(false);
      setError("تعذّرت مزامنة السلة مع الخادم — عُد للعربة واضغط «إعادة المحاولة» ثم أعد الدفع.");
      return;
    }
    /* ★ FE19-3: الموافقة باطلة/المبلغ تغيّر — عُد للمراجعة لموافقة جديدة.
       بلا إنشاء بديل تلقائي وبلا Start. (محلي قبل الإرسال: لا تسجيل ردّ.) */
    if (err && err.approvalStale) {
      respondKind = null;
      setPhase("failed");
      setStockFail(false);
      setError("تغيّر المبلغ أو المدخلات بعد موافقتك" +
        (err.oldTotal != null && err.newTotal != null ? " (" + err.oldTotal + " ← " + err.newTotal + ")" : "") +
        " — عُد للمراجعة وراجع العرض الجديد ووافق مجدداً قبل الإنشاء.");
      return;
    }
    const data = err && err.response && err.response.data;
    const status = err && err.status;
    /* ★ FE25-R32-02-#5: timeout/فقد الرد/408/503/504 محتملة الأثر — احتفظ
       بالمفتاح واللقطة وابدأ المصالحة (إعادة المحاولة هنا تستأنف العملية
       نفسها)، لا مفتاح بديل اعتماداً على رفض أقدم. */
    if (isUnknownOutcome(err)) {
      respondKind = null;
      try { markSetupUnknown(aPid || undefined); } catch (eU) {}
      setPhase("failed");
      setStockFail(false);
      setError("نتيجة طلبك مجهولة (ضاع الرد) — لم يُحسم إنشاء من عدمه. لا تنشئ طلباً جديداً: أعد المحاولة هنا لاستئناف العملية نفسها، أو راجع «طلباتي» لحالتها.");
      return;
    }
    const reason = data && data.reason ? String(data.reason).toUpperCase() : "";
    const isCoupon = COUPON_REASONS.some(function (r) {
      return reason.indexOf(r) !== -1;
    });
    if (isCoupon) {
      dispatch(cartActions.removeCoupon());
      setPhase("failed");
      setStockFail(false);
      setError(fullServerMessage(data, "سقط الكوبون لحظة الطلب — أُكمل بلا خصم أو جرّب كوداً آخر."));
      return;
    }
    /* ★ FE19-3: تعارض العرض/السلة برموز منظمة (بلا regex عربي) — عُد
       للمراجعة لموافقة جديدة. بلا إنشاء بديل تلقائي. */
    const qc = classifyQuoteConflict(data, status);
    if (qc) {
      setPhase("failed");
      setStockFail(false);
      setError((fullServerMessage(data, "تغيّرت السلة أو الأسعار أثناء الإنشاء.") || "تغيّرت السلة أو الأسعار أثناء الإنشاء.") + " — عُد للمراجعة وراجع العرض الجديد ووافق مجدداً قبل الإنشاء. (رمز: " + qc + ")");
      return;
    }
    /* ★ FE24-F4: رفض الإحالة القطعي — مخرج صريح بدل التكرار الأعمى:
       طريق الطلب الأصلي عند consumed، ومتابعة صريحة بلا إحالة بعد
       التأكيد. لم يُنشأ طلب — لا تنظيف، لا بديل تلقائي، لا حلقة.
       ★ FE25-R32-02: الرفض مربوط بهوية المحاولة وعدّ إرسالها — رفض K1
       لا يفتح بوابة لعملية أحدث (K2 مجهولة تُبقي المنع). */
    const rc = classifyReferralConflict(data, status);
    if (rc) {
      let rejOrderId = 0;
      try {
        const dd = data || {};
        rejOrderId = Number(dd.orderId || dd.existingOrderId || dd.consumedByOrderId || dd.order_id) || 0;
      } catch (eO) {}
      const rcMsg = (fullServerMessage(data, "تعذّر إرفاق كود الإحالة.") || "تعذّر إرفاق كود الإحالة.") + " — لم يُنشأ أي طلب ولم تُستهلك إحالة جديدة؛ الإحالة المحفوظة باقية لعملية لاحقة صالحة. (رمز: " + rc + ")";
      try { markSetupRejected(aPid || undefined, rc); } catch (eMR) {}
      respondKind = null; /* سُجّل الردّ عبر markSetupRejected — لا تسجيل مكرر */
      try { noRefBusyRef.current = false; } catch (eB) {}
      setPhase("failed");
      setStockFail(false);
      setError(rcMsg);
      try {
        setReferralExit({ kind: rc, message: rcMsg, orderId: rejOrderId || null, purchaseId: aPid || "", idempotencyKey: aKey || "", sentCount: aSent || 0 });
      } catch (eS) {}
      try { setNoRefArmed(false); } catch (eA2) {}
      return;
    }
    /* ★ منع التكرار (§11): قيد التنفيذ = لا طلب جديد (راجع طلباتي)؛
       ومفتاح لمدخلات مختلفة = عُد للمراجعة لعملية جديدة صريحة. */
    if (status === 409) {
      const conflict = classifyOrderConflict(data);
      if (conflict === "in-progress") {
        setPhase("failed");
        setStockFail(false);
        setError((fullServerMessage(data, "طلبك قيد التنفيذ.") || "طلبك قيد التنفيذ.") + " — لا تنشئ طلباً جديداً؛ ستجده في «طلباتي».");
        return;
      }
      if (conflict === "key-mismatch") {
        setPhase("failed");
        setStockFail(false);
        setError((fullServerMessage(data, "تغيّرت مدخلات الطلب.") || "تغيّرت مدخلات الطلب.") + " — عُد للمراجعة وأكّد مجدداً لبدء عملية جديدة.");
        return;
      }
      if (conflict === "key-reuse") {
        setPhase("failed");
        setStockFail(false);
        setError((fullServerMessage(data, "أُعيد استعمال مفتاح العملية.") || "أُعيد استعمال مفتاح العملية.") + " — استأنف طلبك من «طلباتي» بدل إنشاء جديد.");
        return;
      }
    }
    /* ★ #2: رفض العرض — لا سعر أساسي صامت. عُد للمراجعة للموافقة الصريحة. */
    if (status === 400 && isOfferRejection({ response: { data: data } })) {
      setPhase("failed");
      setStockFail(false);
      setError((fullServerMessage(data, "الخادم رفض سعر العرض.") || "الخادم رفض سعر العرض.") + " — عُد للمراجعة ووافق على السعر الجديد ثم أكّد (بمفتاح جديد).");
      return;
    }
    /* ★ طريقة توصيل مرفوضة (id مجاني/مزور بلا استحقاق = 400): رسالة
       الخادم حرفياً + عودة للمراجعة لإعادة الاختيار — لا علاقة بالمخزون. */
    if (/طريقة التوصيل|delivery ?method|deliverymethod/i.test(fullServerMessage(data, ""))) {
      setPhase("failed");
      setStockFail(false);
      setError(fullServerMessage(data, "طريقة التوصيل مرفوضة من الخادم.") + " — عُد للمراجعة وأعد اختيار سرعة التوصيل.");
      return;
    }
    /* ★ البند 17: المتجر مغلق — لا طلبات جديدة من صفحة قديمة */
    if (/STORE_CLOSED|المتجر مغلق|المحل مغلق|store closed/i.test(fullServerMessage(data, ""))) {
      setPhase("failed");
      setStockFail(false);
      setError("المتجر مغلق حالياً — لا يمكن إنشاء طلبات جديدة الآن.");
      return;
    }
    /* ★ الـ409 يسمّي المنتج والكمية المتاحة في detail — خفّض إليها
       (محلياً + سلة الخادم) ثم أعد إنشاء الطلب تلقائياً، مرة واحدة. */
    const parsed = parseAvailabilityFromPayload(data);
    const target = resolveReduceTarget(parsed);
    if ((status === 409 || status === 400) && target && !stockRetried.current && qtyNeedsCut(target)) {
      stockRetried.current = true;
      applyAvailableAndRetry(target);
      return;
    }
    /* مخزون/تحقق بلا تحليل: اعرض رسالة الخادم الكاملة + إرشاد التخفيض */
    setPhase("failed");
    setStockFail(true);
    setError(
      fullServerMessage(data, "تعذّر إنشاء الطلب — الكمية المطلوبة أكبر من المتاح.") +
      (target
        ? " — " + (target.productName ? "«" + target.productName + "»" : "المنتج " + target.productId) + ": الكمية المتاحة " + target.available + ". خفّض إليها ثم أعد المحاولة."
        : " — خفّض كمية السلة إلى المتاح (راجع DevTools ← Response للنص الكامل) ثم أعد المحاولة.")
    );
    } finally {
      /* ★ FE26-§1-req4: المتأخرة والمجهولة لا تُسجَّلان ردّاً محلولاً —
         التسجيل للمحاولة الجارية بردّ فعلي فقط. */
      try { if (respondKind && !staleResp) markSetupResponded(aPid || undefined); } catch (eM) {}
    }
  }

  /* تحديد الصف المستهدف: المنتج المسمّى (id أو اسم)، وإلا الصف الوحيد إن تجاوز المتاح */
  function normName(s) {
    return String(s || "")
      .replace(/[ً-ٟـ]/g, "")
      .replace(/\s+/g, "")
      .toLowerCase();
  }
  function resolveReduceTarget(parsed) {
    if (!parsed || parsed.available == null) return null;
    const avail = Number(parsed.available);
    if (parsed.productId != null) return { productId: Number(parsed.productId), productName: parsed.productName || "", available: avail };
    const rows = (totals && totals.rows) || [];
    /* ★ الـ409 يسمّي المنتج بالاسم («... من مسك ابيض هي 0 فقط»):
       نطابق الاسم مع أسماء الصفوف (ar/en) */
    if (parsed.productName) {
      const want = normName(parsed.productName);
      if (want.length >= 2) {
        for (let i = 0; i < rows.length; i++) {
          const p = (rows[i] && rows[i].product) || {};
          const cands = [p.name, p.nameEn, p.nameAr, p.titleAr, p.desc];
          for (let j = 0; j < cands.length; j++) {
            const c = normName(cands[j]);
            if (c.length >= 2 && (c.indexOf(want) !== -1 || want.indexOf(c) !== -1)) {
              return { productId: Number(rows[i].id), productName: parsed.productName || "", available: avail };
            }
          }
        }
      }
    }
    if (rows.length === 1 && Number(rows[0].qty) > avail) {
      return { productId: Number(rows[0].id), productName: parsed.productName || "", available: avail };
    }
    return null;
  }

  function qtyNeedsCut(target) {
    if (!target) return false;
    if (target.available < 0) return false;
    let current = null;
    ((totals && totals.rows) || []).forEach(function (r) {
      if (Number(r.id) === Number(target.productId)) current = Number(r.qty);
    });
    if (current == null) return true;
    return current > target.available;
  }

  /* التخفيض + مزامنة الخادم + إعادة تقييم الموافقة (لا إنشاء تلقائي بعد تغيّر) */
  function applyAvailableAndRetry(target) {
    const pid = Number(target.productId);
    const avail = Math.max(0, Math.round(Number(target.available) || 0));
    setAdjustNote(
      avail <= 0
        ? "المنتج " + pid + " نفد مخزونه — أزلناه من العربة. سيُعاد فحص الموافقة قبل أي إنشاء جديد."
        : "خفّضنا المنتج " + pid + " إلى الكمية المتاحة (" + avail + ") — سيُعاد فحص الموافقة قبل أي إنشاء جديد."
    );
    dispatch(
      uiActions.toastShown(
        avail <= 0
          ? "نفد مخزون أحد المنتجات — أُزيل من العربة وسيُعاد فحص الموافقة."
          : "خفّضنا الكمية إلى المتاح (" + avail + ") وسيُعاد فحص الموافقة."
      )
    );
    const synced =
      avail <= 0
        ? dispatch(dropRowEverywhere(pid))
        : (dispatch(cartActions.setQty({ id: pid, qty: avail, max: Math.max(1, avail) })), dispatch(pushRowQty(pid)));
    Promise.resolve(synced).then(
      function () {
        runOnce();
      },
      function () {
        runOnce();
      }
    );
  }

  useEffect(
    function () {
      startFlow();
    },
    [startFlow]
  );

  /* ★ معاينة الإجمالي بسرعة التوصيل المختارة (من إعداد Checkout) —
     تقدير للعرض فقط، والفاتورة الحقيقية من الخادم. */
  const setupTotal = setupRef.current && setupRef.current.viewTotal != null && isFinite(Number(setupRef.current.viewTotal))
    ? Number(setupRef.current.viewTotal)
    : null;

  const waHref =
    support && support.whatsappDigits
      ? "https://wa.me/" + support.whatsappDigits + "?text=" + encodeURIComponent(language === "en" ? "Hello, the payment page did not open and I need help." : "السلام عليكم، تعذّر فتح صفحة الدفع وأحتاج المساعدة.")
      : null;

  /* ---------- بلا إعداد: دخل الرابط مباشرة ---------- */
  if (phase === "empty") {
    return (
      <section className="container view ck ct" id="paymentStartView">
        <div className="ct-empty">
          <span className="ct-empty-ic">
            <Icon name="cart" strokeWidth={1.6} />
          </span>
          <h3>لا يوجد طلب معلّق</h3>
          <p>ابدأ من العربة وأكمل خطوات الدفع — سنجهّز لك صفحة الدفع الآمنة.</p>
          <div className="wl-empty-actions">
            <Link className="btn-primary" to={PATHS.checkout}>
              العودة للمراجعة
            </Link>
            <Link className="btn-ghost" to={PATHS.cart}>
              العربة
            </Link>
          </div>
        </div>
      </section>
    );
  }

  /* ---------- متابعة: عملية موجودة/مجهولة — نفس الطلب، لا جديد ---------- */
  if (phase === "follow" && follow && follow.orderId) {
    const isUnknown = follow.code === "unknown";
    return (
      <section className="container view ck ct" id="paymentStartView">
        <div className="ct-empty">
          <span className="ct-empty-ic">
            <Icon name="info" strokeWidth={1.6} />
          </span>
          <h3>{isUnknown ? "نتيجة الدفع مجهولة — لا نعلن مدفوعاً" : "عملية الدفع قائمة بالفعل"}</h3>
          <p>
            {isUnknown
              ? "طلبك رقم " + follow.orderId + " له عملية دفع نتيجتها غير مؤكدة. سنتابع الطلب نفسه دون إنشاء طلب أو مفتاح جديد."
              : "طلبك رقم " + follow.orderId + " له عملية دفع جارية. تابعها هي نفسها — لا تنشئ طلباً جديداً."}
          </p>
          <div className="wl-empty-actions">
            <button className="btn-primary" type="button" onClick={function () { setPhase("working"); setFollow(null); runOnce(); }}>
              متابعة الطلب نفسه
            </button>
            <Link className="btn-ghost" to={PATHS.profile}>
              طلباتي — حالة الطلب
            </Link>
            <Link className="btn-ghost" to={PATHS.checkout}>
              العودة للمراجعة
            </Link>
          </div>
        </div>
      </section>
    );
  }

  /* ---------- فشل: خطأ واضح + مسارات العودة ---------- */
  if (phase === "failed") {
    return (
      <section className="container view ck ct" id="paymentStartView">
        <div className="ct-empty">
          <span className="ct-empty-ic">
            <Icon name="alert" strokeWidth={1.6} />
          </span>
          <h3>تعذّر فتح صفحة الدفع</h3>
          <p>{error || "حدث خطأ ما — أعد المحاولة لاحقاً أو كلم الدعم."}</p>
          {/* ★ FE24-F4: مخرج رفض الإحالة القطعي — طريق الطلب الأصلي عند
             consumed، ومتابعة صريحة بخطوتين بلا إحالة (عملية جديدة بمفتاح
             جديد + إعادة تحقق الموافقة). لا تلقائية ولا حلقة. */}
          {referralExit ? (
            <div className="ck-skipped" role="alert" style={{ textAlign: "right" }}>
              <b>
                {referralExit.kind === "visit-consumed"
                  ? "هذه الزيارة مرتبطة بطلب آخر."
                  : referralExit.kind === "code-invalid"
                    ? "كود الإحالة مرفوض."
                    : "تعذّر إرفاق الإحالة."}
              </b>
              <p>
                {referralExit.kind === "visit-consumed" && referralExit.orderId ? (
                  <>الطلب الأصلي المرتبط بها رقم <b>{referralExit.orderId}</b>. </>
                ) : null}
                تابع «طلباتي» لحالته، أو تابع بلا إحالة بزر صريح أدناه. (رمز: {referralExit.kind})
              </p>
              <p className="ck-hint">هذا الرفض يخص المحاولة التي فشلت فقط — أي محاولة جديدة تُبطله، ولا يُبنى عليه بديل إلا بعد رفض قطعي للعملية الحالية.</p>
              {gateNoReferralOp(referralExit, currentOpNow()).allowed ? (
                noRefArmed ? (
                  <button
                    className="btn-primary"
                    type="button"
                    onClick={function () {
                      /* ★ FE25-R32-02-#4: إعادة تقييم الحارس لحظة التنفيذ
                         بقراءة تخزين طازجة (ظهر orderId؟ مجهول لاحق؟ رفض
                         لعملية أخرى؟) + منع النقر المزدوج (عملية واحدة
                         بهوية واحدة). */
                      if (noRefBusyRef.current) return;
                      let gate = null;
                      try { gate = gateNoReferralOp(referralExit, currentOpNow()); } catch (eG) { gate = null; }
                      if (!gate || !gate.allowed) {
                        try {
                          if (gate && gate.reason === "resume-order") setError("ظهر طلب قائم — استأنفه من «طلباتي» بدل عملية جديدة.");
                          else if (gate && gate.reason === "unknown-pending") setError("نتيجة العملية الحالية مجهولة — أعد المحاولة هنا لاستئنافها أو راجع «طلباتي» قبل أي بديل.");
                          else setError("انتهت صلاحية هذا الرفض لعملية أحدث — لا بديل يُبنى عليه. راجع «طلباتي».");
                        } catch (eF2) {}
                        return;
                      }
                      const cur = setupRef.current || readPaymentSetup();
                      if (!cur || !cur.customerId || !cur.orderFields) {
                        setPhase("empty");
                        return;
                      }
                      noRefBusyRef.current = true;
                      const ni = newPurchaseIdentity();
                      /* ★ FE25-R32-03-#2/#3: بناء خالص — referral:null مرة
                         واحدة مع هوية جديدة وتصفير العدّادات؛ إعادة المحاولة
                         بعد مجهول تعيد المفتاح نفسه وnull نفسه. */
                      const next = nextNoReferralSetup(cur, ni);
                      if (!savePaymentSetup(next)) {
                        noRefBusyRef.current = false;
                        setError("تعذّر حفظ الإعداد الجديد — عُد للمراجعة وأعد المحاولة.");
                        return;
                      }
                      setupRef.current = next;
                      setReferralExit(null);
                      setNoRefArmed(false);
                      setPhase("working");
                      setFollow(null);
                      setError("");
                      setAdjustNote("");
                      setStockFail(false);
                      runOnce();
                    }}
                  >
                    تأكيد — متابعة بلا إحالة (عملية جديدة)
                  </button>
                ) : (
                  <button className="btn-ghost" type="button" onClick={function () { setNoRefArmed(true); }}>
                    المتابعة بلا إحالة
                  </button>
                )
              ) : null}
            </div>
          ) : null}
          {volatileSetup ? (
            <p className="ck-auth-warn">تعذّر حفظ تقدّم الدفع في المتصفح — أعد المحاولة من هنا مباشرة ولا تُحدّث الصفحة حتى لا يتكرّر الطلب.</p>
          ) : null}
          <div className="wl-empty-actions">
            <button className="btn-primary" type="button" onClick={startFlow}>
              إعادة المحاولة
            </button>
            {stockFail ? (
              <Link className="btn-ghost" to={PATHS.cart}>
                العربة — خفّض الكمية
              </Link>
            ) : null}
            <Link className="btn-ghost" to={PATHS.checkout}>
              العودة للمراجعة
            </Link>
            {waHref ? (
              <a className="btn-ghost" href={waHref} target="_blank" rel="noopener noreferrer">
                كلم الدعم
              </a>
            ) : (
              <Link className="btn-ghost" to={PATHS.contact}>
                كلم الدعم
              </Link>
            )}
          </div>
        </div>
      </section>
    );
  }

  /* ---------- شاشة الانتظار: ما زلت في الموقع ---------- */
  return (
    <section className="container view ck ct" id="paymentStartView">
      <div className="ct-empty">
        <span className="ct-empty-ic" aria-hidden="true">
          <span className="ck-spin" style={{ width: "34px", height: "34px", borderWidth: "4px" }} />
        </span>
        <h3>يتم توجيهك… انتظر قليلاً</h3>
        <p>ما زلت في أطياب الجاسم — نجهّز لك صفحة الدفع الآمنة وسننقلك إليها تلقائياً. لا تغلق الصفحة.</p>
        {adjustNote ? (
          <p className="ct-count" style={{ justifyContent: "center" }}>
            <Icon name="info" strokeWidth={1.8} />
            <span>{adjustNote}</span>
          </p>
        ) : null}
        {totals && totals.count > 0 ? (
          <p className="ct-count" style={{ justifyContent: "center" }}>
            <Icon name="lock" strokeWidth={1.8} />
            <span>
              الإجمالي التقريبي <b><Money sar={setupTotal != null ? setupTotal : totals.total} /></b>
            </span>
          </p>
        ) : null}
        {tries.current > 1 ? (
          <div className="wl-empty-actions">
            <Link className="btn-ghost" to={PATHS.checkout}>
              العودة للمراجعة
            </Link>
          </div>
        ) : null}
      </div>
    </section>
  );
}
